      SEL2                           :	out   STD_ULOGIC := 'L';
      TDI                            :	in    STD_ULOGIC;
      TMS                            :	in    STD_ULOGIC;
      TCK                            :	in    STD_ULOGIC;
      TDO1                           :	in    STD_ULOGIC;
      TDO2                           :	in    STD_ULOGIC);
