use IEEE.STD_LOGIC_1164.all;
library IEEE;
use IEEE.VITAL_Timing.all;


-- entity declaration --
entity BUFGMUX0 is
   generic(
      TimingChecksOn: Boolean := TRUE;
      InstancePath: STRING := "*";
      Xon: Boolean := True;
      MsgOn: Boolean := False;
      tpd_I0_O                        :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_I1_O                        :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_S_O                        :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tipd_S                         :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_I0                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_I1                        :	VitalDelayType01 := (0.000 ns, 0.000 ns));

   port(
      O                              :	out   STD_ULOGIC;
      S                              :	in    STD_ULOGIC;
      I0                             :	in    STD_ULOGIC;
      I1                             :	in    STD_ULOGIC);

attribute VITAL_LEVEL0 of BUFGMUX0 : entity is TRUE;
end BUFGMUX0;

-- architecture body --
library IEEE;
use IEEE.VITAL_Primitives.all;
library UNISIM;
use UNISIM.VPKG.all;
architecture BUFGMUX0_V of BUFGMUX0 is
--   attribute VITAL_LEVEL1 of BUFGMUX0_V : architecture is TRUE;

   SIGNAL S_ipd	 : STD_ULOGIC := 'X';
   SIGNAL I0_ipd	 : STD_ULOGIC := 'X';
   SIGNAL I1_ipd	 : STD_ULOGIC := 'X';

begin

   ---------------------
   --  INPUT PATH DELAYs
   ---------------------
   WireDelay : block
   begin
   VitalWireDelay (S_ipd, S, tipd_S);
   VitalWireDelay (I0_ipd, I0, tipd_I0);
   VitalWireDelay (I1_ipd, I1, tipd_I1);
   end block;
   --------------------
   --  BEHAVIOR SECTION
   --------------------
   VITALBehavior : process 

   -- timing check results

   -- functionality results
   variable O_zd, O1_zd, O2_zd : STD_ULOGIC ;
   --variable Q : STD_LOGIC_VECTOR (1 downto 0) := To_StdLogicVector(INIT);
   variable Q : STD_LOGIC_VECTOR (1 downto 0) := "01" ;
   VARIABLE FIRST_TIME : BOOLEAN := TRUE;

   -- output glitch detection variables
   VARIABLE O_GlitchData	: VitalGlitchDataType;

   begin

      -------------------------
      --  Functionality Section
      -------------------------
      if (FIRST_TIME) then
	  O <= 'L';
          Wait until (falling_edge(I0_ipd ) OR falling_edge(I1_ipd ) );
          FIRST_TIME := FALSE;
      end if;

      if (falling_edge(I0_ipd) = TRUE ) then
         Q(0) := NOT S_ipd AND (NOT Q(1)) ;
      end if;

      if (falling_edge(I1_ipd) = TRUE ) then
         Q(1) := S_ipd  AND (NOT Q(0));
      end if;

      O1_zd := VitalBUFIF1 (data => I0_ipd, enable => Q(0) );
      O2_zd := VitalBUFIF1 (data => I1_ipd, enable => Q(1) );
      O_zd := resolved (O1_zd & O2_zd & 'L');

      ----------------------
      --  Path Delay Section
      ----------------------
      VitalPathDelay01 (
       OutSignal => O,
       GlitchData => O_GlitchData,
       OutSignalName => "O",
       OutTemp => O_zd,
       Paths => (0 => (I0_ipd'last_event, tpd_I0_O, TRUE),
                 1 => (I1_ipd'last_event, tpd_I1_O, TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);

    wait on I0_ipd, I1_ipd;

end process;
  

end BUFGMUX0_V;

configuration CFG_BUFGMUX0_V of BUFGMUX0 is
   for BUFGMUX0_V
   end for;
end CFG_BUFGMUX0_V;
