----- CELL CK_DIV -----
-----------------------------------------------------------------------------
-- Model for XC5200 Oscillator Cell Using User-Supplied clock
--
-- Version 1.0.1
--
-- Dhimant Patel, August 27, 1996.

-- Version 1.0.2, DP, 06/18/97
-- 1. Added wait statements after the assert statements. These are in case
--    the simulator doesn't behave as expected, i.e. doesn't abort.
-----------------------------------------------------------------------------
library IEEE;
use IEEE.std_logic_1164.all;
use IEEE.VITAL_Timing.all;

entity CK_DIV is
    generic ( InstancePath : STRING := "*";
              DIVIDE1_BY : integer := 4;
              DIVIDE2_BY : integer := 2);
    port( C : in std_ulogic := '0'; 
          OSC1 : out std_ulogic := '0'; 
          OSC2 : out std_ulogic := '0'); 
    attribute VITAL_LEVEL0 of CK_DIV : entity is TRUE;
end CK_DIV;

architecture CK_DIV_V of CK_DIV is

attribute VITAL_LEVEL0 of CK_DIV_V : architecture is TRUE;

type DIV1_ARRAY is array (0 to 3) of integer;
type DIV2_ARRAY is array (0 to 7) of integer;

constant DIVISOR1 : DIV1_ARRAY := (4, 16, 64, 256);
constant DIVISOR2 : DIV2_ARRAY := (2, 8, 32, 128, 1024, 4096, 16394, 65536);

constant HALF_DIVIDE1 : integer := (DIVIDE1_BY / 2);
constant HALF_DIVIDE2 : integer := (DIVIDE2_BY / 2);

constant DIV1_ERROR : string := "(4, 16, 64, 256)";
constant DIV2_ERROR : string := "(2, 8, 32, 128, 1024, 4096, 16394, 65536)";

begin

    CLOCK1: process
    variable COUNT1 : integer := 0;
    variable FREQ1 : std_ulogic := '0';
    variable VALID1 : boolean := FALSE;
    begin
        for I1 in DIVISOR1'range loop
            if (DIVIDE1_BY = DIVISOR1(I1)) then
                VALID1 := TRUE;
            end if;
        end loop;
        if (VALID1) then
            wait until (C'event and C = '1');
            COUNT1 := COUNT1 + 1;
            if (COUNT1 = HALF_DIVIDE1) then
                COUNT1 := 0;
                FREQ1 := not FREQ1;
                OSC1 <= FREQ1;
            end if;
        else
            assert FALSE report
            "*** Error: DIVIDE1_BY is not one of " & DIV1_ERROR & " ***"
            severity failure;
            wait;
        end if;
    end process CLOCK1;

    CLOCK2: process
    variable COUNT2 : integer := 0;
    variable FREQ2 : std_ulogic := '0';
    variable VALID2 : boolean := FALSE;
    begin
        for I2 in DIVISOR2'range loop
            if (DIVIDE2_BY = DIVISOR2(I2)) then
                VALID2 := TRUE;
            end if;
        end loop;
        if (VALID2) then
            wait until (C'event and C = '1');
            COUNT2 := COUNT2 + 1;
            if (COUNT2 = HALF_DIVIDE2) then
                COUNT2 := 0;
                FREQ2 := not FREQ2;
                OSC2 <= FREQ2;
            end if;
        else
            assert FALSE report
            "*** Error: DIVIDE2_BY is not one of " & DIV2_ERROR & " ***"
            severity failure;
            wait;
        end if;
    end process CLOCK2;

end CK_DIV_V;

configuration CFG_CK_DIV_V of CK_DIV is
    for CK_DIV_V
    end for;
end CFG_CK_DIV_V;
----- CELL CLKDLL -----
-------------------------------------------------------------------------------
-- Model for Clock Delay Locked Loop
--
-- Version 1.0.6
--
-- Dhimant Patel, November, 1997.
--
-- Version 1.0.7:
--     Added CLK2X90 pin and functionality. Added STARTUP_WAIT generic.
--     Added fractional (e.g. 1.5) divisor functionality.
--     Renamed CLK1X_DUTY generic to DUTY_CYCLE_CORRECTION.
--     Dhimant Patel, March, 1998.
--
-- Version 1.0.8:
--     Removed CLK2X90 pin and functionality. Removed STARTUP_WAIT generic.
--     Dhimant Patel, April, 1998.
-------------------------------------------------------------------------------
library IEEE;
use IEEE.std_logic_1164.all;
use IEEE.VITAL_Timing.all;

library STD;
USE STD.TEXTIO.ALL;

entity CLKDLL is
    generic (TimingChecksOn    : boolean := TRUE;
             InstancePath : STRING := "*";
             Xon               : boolean := TRUE;
             MsgOn             : boolean := FALSE;

             tipd_CLKIN   : VitalDelayType01 := (0.000 ns, 0.000 ns);
             tipd_CLKFB   : VitalDelayType01 := (0.000 ns, 0.000 ns);
             tipd_RST     : VitalDelayType01 := (0.000 ns, 0.000 ns);

             tpd_CLKIN_LOCKED  : VitalDelayType01 := (0.100 ns, 0.100 ns);

             tperiod_CLKIN_POSEDGE     : VitalDelayType  := 0.010 ns;
             MAXPERCLKIN       : time := 100 ns;

             tpw_CLKIN_posedge : VitalDelayType  := 0.010 ns;
             tpw_CLKIN_negedge : VitalDelayType  := 0.010 ns;

             tpw_RST_posedge   : VitalDelayType  := 0.010 ns;

             DUTY_CYCLE_CORRECTION : boolean := TRUE;
             CLKDV_DIVIDE : real := 2.0); 

    port (CLKIN   : in  std_ulogic := '0';
          CLKFB   : in  std_ulogic := '0';
          RST     : in  std_ulogic := '0';
          CLK0    : out std_ulogic := '0';
          CLK90   : out std_ulogic := '0';
          CLK180  : out std_ulogic := '0';
          CLK270  : out std_ulogic := '0';
          CLK2X   : out std_ulogic := '0';
          CLKDV   : out std_ulogic := '0';
          LOCKED  : out std_ulogic := '0');
 
   attribute VITAL_LEVEL0 of CLKDLL : entity is TRUE;

end CLKDLL;
 
architecture CLKDLL_V of CLKDLL is
 
procedure CHECK_DIVISOR (DIVISOR_IN : in real; signal DIVISOR_OUT : out real;
    signal FRACTIONAL : out boolean
) is

type DIVIDE_BY_ARRAY  is array (0 to 7) of real;
constant DIVIDE_BY_LEGAL : DIVIDE_BY_ARRAY := (1.5, 2.0, 2.5, 3.0, 4.0, 5.0, 8.0, 16.0);
constant DIVIDE_BY_ERROR : string := "(1.5, 2.0, 2.5, 3.0, 4.0, 5.0, 8.0, 16.0)";
variable VALID : boolean := FALSE;
variable X     : real    := 0.0;

begin
    for I in DIVIDE_BY_LEGAL'range loop
        if (DIVISOR_IN = DIVIDE_BY_LEGAL(I)) then
            VALID := TRUE;
        end if;
    end loop;

    if (VALID) then
        X := 2.0 * DIVISOR_IN;
        L : loop
           exit when (X < 2.0);
           X := X - 2.0;
        end loop;
        if (X > 0.0) then
            DIVISOR_OUT <= 2.0 * DIVISOR_IN;
            FRACTIONAL  <= TRUE;
        else
            DIVISOR_OUT <= DIVISOR_IN;
        end if;
    else
        assert FALSE report
        "*** Error: CLKDV_DIVIDE is not one of " & DIVIDE_BY_ERROR &
        " , using 2.0 ***"
        severity failure;
        DIVISOR_OUT <= 2.0;
    end if;

end CHECK_DIVISOR;

constant CLKIN_WINDOW_WIDTH : time := 100 ps;
constant CLKFB_WINDOW_WIDTH : time := 100 ps;
constant PERIOD_WINDOW_WIDTH : time := 100 ps;
constant DELAY_DELTA         : time := 1   ns;


signal CLKIN_WINDOW         : std_ulogic := '0';
signal CLKFB_WINDOW         : std_ulogic := '0';
signal WINDOW_OVERLAP       : std_ulogic := '0';

signal CLKIN_ipd, CLKFB_ipd, RST_ipd             : std_ulogic := '0';
signal CLK_0, CLK_5050, CLK_2575, CLK_1X,CLK_2X  : std_ulogic := '0';
signal PERIOD_FOUND, FB_DELAY_FOUND              : std_ulogic := '0';
signal RST_META, LOCKED_INT                      : std_ulogic := '0';
signal DCC                                       : std_ulogic := '1';

signal PERIOD, PERIOD_90, PERIOD_180, PERIOD_270 : time := 0 ps;
signal DELAY, FB_DELAY                           : time := 0 ps;

signal CLKIN_DELAYED_0 : std_ulogic := '0';
signal CLK5050_DELAYED_0, CLK2575_DELAYED_0, CLK5050_DELAYED_90 : std_ulogic := '0';

signal DIVISOR : real := 0.0;
signal IS_FRACTIONAL : boolean := FALSE;

begin

    ---------------------
    --  Wire Delays
    ---------------------
    WireDelay : block
    begin
    VitalWireDelay (CLKIN_ipd, CLKIN, tipd_CLKIN);
    VitalWireDelay (CLKFB_ipd, CLKFB, tipd_CLKFB);
    VitalWireDelay (RST_ipd,   RST,   tipd_RST);
    end block;

    CHECK_DIVISOR (DIVISOR_IN  => CLKDV_DIVIDE,
                   DIVISOR_OUT => DIVISOR,
                   FRACTIONAL  => IS_FRACTIONAL);

    ---------------------------------------------------
    --  Generate Master Reset Signal
    ---------------------------------------------------
    RESET_CLKDLL : process (RST_ipd, CLKIN_ipd)
    variable COUNT_CLKIN : integer := 0;
    variable RST_EVENT   : boolean := FALSE;
    variable Pviol_RST   : STD_ULOGIC := '0';
    variable PInfo_RST   : VitalPeriodDataType := VitalPeriodDataInit;

    begin
            VitalPeriodPulseCheck (
                Violation               => Pviol_RST,
                PeriodData              => PInfo_RST,
                TestSignal              => RST_ipd,
                TestSignalName          => "RST",
                TestDelay               => 0 ns,
                Period                  => 0 ns,
                PulseWidthHigh          => tpw_RST_posedge,
                PulseWidthLow           => 0 ns,
                CheckEnabled            => TRUE,
                HeaderMsg               => InstancePath &"/CLKDLL",
                Xon                     => Xon,
                MsgOn                   => MsgOn,
                MsgSeverity             => WARNING
            );
        if (RST_ipd'event) then
            COUNT_CLKIN := 0;
            RST_EVENT   := TRUE;
        end if;
        if (RST_EVENT) then
            if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                if (COUNT_CLKIN < 1) then
                    COUNT_CLKIN := COUNT_CLKIN + 1;
                else
                    RST_META <= RST_ipd;
                    RST_EVENT := FALSE;
                end if;
            end if;
        end if;
    end process RESET_CLKDLL;

    ---------------------------------------------------
    --  Determine Input Clock Period
    ---------------------------------------------------
    DETERMINE_PERIOD : process
    variable CLKIN_RISE_PREVIOUS, CLKIN_RISE_CURRENT, PERIOD_VAR : time := 0 ps;
    variable PERIOD_PREVIOUS : time := 0 ps;
    variable Pviol_CLKIN : STD_ULOGIC := '0';
    variable PInfo_CLKIN : VitalPeriodDataType := VitalPeriodDataInit;
    variable TEMPLINE : LINE ;
    begin
            VitalPeriodPulseCheck (
                Violation               => Pviol_CLKIN,
                PeriodData              => PInfo_CLKIN,
                TestSignal              => CLKIN_ipd,
                TestSignalName          => "CLKIN",
                TestDelay               => 0 ns,
                Period                  => tperiod_CLKIN_POSEDGE,
                PulseWidthHigh          => tpw_CLKIN_posedge,
                PulseWidthLow           => tpw_CLKIN_negedge,
                CheckEnabled            => TRUE,
                HeaderMsg               => InstancePath &"/CLKDLL",
                Xon                     => Xon,
                MsgOn                   => MsgOn,
                MsgSeverity             => WARNING
            );

        if (RST_META = '1' ) then
            CLKIN_RISE_PREVIOUS := 0 ps;
            CLKIN_RISE_CURRENT  := 0 ps;
            PERIOD_PREVIOUS     := 0 ps;
            PERIOD_VAR          := 0 ps;
            PERIOD              <= 0 ps;
            PERIOD_90           <= 0 ps;
            PERIOD_180          <= 0 ps;
            PERIOD_270          <= 0 ps;
            PERIOD_FOUND        <= '0';
        else
            PERIOD_FOUND <= '0';
            if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                    CLKIN_RISE_PREVIOUS := CLKIN_RISE_CURRENT;
                    CLKIN_RISE_CURRENT  := NOW;
            end if;
            if (CLKIN_RISE_PREVIOUS > 0 ps) then
                PERIOD_PREVIOUS := PERIOD_VAR;
                PERIOD_VAR := CLKIN_RISE_CURRENT - CLKIN_RISE_PREVIOUS;
                if (PERIOD_VAR > PERIOD_PREVIOUS) then
                    if ((PERIOD_VAR - PERIOD_PREVIOUS) < PERIOD_WINDOW_WIDTH) then
                        PERIOD_VAR := PERIOD_PREVIOUS;
                    end if;
                elsif (PERIOD_VAR < PERIOD_PREVIOUS) then
                    if ((PERIOD_PREVIOUS - PERIOD_VAR) < PERIOD_WINDOW_WIDTH) then
                        PERIOD_VAR := PERIOD_PREVIOUS;
                    end if;
                end if;
                if ( PERIOD_VAR > MAXPERCLKIN) then
                    write(TEMPLINE, STRING'("MAXCLKPERIOD VIOLATION ON CLK;"));

                      write(TEMPLINE, LF );
                      write(TEMPLINE, STRING'("Expected := "));
                      write(TEMPLINE, MAXPERCLKIN );
                      write(TEMPLINE, STRING'( "; Observed := "));
                      write(TEMPLINE, PERIOD_VAR);

                    assert FALSE report
                    TEMPLINE.all & ";"
                    severity WARNING;
                    --wait;
                end if;
                PERIOD       <= PERIOD_VAR;
                PERIOD_90    <= PERIOD_VAR * 0.25;
                PERIOD_180   <= PERIOD_VAR * 0.5;
                PERIOD_270   <= PERIOD_VAR * 0.75;
                PERIOD_FOUND <= '1';
            end if;
        end if;

        wait on CLKIN_ipd, RST_META;

    end process DETERMINE_PERIOD;

    ---------------------------------------------------
    --  Determine Feedback Loop Delay
    ---------------------------------------------------
    DETERMINE_FB_DELAY : process (CLKIN_ipd, CLKFB_ipd, RST_META)
    variable TIME_RISE_CLKIN, TIME_RISE_CLKFB : time := 0 ps;
    begin
        if (RST_META'event AND RST_META = '1') then
            TIME_RISE_CLKIN := 0 ps;
            TIME_RISE_CLKFB := 0 ps;
            FB_DELAY_FOUND  <= '0';
            FB_DELAY        <= 0 ps;
        else
             if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                    TIME_RISE_CLKIN := NOW;
             elsif (CLKFB_ipd'event AND CLKFB_ipd = '1') then
                    TIME_RISE_CLKFB := NOW;
             end if;
             if (PERIOD_FOUND = '1' AND FB_DELAY_FOUND = '0' AND TIME_RISE_CLKIN /= 0 ns) then
                if (TIME_RISE_CLKFB > TIME_RISE_CLKIN) then
                    FB_DELAY <= TIME_RISE_CLKFB - TIME_RISE_CLKIN;
                    FB_DELAY_FOUND <= '1';
                end if;
            end if;
        end if;
    end process DETERMINE_FB_DELAY;

    ---------------------------------------------------
    --  Set Lock Delay
    ---------------------------------------------------
    SET_LOCK_DELAY : process (PERIOD, CLKIN_ipd, RST_META)
    variable DELAY_AMOUNT : time := 0 ps;
    variable PERIOD_CHANGED : boolean := FALSE;
    begin
        if (RST_META'event AND RST_META = '1') then
            DELAY   <= 0 ps;
            PERIOD_CHANGED := FALSE;
        elsif (PERIOD'event) then
            PERIOD_CHANGED := TRUE;
        end if;
        if (PERIOD_CHANGED AND FB_DELAY_FOUND = '1') then
            DELAY_AMOUNT := PERIOD - FB_DELAY;
            if ((CLKIN_ipd'event AND CLKIN_ipd = '1') AND LOCKED_INT = '0') then
                if (DELAY_AMOUNT - DELAY > DELAY_DELTA) then
                    DELAY <= DELAY + DELAY_DELTA;
                elsif (DELAY - DELAY_AMOUNT > DELAY_DELTA) then
                    DELAY <= DELAY - DELAY_DELTA;
                else
                    DELAY <= DELAY_AMOUNT;
                end if;
            end if;
        end if;
    end process SET_LOCK_DELAY;

    ---------------------------------------------------
    --  Generate Windows
    ---------------------------------------------------
    GENERATE_WINDOWS : process (CLKIN_ipd, CLKFB_ipd, RST_META)
    begin
        if (RST_META'event AND RST_META = '1') then
            CLKIN_WINDOW <= '0';
            CLKFB_WINDOW <= '0';
        else
            if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                CLKIN_WINDOW <= '1';
                CLKIN_WINDOW <= transport '0' after CLKIN_WINDOW_WIDTH;
            end if;
            if (CLKFB_ipd'event AND CLKFB_ipd = '1') then
                CLKFB_WINDOW <= '1';
                CLKFB_WINDOW <= transport '0' after CLKFB_WINDOW_WIDTH;
            end if;
        end if;
    end process GENERATE_WINDOWS;
 
    WINDOW_OVERLAP <= CLKIN_WINDOW AND CLKFB_WINDOW;
 
    ---------------------------------------------------
    --  Check for a Lock
    ---------------------------------------------------
    DETERMINE_IF_LOCKED : process (CLKIN_ipd, RST_META, WINDOW_OVERLAP)
    variable LOCKED_GlitchData : VitalGlitchDataType;
    variable IS_LOCKED : std_ulogic := '0';
    begin
        if (RST_META'event AND RST_META = '1') then
            LOCKED_INT <= '0';
            IS_LOCKED  := '0';
        elsif (RST_META /= '1' AND (WINDOW_OVERLAP'event AND WINDOW_OVERLAP = '1')) then
            IS_LOCKED := '1';
        elsif (RST_META /= '1' AND (CLKIN_ipd'event AND CLKIN_ipd = '1')) then
            LOCKED_INT<= IS_LOCKED;
            IS_LOCKED := '0';
        end if;
        ----------------------
        --  Path Delay Section
        ----------------------
        VitalPathDelay01 (
            OutSignal  => LOCKED,
            GlitchData => LOCKED_GlitchData,
            OutSignalName => "LOCKED",
            OutTemp => LOCKED_INT,
            Paths => (0 => (CLKIN_ipd'last_event, tpd_CLKIN_LOCKED, TRUE)),
            Mode => OnEvent,
            Xon => Xon,
            MsgOn => MsgOn,
            MsgSeverity => WARNING
        );

    end process DETERMINE_IF_LOCKED;

    ---------------------------------------------------
    --  Generate CLK_5050 and CLK_2575
    ---------------------------------------------------
    GENERATE_CLOCK_5050_AND_CLK2575 : process (CLKIN_ipd, RST_META)
    begin
        if (RST_META'event AND RST_META = '1') then
            CLK_5050 <= '0';
            CLK_2575 <= '0';
        elsif (PERIOD_FOUND = '1') then
            if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                CLK_5050 <= '1';
                CLK_2575 <= '1';
                CLK_5050 <= transport '0' after PERIOD_180;
                CLK_2575 <= transport '0' after PERIOD_90;
            end if;
        end if;
    end process GENERATE_CLOCK_5050_AND_CLK2575;
    
    ---------------------------------------------------
    --  Delay CLKIN and CLK_5050 and CLK_2575 for Locking to CLKFB.
    ---------------------------------------------------
    CLKIN_DELAYED_0   <= transport CLKIN_ipd after DELAY;
    CLK5050_DELAYED_0 <= transport CLK_5050  after DELAY;
    CLK2575_DELAYED_0 <= transport CLK_2575  after DELAY;

    ---------------------------------------------------
    --  CLK0, CLK90, CLK180, CLK270, CLK2X and CLK2X90
    ---------------------------------------------------
    DCC <= '1' when DUTY_CYCLE_CORRECTION else '0';
    
 
    CLK_0   <= (PERIOD_FOUND AND (NOT RST_META))  AND
               (((NOT DCC)   AND CLKIN_DELAYED_0)  OR
               (      DCC    AND CLK5050_DELAYED_0));
    CLK0    <= CLK_0;

    CLK90   <= transport CLK_0 after PERIOD_90;
    CLK180  <= transport CLK_0 after PERIOD_180;
    CLK270  <= transport CLK_0 after PERIOD_270;

    CLK5050_DELAYED_90 <= transport CLK_5050 after (DELAY + PERIOD_90);

    CLK_2X  <= (PERIOD_FOUND AND (NOT RST_META)) AND
               (CLK5050_DELAYED_0 XOR CLK5050_DELAYED_90);
    CLK_1X  <= (PERIOD_FOUND AND (NOT RST_META)) AND CLK2575_DELAYED_0;
    CLK2X   <= (LOCKED_INT AND CLK_2X) OR (NOT LOCKED_INT AND CLK_1X);

    ---------------------------------------------------
    --  Clock Divider
    ---------------------------------------------------
    GENERATE_CLOCK_DIV : process (CLK_2X, RST_META)
    variable FIRST_TIME      : boolean    := TRUE;
    variable COUNT_RISE_FALL : real       := 0.0;
    variable CLOCK_DIV       : std_ulogic := '0';
    begin
        if (RST_META = '1') then
            FIRST_TIME      := TRUE;
            COUNT_RISE_FALL := 0.0;
            CLOCK_DIV       := '0';
        elsif (PERIOD_FOUND = '1') then
            if (CLK_2X'event) then
                if (CLK_2X = '1') then
                    if (FIRST_TIME) then
                        CLOCK_DIV  := NOT CLOCK_DIV;
                        FIRST_TIME := FALSE;
                    else COUNT_RISE_FALL := COUNT_RISE_FALL + 1.0;
                    end if;
                end if;
                if (CLK_2X = '0' AND IS_FRACTIONAL) then
                    COUNT_RISE_FALL := COUNT_RISE_FALL + 1.0;
                end if;
                if (COUNT_RISE_FALL >= DIVISOR) then
                    CLOCK_DIV       := NOT CLOCK_DIV;
                    COUNT_RISE_FALL := 0.0;
                end if;
            end if;
            CLKDV <= CLOCK_DIV;
        end if;
    end process GENERATE_CLOCK_DIV;
end CLKDLL_V;

configuration CFG_CLKDLL_V of CLKDLL is
    for CLKDLL_V
    end for;
end CFG_CLKDLL_V;
----- CELL CLKDLLE -----
-------------------------------------------------------------------------------
-- A V2 Model for Clock Delay Locked Loop
--
-- Version 1.0.0
--
-- Version 1.0.0:
--     Added CLK2X180 pin and functionality. 
--     
--     
--     
--
-- Version 1.0.0:
--     Initial rev.
--     SG, 6/12/99.
-------------------------------------------------------------------------------
library IEEE;
use IEEE.std_logic_1164.all;
use IEEE.VITAL_Timing.all;

library STD;
USE STD.TEXTIO.ALL;

entity CLKDLLE is
    Generic (TimingChecksOn    : boolean := TRUE;
             InstancePath : STRING := "*";
             Xon               : boolean := TRUE;
             MsgOn             : boolean := FALSE;

             tipd_CLKIN   : VitalDelayType01 := (0.000 ns, 0.000 ns);
             tipd_CLKFB   : VitalDelayType01 := (0.000 ns, 0.000 ns);
             tipd_RST     : VitalDelayType01 := (0.000 ns, 0.000 ns);

             tpd_CLKIN_LOCKED  : VitalDelayType01 := (0.100 ns, 0.100 ns);

             tperiod_CLKIN_POSEDGE     : VitalDelayType  := 0.010 ns;
             MAXPERCLKIN       : time := 100 ns;

             tpw_CLKIN_posedge : VitalDelayType  := 0.010 ns;
             tpw_CLKIN_negedge : VitalDelayType  := 0.010 ns;

             tpw_RST_posedge   : VitalDelayType  := 0.010 ns;

             DUTY_CYCLE_CORRECTION : boolean := TRUE;
             CLKDV_DIVIDE : real := 2.0); 

    port (CLKIN   : in  std_ulogic := '0';
          CLKFB   : in  std_ulogic := '0';
          RST     : in  std_ulogic := '0';
          CLK0    : out std_ulogic := '0';
          CLK90   : out std_ulogic := '0';
          CLK180  : out std_ulogic := '0';
          CLK270  : out std_ulogic := '0';
          CLK2X   : out std_ulogic := '0';
          CLK2X180 : out std_ulogic := '0';
          CLKDV   : out std_ulogic := '0';
          LOCKED  : out std_ulogic := '0');
 
   attribute VITAL_LEVEL0 of CLKDLLE : entity is TRUE;

end CLKDLLE;
 
architecture CLKDLLE_V of CLKDLLE is
 
procedure CHECK_DIVISOR (DIVISOR_IN : in real; signal DIVISOR_OUT : out real;
    signal FRACTIONAL : out boolean
) is

type DIVIDE_BY_ARRAY  is array (0 to 21) of real;
constant DIVIDE_BY_LEGAL : DIVIDE_BY_ARRAY := (1.5, 2.0, 2.5, 3.0, 3.5, 4.0, 4.5, 5.0, 5.5, 6.0, 6.5, 7.0, 7.5, 8.0, 9.0, 10.0, 11.0, 12.0, 13.0, 14.0, 15.0, 16.0);
constant DIVIDE_BY_ERROR : string := "(1.5, 2.0, 2.5, 3.0, 3.5, 4.0, 4.5, 5.0, 5.5, 6.0, 6.5, 7.0, 7.5, 8.0, 9.0, 10.0, 11.0, 12.0, 13.0, 14.0, 15.0, 16.0)";
variable VALID : boolean := FALSE;
variable X     : real    := 0.0;

begin
    for I in DIVIDE_BY_LEGAL'range loop
        if (DIVISOR_IN = DIVIDE_BY_LEGAL(I)) then
            VALID := TRUE;
        end if;
    end loop;

    if (VALID) then
        X := 2.0 * DIVISOR_IN;
        L : loop
           exit when (X < 2.0);
           X := X - 2.0;
        end loop;
        if (X > 0.0) then
            DIVISOR_OUT <= 2.0 * DIVISOR_IN;
            FRACTIONAL  <= TRUE;
        else
            DIVISOR_OUT <= DIVISOR_IN;
        end if;
    else
        assert FALSE report
        "*** Error: CLKDV_DIVIDE is not one of " & DIVIDE_BY_ERROR &
        " , using 2.0 ***"
        severity failure;
        DIVISOR_OUT <= 2.0;
    end if;

end CHECK_DIVISOR;

constant CLKIN_WINDOW_WIDTH : time := 100 ps;
constant CLKFB_WINDOW_WIDTH : time := 100 ps;
constant PERIOD_WINDOW_WIDTH : time := 100 ps;
constant DELAY_DELTA         : time := 1   ns;


signal CLKIN_WINDOW         : std_ulogic := '0';
signal CLKFB_WINDOW         : std_ulogic := '0';
signal WINDOW_OVERLAP       : std_ulogic := '0';

signal CLKIN_ipd, CLKFB_ipd, RST_ipd             : std_ulogic := '0';
signal CLK_0, CLK_5050, CLK_2575, CLK_1X,CLK_2X  : std_ulogic := '0';
signal PERIOD_FOUND, FB_DELAY_FOUND              : std_ulogic := '0';
signal RST_META, LOCKED_INT                      : std_ulogic := '0';
signal DCC                                       : std_ulogic := '1';

signal PERIOD, PERIOD_90, PERIOD_180, PERIOD_270 : time := 0 ps;
signal DELAY, FB_DELAY                           : time := 0 ps;

signal CLKIN_DELAYED_0 : std_ulogic := '0';
signal CLK5050_DELAYED_0, CLK2575_DELAYED_0, CLK5050_DELAYED_90 : std_ulogic := '0';
signal CLK2X_INT : std_ulogic := '0';

signal DIVISOR : real := 0.0;
signal IS_FRACTIONAL : boolean := FALSE;

begin

    ---------------------
    --  Wire Delays
    ---------------------
    WireDelay : block
    begin
    VitalWireDelay (CLKIN_ipd, CLKIN, tipd_CLKIN);
    VitalWireDelay (CLKFB_ipd, CLKFB, tipd_CLKFB);
    VitalWireDelay (RST_ipd,   RST,   tipd_RST);
    end block;

    CHECK_DIVISOR (DIVISOR_IN  => CLKDV_DIVIDE,
                   DIVISOR_OUT => DIVISOR,
                   FRACTIONAL  => IS_FRACTIONAL);

    ---------------------------------------------------
    --  Generate Master Reset Signal
    ---------------------------------------------------
    RESET_CLKDLLE : process (RST_ipd, CLKIN_ipd)
    variable COUNT_CLKIN : integer := 0;
    variable RST_EVENT   : boolean := FALSE;
    variable Pviol_RST   : STD_ULOGIC := '0';
    variable PInfo_RST   : VitalPeriodDataType := VitalPeriodDataInit;

    begin
        --if(TimingChecksOn) then
            VitalPeriodPulseCheck (
                Violation               => Pviol_RST,
                PeriodData              => PInfo_RST,
                TestSignal              => RST_ipd,
                TestSignalName          => "RST",
                TestDelay               => 0 ns,
                Period                  => 0 ns,
                PulseWidthHigh          => tpw_RST_posedge,
                PulseWidthLow           => 0 ns,
                CheckEnabled            => TRUE,
                HeaderMsg               => InstancePath &"/CLKDLLE",
                Xon                     => Xon,
                MsgOn                   => MsgOn,
                MsgSeverity             => WARNING
            );
        --end if;
        if (RST_ipd'event) then
            COUNT_CLKIN := 0;
            RST_EVENT   := TRUE;
        end if;
        if (RST_EVENT) then
            if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                if (COUNT_CLKIN < 1) then
                    COUNT_CLKIN := COUNT_CLKIN + 1;
                else
                    RST_META <= RST_ipd;
                    RST_EVENT := FALSE;
                end if;
            end if;
        end if;
    end process RESET_CLKDLLE;

    ---------------------------------------------------
    --  Determine Input Clock Period
    ---------------------------------------------------
    DETERMINE_PERIOD : process
    variable CLKIN_RISE_PREVIOUS, CLKIN_RISE_CURRENT, PERIOD_VAR : time := 0 ps;
    variable PERIOD_PREVIOUS : time := 0 ps;
    variable Pviol_CLKIN : STD_ULOGIC := '0';
    variable PInfo_CLKIN : VitalPeriodDataType := VitalPeriodDataInit;
    variable TEMPLINE : LINE ;
    begin
        --if(TimingChecksOn) then
            VitalPeriodPulseCheck (
                Violation               => Pviol_CLKIN,
                PeriodData              => PInfo_CLKIN,
                TestSignal              => CLKIN_ipd,
                TestSignalName          => "CLKIN",
                TestDelay               => 0 ns,
                Period                  => tperiod_CLKIN_POSEDGE,
                PulseWidthHigh          => tpw_CLKIN_posedge,
                PulseWidthLow           => tpw_CLKIN_negedge,
                CheckEnabled            => TRUE,
                HeaderMsg               => InstancePath &"/CLKDLLE",
                Xon                     => Xon,
                MsgOn                   => MsgOn,
                MsgSeverity             => WARNING
            );
        --end if;

        if (RST_META = '1' ) then
            CLKIN_RISE_PREVIOUS := 0 ps;
            CLKIN_RISE_CURRENT  := 0 ps;
            PERIOD_PREVIOUS     := 0 ps;
            PERIOD_VAR          := 0 ps;
            PERIOD              <= 0 ps;
            PERIOD_90           <= 0 ps;
            PERIOD_180          <= 0 ps;
            PERIOD_270          <= 0 ps;
            PERIOD_FOUND        <= '0';
        else
            PERIOD_FOUND <= '0';
            if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                    CLKIN_RISE_PREVIOUS := CLKIN_RISE_CURRENT;
                    CLKIN_RISE_CURRENT  := NOW;
            end if;
            if (CLKIN_RISE_PREVIOUS > 0 ps) then
                PERIOD_PREVIOUS := PERIOD_VAR;
                PERIOD_VAR := CLKIN_RISE_CURRENT - CLKIN_RISE_PREVIOUS;
                if (PERIOD_VAR > PERIOD_PREVIOUS) then
                    if ((PERIOD_VAR - PERIOD_PREVIOUS) < PERIOD_WINDOW_WIDTH) then
                        PERIOD_VAR := PERIOD_PREVIOUS;
                    end if;
                elsif (PERIOD_VAR < PERIOD_PREVIOUS) then
                    if ((PERIOD_PREVIOUS - PERIOD_VAR) < PERIOD_WINDOW_WIDTH) then
                        PERIOD_VAR := PERIOD_PREVIOUS;
                    end if;
                end if;
                if (PERIOD_VAR > MAXPERCLKIN) then
                    write(TEMPLINE, STRING'("MAXCLKPERIOD VIOLATION ON CLK;"));

                      write(TEMPLINE, LF );
                      write(TEMPLINE, STRING'("Expected := "));
                      write(TEMPLINE, MAXPERCLKIN );
                      write(TEMPLINE, STRING'( "; Observed := "));
                      write(TEMPLINE, PERIOD_VAR);

                    assert FALSE report
                    TEMPLINE.all & ";"
--                    "*** Warning: Input clock frequency is too low *** "
                    severity WARNING;
                    --wait;
                end if;
                PERIOD       <= PERIOD_VAR;
                PERIOD_90    <= PERIOD_VAR * 0.25;
                PERIOD_180   <= PERIOD_VAR * 0.5;
                PERIOD_270   <= PERIOD_VAR * 0.75;
                PERIOD_FOUND <= '1';
            end if;
        end if;

        wait on CLKIN_ipd, RST_META;

    end process DETERMINE_PERIOD;

    ---------------------------------------------------
    --  Determine Feedback Loop Delay
    ---------------------------------------------------
    DETERMINE_FB_DELAY : process (CLKIN_ipd, CLKFB_ipd, RST_META)
    variable TIME_RISE_CLKIN, TIME_RISE_CLKFB : time := 0 ps;
    begin
        if (RST_META'event AND RST_META = '1') then
            TIME_RISE_CLKIN := 0 ps;
            TIME_RISE_CLKFB := 0 ps;
            FB_DELAY_FOUND  <= '0';
            FB_DELAY        <= 0 ps;
        else
             if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                    TIME_RISE_CLKIN := NOW;
             elsif (CLKFB_ipd'event AND CLKFB_ipd = '1') then
                    TIME_RISE_CLKFB := NOW;
             end if;
             if (PERIOD_FOUND = '1' AND FB_DELAY_FOUND = '0' AND TIME_RISE_CLKIN /= 0 ns) then
                if (TIME_RISE_CLKFB > TIME_RISE_CLKIN) then
                    FB_DELAY <= TIME_RISE_CLKFB - TIME_RISE_CLKIN;
                    FB_DELAY_FOUND <= '1';
                end if;
            end if;
        end if;
    end process DETERMINE_FB_DELAY;

    ---------------------------------------------------
    --  Set Lock Delay
    ---------------------------------------------------
    SET_LOCK_DELAY : process (PERIOD, CLKIN_ipd, RST_META)
    variable DELAY_AMOUNT : time := 0 ps;
    variable PERIOD_CHANGED : boolean := FALSE;
    begin
        if (RST_META'event AND RST_META = '1') then
            DELAY   <= 0 ps;
            PERIOD_CHANGED := FALSE;
        elsif (PERIOD'event) then
            PERIOD_CHANGED := TRUE;
        end if;
        if (PERIOD_CHANGED AND FB_DELAY_FOUND = '1') then
            DELAY_AMOUNT := PERIOD - FB_DELAY;
            if ((CLKIN_ipd'event AND CLKIN_ipd = '1') AND LOCKED_INT = '0') then
                if (DELAY_AMOUNT - DELAY > DELAY_DELTA) then
                    DELAY <= DELAY + DELAY_DELTA;
                elsif (DELAY - DELAY_AMOUNT > DELAY_DELTA) then
                    DELAY <= DELAY - DELAY_DELTA;
                else
                    DELAY <= DELAY_AMOUNT;
                end if;
            end if;
        end if;
    end process SET_LOCK_DELAY;

    ---------------------------------------------------
    --  Generate Windows
    ---------------------------------------------------
    GENERATE_WINDOWS : process (CLKIN_ipd, CLKFB_ipd, RST_META)
    begin
        if (RST_META'event AND RST_META = '1') then
            CLKIN_WINDOW <= '0';
            CLKFB_WINDOW <= '0';
        else
            if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                CLKIN_WINDOW <= '1';
                CLKIN_WINDOW <= transport '0' after CLKIN_WINDOW_WIDTH;
            end if;
            if (CLKFB_ipd'event AND CLKFB_ipd = '1') then
                CLKFB_WINDOW <= '1';
                CLKFB_WINDOW <= transport '0' after CLKFB_WINDOW_WIDTH;
            end if;
        end if;
    end process GENERATE_WINDOWS;
 
    WINDOW_OVERLAP <= CLKIN_WINDOW AND CLKFB_WINDOW;
 
    ---------------------------------------------------
    --  Check for a Lock
    ---------------------------------------------------
    DETERMINE_IF_LOCKED : process (CLKIN_ipd, RST_META, WINDOW_OVERLAP)
    variable LOCKED_GlitchData : VitalGlitchDataType;
    variable IS_LOCKED : std_ulogic := '0';
    begin
        if (RST_META'event AND RST_META = '1') then
            LOCKED_INT <= '0';
            IS_LOCKED  := '0';
        elsif (RST_META /= '1' AND (WINDOW_OVERLAP'event AND WINDOW_OVERLAP = '1')) then
            IS_LOCKED := '1';
        elsif (RST_META /= '1' AND (CLKIN_ipd'event AND CLKIN_ipd = '1')) then
            LOCKED_INT<= IS_LOCKED;
            IS_LOCKED := '0';
        end if;
        ----------------------
        --  Path Delay Section
        ----------------------
        VitalPathDelay01 (
            OutSignal  => LOCKED,
            GlitchData => LOCKED_GlitchData,
            OutSignalName => "LOCKED",
            OutTemp => LOCKED_INT,
            Paths => (0 => (CLKIN_ipd'last_event, tpd_CLKIN_LOCKED, TRUE)),
            Mode => OnEvent,
            Xon => Xon,
            MsgOn => MsgOn,
            MsgSeverity => WARNING
        );

    end process DETERMINE_IF_LOCKED;

    ---------------------------------------------------
    --  Generate CLK_5050 and CLK_2575
    ---------------------------------------------------
    GENERATE_CLOCK_5050_AND_CLK2575 : process (CLKIN_ipd, RST_META)
    begin
        if (RST_META'event AND RST_META = '1') then
            CLK_5050 <= '0';
            CLK_2575 <= '0';
        elsif (PERIOD_FOUND = '1') then
            if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                CLK_5050 <= '1';
                CLK_2575 <= '1';
                CLK_5050 <= transport '0' after PERIOD_180;
                CLK_2575 <= transport '0' after PERIOD_90;
            end if;
        end if;
    end process GENERATE_CLOCK_5050_AND_CLK2575;
    
    ---------------------------------------------------
    --  Delay CLKIN and CLK_5050 and CLK_2575 for Locking to CLKFB.
    ---------------------------------------------------
    CLKIN_DELAYED_0   <= transport CLKIN_ipd after DELAY;
    CLK5050_DELAYED_0 <= transport CLK_5050  after DELAY;
    CLK2575_DELAYED_0 <= transport CLK_2575  after DELAY;

    ---------------------------------------------------
    --  CLK0, CLK90, CLK180, CLK270, CLK2X and CLK2X90
    ---------------------------------------------------
    DCC <= '1' when DUTY_CYCLE_CORRECTION else '0';
    
 
    CLK_0   <= (PERIOD_FOUND AND (NOT RST_META))  AND
               (((NOT DCC)   AND CLKIN_DELAYED_0)  OR
               (      DCC    AND CLK5050_DELAYED_0));
    CLK0    <= CLK_0;

    CLK90   <= transport CLK_0 after PERIOD_90;
    CLK180  <= transport CLK_0 after PERIOD_180;
    CLK270  <= transport CLK_0 after PERIOD_270;

    CLK5050_DELAYED_90 <= transport CLK_5050 after (DELAY + PERIOD_90);

    CLK_2X  <= (PERIOD_FOUND AND (NOT RST_META)) AND
               (CLK5050_DELAYED_0 XOR CLK5050_DELAYED_90);
    CLK_1X  <= (PERIOD_FOUND AND (NOT RST_META)) AND CLK2575_DELAYED_0;
    CLK2X_INT   <= (LOCKED_INT AND CLK_2X) OR (NOT LOCKED_INT AND CLK_1X);
    CLK2X <= CLK2X_INT;
    CLK2X180 <= transport CLK2X_INT after PERIOD_90;

    ---------------------------------------------------
    --  Clock Divider
    ---------------------------------------------------
    GENERATE_CLOCK_DIV : process (CLK_2X, RST_META)
    variable FIRST_TIME      : boolean    := TRUE;
    variable COUNT_RISE_FALL : real       := 0.0;
    variable CLOCK_DIV       : std_ulogic := '0';
    begin
        if (RST_META = '1') then
            FIRST_TIME      := TRUE;
            COUNT_RISE_FALL := 0.0;
            CLOCK_DIV       := '0';
        elsif (PERIOD_FOUND = '1') then
            if (CLK_2X'event) then
                if (CLK_2X = '1') then
                    if (FIRST_TIME) then
                        CLOCK_DIV  := NOT CLOCK_DIV;
                        FIRST_TIME := FALSE;
                    else COUNT_RISE_FALL := COUNT_RISE_FALL + 1.0;
                    end if;
                end if;
                if (CLK_2X = '0' AND IS_FRACTIONAL) then
                    COUNT_RISE_FALL := COUNT_RISE_FALL + 1.0;
                end if;
                if (COUNT_RISE_FALL >= DIVISOR) then
                    CLOCK_DIV       := NOT CLOCK_DIV;
                    COUNT_RISE_FALL := 0.0;
                end if;
            end if;
            CLKDV <= CLOCK_DIV;
        end if;
    end process GENERATE_CLOCK_DIV;
end CLKDLLE_V;

configuration CFG_CLKDLLE_V of CLKDLLE is
    for CLKDLLE_V
    end for;
end CFG_CLKDLLE_V;
----- CELL CLKDLLHF -----
-------------------------------------------------------------------------------
-- Model for Clock Delay Locked Loop
--
-- Version 1.0.6
--
-- Dhimant Patel, November, 1997.
--
-- Version 1.0.7:
--     Added STARTUP_WAIT generic.
--     Added fractional (e.g. 1.5) divisor functionality.
--     Renamed CLK1X_DUTY generic to DUTY_CYCLE_CORRECTION.
--     Dhimant Patel, March, 1998.
--
-- Version 1.0.8:
--     Removed STARTUP_WAIT generic.
--     Dhimant Patel, April, 1998.
-------------------------------------------------------------------------------
library IEEE;
use IEEE.std_logic_1164.all;
use IEEE.VITAL_Timing.all;

library STD;
USE STD.TEXTIO.ALL;

entity CLKDLLHF is
    generic (TimingChecksOn    : boolean := TRUE;
             InstancePath : STRING := "*";
             Xon               : boolean := TRUE;
             MsgOn             : boolean := FALSE;

             tipd_CLKIN   : VitalDelayType01 := (0.000 ns, 0.000 ns);
             tipd_CLKFB   : VitalDelayType01 := (0.000 ns, 0.000 ns);
             tipd_RST     : VitalDelayType01 := (0.000 ns, 0.000 ns);

             tpd_CLKIN_LOCKED  : VitalDelayType01 := (0.100 ns, 0.100 ns);

             tperiod_CLKIN_POSEDGE     : VitalDelayType  := 0.010 ns;
             MAXPERCLKIN       : time := 100 ns;

             tpw_CLKIN_posedge : VitalDelayType  := 0.010 ns;
             tpw_CLKIN_negedge : VitalDelayType  := 0.010 ns;

             tpw_RST_posedge   : VitalDelayType  := 0.010 ns;

             DUTY_CYCLE_CORRECTION : boolean := TRUE;
             CLKDV_DIVIDE : real := 2.0); 

    port (CLKIN  : in  std_ulogic := '0';
          CLKFB  : in  std_ulogic := '0';
          RST    : in  std_ulogic := '0';
          CLK0   : out std_ulogic := '0';
          CLK180 : out std_ulogic := '0';
          CLKDV  : out std_ulogic := '0';
          LOCKED : out std_ulogic := '0');
 
    attribute VITAL_LEVEL0 of CLKDLLHF : entity is TRUE;

end CLKDLLHF;
 
architecture CLKDLLHF_V of CLKDLLHF is
 
procedure CHECK_DIVISOR (DIVISOR_IN : in real; signal DIVISOR_OUT : out real;
    signal FRACTIONAL : out boolean
) is

type DIVIDE_BY_ARRAY  is array (0 to 7) of real;
constant DIVIDE_BY_LEGAL : DIVIDE_BY_ARRAY := (1.5, 2.0, 2.5, 3.0, 4.0, 5.0, 8.0, 16.0);
constant DIVIDE_BY_ERROR : string := "(1.5, 2.0, 2.5, 3.0, 4.0, 5.0, 8.0, 16.0)";
variable VALID : boolean := FALSE;
variable X     : real    := 0.0;

begin
    for I in DIVIDE_BY_LEGAL'range loop
        if (DIVISOR_IN = DIVIDE_BY_LEGAL(I)) then
            VALID := TRUE;
        end if;
    end loop;

    if (VALID) then
        X := 2.0 * DIVISOR_IN;
        L : loop
           exit when (X < 2.0);
           X := X - 2.0;
        end loop;
        if (X > 0.0) then
            DIVISOR_OUT <= 2.0 * DIVISOR_IN;
            FRACTIONAL  <= TRUE;
        else
            DIVISOR_OUT <= DIVISOR_IN;
        end if;
    else
        assert FALSE report
        "*** Error: CLKDV_DIVIDE is not one of " & DIVIDE_BY_ERROR &
        " , using 2.0 ***"
        severity failure;
        DIVISOR_OUT <= 2.0;
    end if;

end CHECK_DIVISOR;

constant CLKIN_WINDOW_WIDTH : time := 100 ps;
constant CLKFB_WINDOW_WIDTH : time := 100 ps;
constant PERIOD_WINDOW_WIDTH : time := 100 ps;
constant DELAY_DELTA         : time := 1   ns;


signal CLKIN_WINDOW         : std_ulogic := '0';
signal CLKFB_WINDOW         : std_ulogic := '0';
signal WINDOW_OVERLAP       : std_ulogic := '0';

signal CLKIN_ipd, CLKFB_ipd, RST_ipd             : std_ulogic := '0';
signal CLK_0, CLK_5050, CLK_2X  : std_ulogic := '0';
signal PERIOD_FOUND, FB_DELAY_FOUND              : std_ulogic := '0';
signal RST_META, LOCKED_INT                      : std_ulogic := '0';
signal DCC                                       : std_ulogic := '1';

signal PERIOD, PERIOD_90, PERIOD_180             : time := 0 ps;
signal DELAY, FB_DELAY                           : time := 0 ps;

signal CLKIN_DELAYED_0 : std_ulogic := '0';
signal CLK5050_DELAYED_0, CLK5050_DELAYED_90 : std_ulogic := '0';

signal DIVISOR : real := 0.0;
signal IS_FRACTIONAL : boolean := FALSE;

begin

    ---------------------
    --  Wire Delays
    ---------------------
    WireDelay : block
    begin
    VitalWireDelay (CLKIN_ipd, CLKIN, tipd_CLKIN);
    VitalWireDelay (CLKFB_ipd, CLKFB, tipd_CLKFB);
    VitalWireDelay (RST_ipd,   RST,   tipd_RST);
    end block;

    CHECK_DIVISOR (DIVISOR_IN  => CLKDV_DIVIDE,
                   DIVISOR_OUT => DIVISOR,
                   FRACTIONAL  => IS_FRACTIONAL);

    ---------------------------------------------------
    --  Generate Master Reset Signal
    ---------------------------------------------------
    RESET_CLKDLLHF : process (RST_ipd, CLKIN_ipd)
    variable COUNT_CLKIN : integer := 0;
    variable RST_EVENT   : boolean := FALSE;
    variable Pviol_RST   : STD_ULOGIC := '0';
    variable PInfo_RST   : VitalPeriodDataType := VitalPeriodDataInit;

    begin
        --if(TimingChecksOn) then
            VitalPeriodPulseCheck (
                Violation               => Pviol_RST,
                PeriodData              => PInfo_RST,
                TestSignal              => RST_ipd,
                TestSignalName          => "RST",
                TestDelay               => 0 ns,
                Period                  => 0 ns,
                PulseWidthHigh          => tpw_RST_posedge,
                PulseWidthLow           => 0 ns,
                CheckEnabled            => TRUE,
                HeaderMsg               => InstancePath &"/CLKDLLHF",
                Xon                     => Xon,
                MsgOn                   => MsgOn,
                MsgSeverity             => WARNING
            );
        --end if;
        if (RST_ipd'event) then
            COUNT_CLKIN := 0;
            RST_EVENT   := TRUE;
        end if;
        if (RST_EVENT) then
            if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                if (COUNT_CLKIN < 1) then
                    COUNT_CLKIN := COUNT_CLKIN + 1;
                else
                    RST_META <= RST_ipd;
                    RST_EVENT := FALSE;
                end if;
            end if;
        end if;
    end process RESET_CLKDLLHF;

    ---------------------------------------------------
    --  Determine Input Clock Period
    ---------------------------------------------------
    DETERMINE_PERIOD : process
    variable CLKIN_RISE_PREVIOUS, CLKIN_RISE_CURRENT, PERIOD_VAR : time := 0 ps;
    variable PERIOD_PREVIOUS : time := 0 ps;
    variable Pviol_CLKIN : STD_ULOGIC := '0';
    variable PInfo_CLKIN : VitalPeriodDataType := VitalPeriodDataInit;
    variable TEMPLINE : LINE ;
    begin
        --if(TimingChecksOn) then
            VitalPeriodPulseCheck (
                Violation               => Pviol_CLKIN,
                PeriodData              => PInfo_CLKIN,
                TestSignal              => CLKIN_ipd,
                TestSignalName          => "CLKIN",
                TestDelay               => 0 ns,
                Period                  => tperiod_CLKIN_POSEDGE,
                PulseWidthHigh          => tpw_CLKIN_posedge,
                PulseWidthLow           => tpw_CLKIN_negedge,
                CheckEnabled            => TRUE,
                HeaderMsg               => InstancePath &"/CLKDLLHF",
                Xon                     => Xon,
                MsgOn                   => MsgOn,
                MsgSeverity             => WARNING
            );
        --end if;

        if (RST_META = '1' ) then
            CLKIN_RISE_PREVIOUS := 0 ps;
            CLKIN_RISE_CURRENT  := 0 ps;
            PERIOD_PREVIOUS     := 0 ps;
            PERIOD_VAR          := 0 ps;
            PERIOD              <= 0 ps;
            PERIOD_90           <= 0 ps;
            PERIOD_180          <= 0 ps;
            PERIOD_FOUND        <= '0';
        else
            PERIOD_FOUND <= '0';
            if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                    CLKIN_RISE_PREVIOUS := CLKIN_RISE_CURRENT;
                    CLKIN_RISE_CURRENT  := NOW;
            end if;
            if (CLKIN_RISE_PREVIOUS > 0 ps) then
                PERIOD_PREVIOUS := PERIOD_VAR;
                PERIOD_VAR := CLKIN_RISE_CURRENT - CLKIN_RISE_PREVIOUS;
                if (PERIOD_VAR > PERIOD_PREVIOUS) then
                    if ((PERIOD_VAR - PERIOD_PREVIOUS) < PERIOD_WINDOW_WIDTH) then
                        PERIOD_VAR := PERIOD_PREVIOUS;
                    end if;
                elsif (PERIOD_VAR < PERIOD_PREVIOUS) then
                    if ((PERIOD_PREVIOUS - PERIOD_VAR) < PERIOD_WINDOW_WIDTH) then
                        PERIOD_VAR := PERIOD_PREVIOUS;
                    end if;
                end if;
                if (PERIOD_VAR > MAXPERCLKIN) then
                   write(TEMPLINE, STRING'("MAXCLKPERIOD VIOLATION ON CLK;"));

                      write(TEMPLINE, LF );
                      write(TEMPLINE, STRING'("Expected := "));
                      write(TEMPLINE, MAXPERCLKIN );
                      write(TEMPLINE, STRING'( "; Observed := "));
                      write(TEMPLINE, PERIOD_VAR);

                    assert FALSE report
                    TEMPLINE.all & ";"
--                    "*** Warning: Input clock frequency is too low *** "
                    severity WARNING;
                    --wait;
                end if;
                PERIOD       <= PERIOD_VAR;
                PERIOD_90    <= PERIOD_VAR * 0.25;
                PERIOD_180   <= PERIOD_VAR * 0.5;
                PERIOD_FOUND <= '1';
            end if;
        end if;

        wait on CLKIN_ipd, RST_META;

    end process DETERMINE_PERIOD;

    ---------------------------------------------------
    --  Determine Feedback Loop Delay
    ---------------------------------------------------
    DETERMINE_FB_DELAY : process (CLKIN_ipd, CLKFB_ipd, RST_META)
    variable TIME_RISE_CLKIN, TIME_RISE_CLKFB : time := 0 ps;
    begin
        if (RST_META'event AND RST_META = '1') then
            TIME_RISE_CLKIN := 0 ps;
            TIME_RISE_CLKFB := 0 ps;
            FB_DELAY_FOUND  <= '0';
            FB_DELAY        <= 0 ps;
        else
             if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                    TIME_RISE_CLKIN := NOW;
             elsif (CLKFB_ipd'event AND CLKFB_ipd = '1') then
                    TIME_RISE_CLKFB := NOW;
             end if;
             if (PERIOD_FOUND = '1' AND FB_DELAY_FOUND = '0' AND TIME_RISE_CLKIN /= 0 ns) then
                if (TIME_RISE_CLKFB > TIME_RISE_CLKIN) then
                    FB_DELAY <= TIME_RISE_CLKFB - TIME_RISE_CLKIN;
                    FB_DELAY_FOUND <= '1';
                end if;
            end if;
        end if;
    end process DETERMINE_FB_DELAY;

    ---------------------------------------------------
    --  Set Lock Delay
    ---------------------------------------------------
    SET_LOCK_DELAY : process (PERIOD, CLKIN_ipd, RST_META)
    variable DELAY_AMOUNT : time := 0 ps;
    variable PERIOD_CHANGED : boolean := FALSE;
    begin
        if (RST_META'event AND RST_META = '1') then
            DELAY   <= 0 ps;
            PERIOD_CHANGED := FALSE;
        elsif (PERIOD'event) then
            PERIOD_CHANGED := TRUE;
        end if;
        if (PERIOD_CHANGED AND FB_DELAY_FOUND = '1') then
            DELAY_AMOUNT := PERIOD - FB_DELAY;
            if ((CLKIN_ipd'event AND CLKIN_ipd = '1') AND LOCKED_INT = '0') then
                if (DELAY_AMOUNT - DELAY > DELAY_DELTA) then
                    DELAY <= DELAY + DELAY_DELTA;
                elsif (DELAY - DELAY_AMOUNT > DELAY_DELTA) then
                    DELAY <= DELAY - DELAY_DELTA;
                else
                    DELAY <= DELAY_AMOUNT;
                end if;
            end if;
        end if;
    end process SET_LOCK_DELAY;

    ---------------------------------------------------
    --  Generate Windows
    ---------------------------------------------------
    GENERATE_WINDOWS : process (CLKIN_ipd, CLKFB_ipd, RST_META)
    begin
        if (RST_META'event AND RST_META = '1') then
            CLKIN_WINDOW <= '0';
            CLKFB_WINDOW <= '0';
        else
            if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                CLKIN_WINDOW <= '1';
                CLKIN_WINDOW <= transport '0' after CLKIN_WINDOW_WIDTH;
            end if;
            if (CLKFB_ipd'event AND CLKFB_ipd = '1') then
                CLKFB_WINDOW <= '1';
                CLKFB_WINDOW <= transport '0' after CLKFB_WINDOW_WIDTH;
            end if;
        end if;
    end process GENERATE_WINDOWS;
 
    WINDOW_OVERLAP <= CLKIN_WINDOW AND CLKFB_WINDOW;
 
    ---------------------------------------------------
    --  Check for a Lock
    ---------------------------------------------------
    DETERMINE_IF_LOCKED : process (CLKIN_ipd, RST_META, WINDOW_OVERLAP)
    variable LOCKED_GlitchData : VitalGlitchDataType;
    variable IS_LOCKED : std_ulogic := '0';
    begin
        if (RST_META'event AND RST_META = '1') then
            LOCKED_INT <= '0';
            IS_LOCKED  := '0';
        elsif (RST_META /= '1' AND (WINDOW_OVERLAP'event AND WINDOW_OVERLAP = '1')) then
            IS_LOCKED := '1';
        elsif (RST_META /= '1' AND (CLKIN_ipd'event AND CLKIN_ipd = '1')) then
            LOCKED_INT<= IS_LOCKED;
            IS_LOCKED := '0';
        end if;
        ----------------------
        --  Path Delay Section
        ----------------------
        VitalPathDelay01 (
            OutSignal  => LOCKED,
            GlitchData => LOCKED_GlitchData,
            OutSignalName => "LOCKED",
            OutTemp => LOCKED_INT,
            Paths => (0 => (CLKIN_ipd'last_event, tpd_CLKIN_LOCKED, TRUE)),
            Mode => OnEvent,
            Xon => Xon,
            MsgOn => MsgOn,
            MsgSeverity => WARNING
        );

    end process DETERMINE_IF_LOCKED;

    ---------------------------------------------------
    --  Generate CLK_5050 
    ---------------------------------------------------
    GENERATE_CLOCK_5050_AND_CLK2575 : process (CLKIN_ipd, RST_META)
    begin
        if (RST_META'event AND RST_META = '1') then
            CLK_5050 <= '0';
            
        elsif (PERIOD_FOUND = '1') then
            if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                CLK_5050 <= '1';
                
                CLK_5050 <= transport '0' after PERIOD_180;
                
            end if;
        end if;
    end process GENERATE_CLOCK_5050_AND_CLK2575;
    
    ---------------------------------------------------
    --  Delay CLKIN and CLK_5050 for Locking to CLKFB.
    ---------------------------------------------------
    CLKIN_DELAYED_0   <= transport CLKIN_ipd after DELAY;
    CLK5050_DELAYED_0 <= transport CLK_5050  after DELAY;

    ---------------------------------------------------
    --  CLK0, CLK180, CLK2X and CLK2X90
    ---------------------------------------------------
    DCC <= '1' when DUTY_CYCLE_CORRECTION else '0';
    
 
    CLK_0   <= (PERIOD_FOUND AND (NOT RST_META))  AND
               (((NOT DCC)   AND CLKIN_DELAYED_0)  OR
               (      DCC    AND CLK5050_DELAYED_0));
    CLK0    <= CLK_0;

    CLK180  <= transport CLK_0 after PERIOD_180;

    CLK5050_DELAYED_90 <= transport CLK_5050 after (DELAY + PERIOD_90);

    CLK_2X  <= (PERIOD_FOUND AND (NOT RST_META)) AND
               (CLK5050_DELAYED_0 XOR CLK5050_DELAYED_90);

    ---------------------------------------------------
    --  Clock Divider
    ---------------------------------------------------
    GENERATE_CLOCK_DIV : process (CLK_2X, RST_META)
    variable FIRST_TIME      : boolean    := TRUE;
    variable COUNT_RISE_FALL : real       := 0.0;
    variable CLOCK_DIV       : std_ulogic := '0';
    begin
        if (RST_META = '1') then
            FIRST_TIME      := TRUE;
            COUNT_RISE_FALL := 0.0;
            CLOCK_DIV       := '0';
        elsif (PERIOD_FOUND = '1') then
            if (CLK_2X'event) then
                if (CLK_2X = '1') then
                    if (FIRST_TIME) then
                        CLOCK_DIV  := NOT CLOCK_DIV;
                        FIRST_TIME := FALSE;
                    else COUNT_RISE_FALL := COUNT_RISE_FALL + 1.0;
                    end if;
                end if;
                if (CLK_2X = '0' AND IS_FRACTIONAL) then
                    COUNT_RISE_FALL := COUNT_RISE_FALL + 1.0;
                end if;
                if (COUNT_RISE_FALL >= DIVISOR) then
                    CLOCK_DIV       := NOT CLOCK_DIV;
                    COUNT_RISE_FALL := 0.0;
                end if;
            end if;
            CLKDV <= CLOCK_DIV;
        end if;
    end process GENERATE_CLOCK_DIV;

end CLKDLLHF_V;

configuration CFG_CLKDLLHF_V of CLKDLLHF is
    for CLKDLLHF_V
    end for;
end CFG_CLKDLLHF_V;
