----- CELL CY4 -----
library IEEE;
use IEEE.STD_LOGIC_1164.all;
library IEEE;
use IEEE.VITAL_Timing.all;


-- entity declaration --
entity CY4 is
   generic(
      TimingChecksOn: Boolean := TRUE;
      InstancePath: STRING := "*";
      Xon: Boolean := True;
      MsgOn: Boolean := False;
      tpd_CIN_COUT                   :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_A0_COUT                    :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_A1_COUT                    :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_B0_COUT                    :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_B1_COUT                    :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_ADD_COUT                   :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_C0_COUT                    :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_C1_COUT                    :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_C2_COUT                    :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_C3_COUT                    :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_C4_COUT                    :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_C5_COUT                    :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_C6_COUT                    :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_C7_COUT                    :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_CIN_COUT0                  :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_A0_COUT0                   :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_B0_COUT0                   :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_ADD_COUT0                  :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_C0_COUT0                   :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_C1_COUT0                   :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_C2_COUT0                   :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_C3_COUT0                   :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_C4_COUT0                   :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_C5_COUT0                   :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_C7_COUT0                   :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tipd_CIN                       :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_A0                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_A1                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_B0                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_B1                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_ADD                       :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_C0                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_C1                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_C2                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_C3                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_C4                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_C5                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_C6                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_C7                        :	VitalDelayType01 := (0.000 ns, 0.000 ns));

   port(
      COUT                           :	out   STD_ULOGIC;
      COUT0                          :	out   STD_ULOGIC;
      CIN                            :	in    STD_ULOGIC;
      A0                             :	in    STD_ULOGIC;
      A1                             :	in    STD_ULOGIC;
      B0                             :	in    STD_ULOGIC;
      B1                             :	in    STD_ULOGIC;
      ADD                            :	in    STD_ULOGIC;
      C0                             :	in    STD_ULOGIC;
      C1                             :	in    STD_ULOGIC;
      C2                             :	in    STD_ULOGIC;
      C3                             :	in    STD_ULOGIC;
      C4                             :	in    STD_ULOGIC;
      C5                             :	in    STD_ULOGIC;
      C6                             :	in    STD_ULOGIC;
      C7                             :	in    STD_ULOGIC);
attribute VITAL_LEVEL0 of CY4 : entity is TRUE;
end CY4;

-- architecture body --
library IEEE;
use IEEE.VITAL_Primitives.all;
library UNISIM;
use UNISIM.VPKG.all;
architecture CY4_V of CY4 is
   attribute VITAL_LEVEL1 of CY4_V : architecture is TRUE;

   SIGNAL CIN_ipd	 : STD_ULOGIC := 'X';
   SIGNAL A0_ipd	 : STD_ULOGIC := 'X';
   SIGNAL A1_ipd	 : STD_ULOGIC := 'X';
   SIGNAL B0_ipd	 : STD_ULOGIC := 'X';
   SIGNAL B1_ipd	 : STD_ULOGIC := 'X';
   SIGNAL ADD_ipd	 : STD_ULOGIC := 'X';
   SIGNAL C0_ipd	 : STD_ULOGIC := 'X';
   SIGNAL C1_ipd	 : STD_ULOGIC := 'X';
   SIGNAL C2_ipd	 : STD_ULOGIC := 'X';
   SIGNAL C3_ipd	 : STD_ULOGIC := 'X';
   SIGNAL C4_ipd	 : STD_ULOGIC := 'X';
   SIGNAL C5_ipd	 : STD_ULOGIC := 'X';
   SIGNAL C6_ipd	 : STD_ULOGIC := 'X';
   SIGNAL C7_ipd	 : STD_ULOGIC := 'X';

begin

   ---------------------
   --  INPUT PATH DELAYs
   ---------------------
   WireDelay : block
   begin
   VitalWireDelay (CIN_ipd, CIN, tipd_CIN);
   VitalWireDelay (A0_ipd, A0, tipd_A0);
   VitalWireDelay (A1_ipd, A1, tipd_A1);
   VitalWireDelay (B0_ipd, B0, tipd_B0);
   VitalWireDelay (B1_ipd, B1, tipd_B1);
   VitalWireDelay (ADD_ipd, ADD, tipd_ADD);
   VitalWireDelay (C0_ipd, C0, tipd_C0);
   VitalWireDelay (C1_ipd, C1, tipd_C1);
   VitalWireDelay (C2_ipd, C2, tipd_C2);
   VitalWireDelay (C3_ipd, C3, tipd_C3);
   VitalWireDelay (C4_ipd, C4, tipd_C4);
   VitalWireDelay (C5_ipd, C5, tipd_C5);
   VitalWireDelay (C6_ipd, C6, tipd_C6);
   VitalWireDelay (C7_ipd, C7, tipd_C7);
   end block;
   --------------------
   --  BEHAVIOR SECTION
   --------------------
   VITALBehavior : process (CIN_ipd, A0_ipd, A1_ipd, B0_ipd, B1_ipd, ADD_ipd, C0_ipd, C1_ipd, C2_ipd, C3_ipd, C4_ipd, C5_ipd, C6_ipd, C7_ipd)


   -- functionality results
   VARIABLE Results : STD_LOGIC_VECTOR(1 to 2) := (others => 'X');
   ALIAS COUT_zd : STD_LOGIC is Results(1);
   ALIAS COUT0_zd : STD_LOGIC is Results(2);

   -- output glitch detection variables
   VARIABLE COUT_GlitchData	: VitalGlitchDataType;
   VARIABLE COUT0_GlitchData	: VitalGlitchDataType;

   begin

      -------------------------
      --  Functionality Section
      -------------------------
      COUT_zd :=
       (((((((ADD_ipd) AND (C0_ipd)) OR (((NOT C0_ipd)) AND (C1_ipd))) XOR
         (A1_ipd) XOR (((NOT B1_ipd)) OR ((NOT C7_ipd)))) AND (C6_ipd)) OR
         ((NOT C6_ipd))) AND ((((((((ADD_ipd) AND (C0_ipd)) OR (((NOT
         C0_ipd)) AND (C1_ipd))) XOR (A0_ipd) XOR (((NOT C7_ipd)) OR ((NOT
         B0_ipd)))) AND (C3_ipd)) OR (((NOT C3_ipd)) AND (C2_ipd))) AND
         (CIN_ipd)) OR (((NOT ((((((ADD_ipd) AND (C0_ipd)) OR (((NOT C0_ipd))
         AND (C1_ipd))) XOR (A0_ipd) XOR (((NOT C7_ipd)) OR ((NOT B0_ipd))))
         AND (C3_ipd)) OR (((NOT C3_ipd)) AND (C2_ipd))))) AND ((((NOT
         C4_ipd)) AND (C5_ipd) AND ((NOT ADD_ipd))) OR (((NOT C4_ipd)) AND
         ((NOT C5_ipd)) AND (C7_ipd)) OR ((C4_ipd) AND (C5_ipd) AND
         (A0_ipd)))))) OR (((NOT ((((((ADD_ipd) AND (C0_ipd)) OR (((NOT
         C0_ipd)) AND (C1_ipd))) XOR (A1_ipd) XOR (((NOT B1_ipd)) OR ((NOT
         C7_ipd)))) AND (C6_ipd)) OR ((NOT C6_ipd))))) AND (A1_ipd));
      COUT0_zd :=
       (((((((ADD_ipd) AND (C0_ipd)) OR (((NOT C0_ipd)) AND (C1_ipd))) XOR
         (A0_ipd) XOR (((NOT C7_ipd)) OR ((NOT B0_ipd)))) AND (C3_ipd)) OR
         (((NOT C3_ipd)) AND (C2_ipd))) AND (CIN_ipd)) OR (((NOT
         ((((((ADD_ipd) AND (C0_ipd)) OR (((NOT C0_ipd)) AND (C1_ipd))) XOR
         (A0_ipd) XOR (((NOT C7_ipd)) OR ((NOT B0_ipd)))) AND (C3_ipd)) OR
         (((NOT C3_ipd)) AND (C2_ipd))))) AND ((((NOT C4_ipd)) AND (C5_ipd)
         AND ((NOT ADD_ipd))) OR (((NOT C4_ipd)) AND ((NOT C5_ipd)) AND
         (C7_ipd)) OR ((C4_ipd) AND (C5_ipd) AND (A0_ipd))));

      ----------------------
      --  Path Delay Section
      ----------------------
      VitalPathDelay01 (
       OutSignal => COUT,
       GlitchData => COUT_GlitchData,
       OutSignalName => "COUT",
       OutTemp => COUT_zd,
       Paths => (0 => (CIN_ipd'last_event, tpd_CIN_COUT, TRUE),
                 1 => (A0_ipd'last_event, tpd_A0_COUT, TRUE),
                 2 => (A1_ipd'last_event, tpd_A1_COUT, TRUE),
                 3 => (B0_ipd'last_event, tpd_B0_COUT, TRUE),
                 4 => (B1_ipd'last_event, tpd_B1_COUT, TRUE),
                 5 => (ADD_ipd'last_event, tpd_ADD_COUT, TRUE),
                 6 => (C0_ipd'last_event, tpd_C0_COUT, TRUE),
                 7 => (C1_ipd'last_event, tpd_C1_COUT, TRUE),
                 8 => (C2_ipd'last_event, tpd_C2_COUT, TRUE),
                 9 => (C3_ipd'last_event, tpd_C3_COUT, TRUE),
                 10 => (C4_ipd'last_event, tpd_C4_COUT, TRUE),
                 11 => (C5_ipd'last_event, tpd_C5_COUT, TRUE),
                 12 => (C6_ipd'last_event, tpd_C6_COUT, TRUE),
                 13 => (C7_ipd'last_event, tpd_C7_COUT, TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);
      VitalPathDelay01 (
       OutSignal => COUT0,
       GlitchData => COUT0_GlitchData,
       OutSignalName => "COUT0",
       OutTemp => COUT0_zd,
       Paths => (0 => (CIN_ipd'last_event, tpd_CIN_COUT0, TRUE),
                 1 => (A0_ipd'last_event, tpd_A0_COUT0, TRUE),
                 2 => (B0_ipd'last_event, tpd_B0_COUT0, TRUE),
                 3 => (ADD_ipd'last_event, tpd_ADD_COUT0, TRUE),
                 4 => (C0_ipd'last_event, tpd_C0_COUT0, TRUE),
                 5 => (C1_ipd'last_event, tpd_C1_COUT0, TRUE),
                 6 => (C2_ipd'last_event, tpd_C2_COUT0, TRUE),
                 7 => (C3_ipd'last_event, tpd_C3_COUT0, TRUE),
                 8 => (C4_ipd'last_event, tpd_C4_COUT0, TRUE),
                 9 => (C5_ipd'last_event, tpd_C5_COUT0, TRUE),
                 10 => (C7_ipd'last_event, tpd_C7_COUT0, TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);

