library IEEE;
use IEEE.VITAL_Primitives.all;
library UNISIM;
use UNISIM.VPKG.all;
architecture FDCE_1_V of FDCE_1 is
   --attribute VITAL_LEVEL1 of FDCE_1_V : architecture is TRUE;

   SIGNAL D_ipd	 : STD_ULOGIC := 'X';
   SIGNAL C_ipd	 : STD_ULOGIC := 'X';
   SIGNAL CE_ipd	 : STD_ULOGIC := 'X';
   SIGNAL CLR_ipd	 : STD_ULOGIC := 'X';

begin

   ---------------------
   --  INPUT PATH DELAYs
   ---------------------
   WireDelay : block
   begin
   VitalWireDelay (D_ipd, D, tipd_D);
   VitalWireDelay (C_ipd, C, tipd_C);
   VitalWireDelay (CE_ipd, CE, tipd_CE);
   VitalWireDelay (CLR_ipd, CLR, tipd_CLR);
   end block;
   --------------------
   --  BEHAVIOR SECTION
   --------------------
   VITALBehavior : process 

   -- timing check results
   VARIABLE Tviol_D_C_negedge	: STD_ULOGIC := '0';
   VARIABLE Tmkr_D_C_negedge	: VitalTimingDataType := VitalTimingDataInit;
   VARIABLE Tviol_CE_C_negedge	: STD_ULOGIC := '0';
   VARIABLE Tmkr_CE_C_negedge	: VitalTimingDataType := VitalTimingDataInit;
   VARIABLE Tviol_CLR_C_negedge	: STD_ULOGIC := '0';
   VARIABLE Tmkr_CLR_C_negedge	: VitalTimingDataType := VitalTimingDataInit;
   VARIABLE Pviol_C	: STD_ULOGIC := '0';
   VARIABLE PInfo_C	: VitalPeriodDataType := VitalPeriodDataInit;
   VARIABLE Pviol_CLR	: STD_ULOGIC := '0';
   VARIABLE PInfo_CLR	: VitalPeriodDataType := VitalPeriodDataInit;

   -- functionality results
   VARIABLE Violation : STD_ULOGIC := '0';
   VARIABLE PrevData_Q : STD_LOGIC_VECTOR(0 to 5);
   VARIABLE D_delayed : STD_ULOGIC := 'X';
   VARIABLE C_delayed : STD_ULOGIC := 'X';
   VARIABLE CE_delayed : STD_ULOGIC := 'X';
   --VARIABLE Results : STD_LOGIC_VECTOR(1 to 1) := (others => 'X');
   --ALIAS Q_zd : STD_LOGIC is Results(1);
   variable Q_zd : STD_ULOGIC := TO_X01(INIT);
   VARIABLE FIRST_TIME : boolean := True ;

   -- output glitch detection variables
   VARIABLE Q_GlitchData	: VitalGlitchDataType;

   begin

     if (FIRST_TIME = TRUE) then

       Q <= Q_zd;

       wait until (CLR_ipd = '1' or falling_edge(c_ipd ));

	CE_delayed := CE_ipd;
        C_delayed := C_ipd'last_value;
        D_delayed := D_ipd;

       FIRST_TIME := FALSE;
      end if;
      ------------------------
      --  Timing Check Section
      ------------------------
      if (TimingChecksOn) then
         VitalSetupHoldCheck (
          Violation               => Tviol_D_C_negedge,
          TimingData              => Tmkr_D_C_negedge,
          TestSignal              => D_ipd,
          TestSignalName          => "D",
          TestDelay               => 0 ns,
          RefSignal               => C_ipd,
          RefSignalName          => "C",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_D_C_posedge_negedge,
          SetupLow                => tsetup_D_C_negedge_negedge,
          HoldHigh                => thold_D_C_posedge_negedge,
          HoldLow                 => thold_D_C_negedge_negedge,
          CheckEnabled            => 
                           TO_X01(((NOT CLR_ipd)) AND (CE_ipd)) /= '0',
          RefTransition           => 'F',
          HeaderMsg               => InstancePath & "/FDCE_1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
         VitalSetupHoldCheck (
          Violation               => Tviol_CE_C_negedge,
          TimingData              => Tmkr_CE_C_negedge,
          TestSignal              => CE_ipd,
          TestSignalName          => "CE",
          TestDelay               => 0 ns,
          RefSignal               => C_ipd,
          RefSignalName          => "C",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_CE_C_posedge_negedge,
          SetupLow                => tsetup_CE_C_negedge_negedge,
          HoldHigh                => thold_CE_C_posedge_negedge,
          HoldLow                 => thold_CE_C_negedge_negedge,
          CheckEnabled            => 
                           TO_X01(((NOT CLR_ipd)) AND ((Q_zd) XOR (D_ipd)))
                            /= '0',
          RefTransition           => 'F',
          HeaderMsg               => InstancePath & "/FDCE_1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
         VitalRecoveryRemovalCheck (
          Violation               => Tviol_CLR_C_negedge,
          TimingData              => Tmkr_CLR_C_negedge,
          TestSignal              => CLR_ipd,
          TestSignalName          => "CLR",
          TestDelay               => 0 ns,
          RefSignal               => C_ipd,
          RefSignalName          => "C",
          RefDelay                => 0 ns,
          Recovery                => trecovery_CLR_C_negedge_negedge,
          Removal                 => thold_CLR_C_negedge_negedge,
          ActiveLow               => FALSE,
          CheckEnabled            => 
                           TO_X01(CE_ipd) /= '0',
          RefTransition           => 'F',
          HeaderMsg               => InstancePath & "/FDCE_1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
         VitalPeriodPulseCheck (
          Violation               => Pviol_C,
          PeriodData              => PInfo_C,
          TestSignal              => C_ipd,
          TestSignalName          => "C",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_C_posedge,
          PulseWidthLow           => tpw_C_negedge,
          CheckEnabled            =>  TRUE,
          HeaderMsg               => InstancePath &"/FDCE_1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
         VitalPeriodPulseCheck (
          Violation               => Pviol_CLR,
          PeriodData              => PInfo_CLR,
          TestSignal              => CLR_ipd,
          TestSignalName          => "CLR",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_CLR_posedge,
          PulseWidthLow           => 0 ns,
          CheckEnabled            =>  TRUE,
          HeaderMsg               => InstancePath &"/FDCE_1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
      end if;

      -------------------------
      --  Functionality Section
      -------------------------
      Violation := Tviol_D_C_negedge or Tviol_CE_C_negedge or Pviol_C or Tviol_CLR_C_negedge or Pviol_CLR;
      VitalStateTable(
        Result => Q_zd,
        PreviousDataIn => PrevData_Q,
        StateTable => FDCE_Q_tab,
        DataIn => (
               C_ipd, Q_zd, D_delayed, CE_delayed, C_delayed, CLR_ipd));
      Q_zd := Violation XOR Q_zd;
      D_delayed := D_ipd;
      C_delayed := C_ipd;
      CE_delayed := CE_ipd;

      ----------------------
      --  Path Delay Section
      ----------------------
      VitalPathDelay01 (
       OutSignal => Q,
       GlitchData => Q_GlitchData,
       OutSignalName => "Q",
       OutTemp => Q_zd,
       Paths => (0 => (CLR_ipd'last_event, tpd_CLR_Q, TRUE),
                 1 => (C_ipd'last_event, tpd_C_Q, TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);

    wait on D_ipd, C_ipd, CE_ipd, CLR_ipd;
end process;

end FDCE_1_V;

configuration CFG_FDCE_1_V of FDCE_1 is
   for FDCE_1_V
   end for;
end CFG_FDCE_1_V;
