----- CELL FDDRCPE -----
library IEEE;
use IEEE.STD_LOGIC_1164.all;
library IEEE;
use IEEE.VITAL_Timing.all;


-- entity declaration --
entity FDDRCPE is
   generic(
      TimingChecksOn: Boolean := TRUE;
      InstancePath: STRING := "*";
      Xon: Boolean := True;
      MsgOn: Boolean := False;
      tpd_CLR_Q                        :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_PRE_Q                        :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_C0_Q                        :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_C1_Q                        :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_D0_Q                        :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_D1_Q                        :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tipd_PRE                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_CLR                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_D0                         :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_D1                         :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_C0                         :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_C1                         :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_CE                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
	INIT				: BIT := '0' );

   port(
      Q                             :	out   STD_ULOGIC;
      D0                              :	in    STD_ULOGIC;
      D1                              :	in    STD_ULOGIC;
      C0                             :	in    STD_ULOGIC;
      C1                             :	in    STD_ULOGIC;
      CE                             :	in    STD_ULOGIC;
      PRE                             :	in    STD_ULOGIC;
      CLR                             :	in    STD_ULOGIC);
attribute VITAL_LEVEL0 of FDDRCPE : entity is TRUE;
end FDDRCPE;

-- architecture body --
library IEEE;
use IEEE.VITAL_Primitives.all;
library UNISIM;
use UNISIM.VPKG.all;
architecture FDDRCPE_V of FDDRCPE is
--   attribute VITAL_LEVEL1 of FDDRCPE_V : architecture is TRUE;

   SIGNAL D0_ipd	 : STD_ULOGIC := 'X';
   SIGNAL D1_ipd	 : STD_ULOGIC := 'X';
   SIGNAL PRE_ipd	 : STD_ULOGIC := 'X';
   SIGNAL CLR_ipd	 : STD_ULOGIC := 'X';
   SIGNAL C0_ipd	 : STD_ULOGIC := 'X';
   SIGNAL C1_ipd	 : STD_ULOGIC := 'X';
   SIGNAL CE_ipd	 : STD_ULOGIC := 'X';

begin

   ---------------------
   --  INPUT PATH DELAYs
   ---------------------
   WireDelay : block
   begin
   VitalWireDelay (D0_ipd, D0, tipd_D0);
   VitalWireDelay (PRE_ipd, PRE, tipd_PRE);
   VitalWireDelay (CLR_ipd, CLR, tipd_CLR);
   VitalWireDelay (D1_ipd, D1, tipd_D1);
   VitalWireDelay (C0_ipd, C0, tipd_C0);
   VitalWireDelay (C1_ipd, C1, tipd_C1);
   VitalWireDelay (CE_ipd, CE, tipd_CE);
   end block;
   --------------------
   --  BEHAVIOR SECTION
   --------------------
   VITALBehavior : process 

   -- timing check results

   -- functionality results
   VARIABLE PrevData_Q : STD_LOGIC_VECTOR(0 to 6);
   VARIABLE D_delayed : STD_ULOGIC := 'X';
   VARIABLE C0_delayed : STD_ULOGIC := 'X';
   VARIABLE C1_delayed : STD_ULOGIC := 'X';
   VARIABLE CE_delayed : STD_ULOGIC := 'X';
   VARIABLE Results : STD_LOGIC_VECTOR(1 to 1) := (others => To_X01(INIT));
   VARIABLE FIRST_TIME : BOOLEAN := TRUE;
   ALIAS Q_zd : STD_LOGIC is Results(1);

   -- output glitch detection variables
   VARIABLE Q_GlitchData	: VitalGlitchDataType;

   begin

      -------------------------
      --  Functionality Section
      -------------------------
 
      if (FIRST_TIME) then
         Q <= TO_X01(INIT);
         wait until ((C0_ipd = '1' OR C0_ipd = '0') AND
                        (C1_ipd = '1' OR C1_ipd = '0' ));
         FIRST_TIME := false ;
      end if;

      If (CLR_ipd = '1') then
		Q_zd := '0';
      elsif (PRE_ipd = '1' ) then
		Q_zd := '1';
      elsif ( rising_edge(C0_ipd) = TRUE) then
		if (CE_ipd = '1' ) then
 			Q_zd := D0_ipd;
		end if;
      elsif (rising_edge(C1_ipd) = TRUE ) then
		if (CE_ipd = '1') then
 			Q_zd := D1_ipd;
		end if;
      end if;

      ----------------------
      --  Path Delay Section
      ----------------------
      VitalPathDelay01 (
       OutSignal => Q,
       GlitchData => Q_GlitchData,
       OutSignalName => "Q",
       OutTemp => Q_zd,
       Paths => (0 => (C0_ipd'last_event, tpd_C0_Q, TRUE),
                 1 => (C1_ipd'last_event, tpd_C1_Q, TRUE),
                 2 => (PRE_ipd'last_event, tpd_PRE_Q, TRUE),
                 3 => (CLR_ipd'last_event, tpd_CLR_Q, TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);

wait on C0_ipd, C1_ipd, PRE_ipd, CLR_ipd;
end process VITALBehavior;

end FDDRCPE_V;

configuration CFG_FDDRCPE_V of FDDRCPE is
   for FDDRCPE_V
   end for;
end CFG_FDDRCPE_V;
----- CELL FDDRRSE -----
library IEEE;
use IEEE.STD_LOGIC_1164.all;
library IEEE;
use IEEE.VITAL_Timing.all;


-- entity declaration --
entity FDDRRSE is
   generic(
      TimingChecksOn: Boolean := TRUE;
      InstancePath: STRING := "*";
      Xon: Boolean := True;
      MsgOn: Boolean := False;
      tpd_C0_Q                        :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_C1_Q                        :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_D0_Q                        :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_D1_Q                        :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tipd_S                          :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_R                          :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_D0                         :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_D1                         :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_C0                         :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_C1                         :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_CE                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
	INIT				: BIT := '0' );

   port(
      Q                             :	out   STD_ULOGIC;
      D0                              :	in    STD_ULOGIC;
      D1                              :	in    STD_ULOGIC;
      C0                             :	in    STD_ULOGIC;
      C1                             :	in    STD_ULOGIC;
      CE                             :	in    STD_ULOGIC;
      S                              :	in    STD_ULOGIC;
      R                              :	in    STD_ULOGIC);
attribute VITAL_LEVEL0 of FDDRRSE : entity is TRUE;
end FDDRRSE;

-- architecture body --
library IEEE;
use IEEE.VITAL_Primitives.all;
library UNISIM;
use UNISIM.VPKG.all;
architecture FDDRRSE_V of FDDRRSE is
--   attribute VITAL_LEVEL1 of FDDRRSE_V : architecture is TRUE;

   SIGNAL D0_ipd	 : STD_ULOGIC := 'X';
   SIGNAL D1_ipd	 : STD_ULOGIC := 'X';
   SIGNAL R_ipd	 : STD_ULOGIC := 'X';
   SIGNAL S_ipd	 : STD_ULOGIC := 'X';
   SIGNAL C0_ipd	 : STD_ULOGIC := 'X';
   SIGNAL C1_ipd	 : STD_ULOGIC := 'X';
   SIGNAL CE_ipd	 : STD_ULOGIC := 'X';

begin

   ---------------------
   --  INPUT PATH DELAYs
   ---------------------
   WireDelay : block
   begin
   VitalWireDelay (D0_ipd, D0, tipd_D0);
   VitalWireDelay (S_ipd, S, tipd_S);
   VitalWireDelay (R_ipd, R, tipd_R);
   VitalWireDelay (D1_ipd, D1, tipd_D1);
   VitalWireDelay (C0_ipd, C0, tipd_C0);
   VitalWireDelay (C1_ipd, C1, tipd_C1);
   VitalWireDelay (CE_ipd, CE, tipd_CE);
   end block;
   --------------------
   --  BEHAVIOR SECTION
   --------------------
   VITALBehavior : process 

   -- timing check results

   -- functionality results
   VARIABLE PrevData_Q : STD_LOGIC_VECTOR(0 to 6);
   VARIABLE D_delayed : STD_ULOGIC := 'X';
   VARIABLE C0_delayed : STD_ULOGIC := 'X';
   VARIABLE C1_delayed : STD_ULOGIC := 'X';
   VARIABLE CE_delayed : STD_ULOGIC := 'X';
   VARIABLE Results : STD_LOGIC_VECTOR(1 to 1) := (others => TO_X01(INIT));
   VARIABLE FIRST_TIME : boolean := true;
   ALIAS Q_zd : STD_LOGIC is Results(1);

   -- output glitch detection variables
   VARIABLE Q_GlitchData	: VitalGlitchDataType;

   begin

      -------------------------
      --  Functionality Section
      -------------------------
 
      if (FIRST_TIME) then
            Q <= TO_X01(INIT);
            wait until ((C0_ipd = '1' OR C0_ipd = '0') AND
                        (C1_ipd = '1' OR C1_ipd = '0' ));
         FIRST_TIME := false ;
      end if;

      if ( rising_edge(C0_ipd) = TRUE) then
                if (R_ipd = '1') then
			Q_zd := '0';
		elsif (S_ipd = '1' ) then
			Q_zd := '1' ; 
		elsif (CE_ipd = '1' ) then
 			Q_zd := D0_ipd;
		end if;

      elsif (rising_edge(C1_ipd) = TRUE ) then
                if (R_ipd = '1') then
                        Q_zd := '0';
                elsif (S_ipd = '1' ) then
                        Q_zd := '1'  ;
		elsif (CE_ipd = '1') then
 			Q_zd := D1_ipd;
		end if;
      end if;

      ----------------------
      --  Path Delay Section
      ----------------------
      VitalPathDelay01 (
       OutSignal => Q,
       GlitchData => Q_GlitchData,
       OutSignalName => "Q",
       OutTemp => Q_zd,
       Paths => (0 => (C0_ipd'last_event, tpd_C0_Q, TRUE),
                 1 => (C1_ipd'last_event, tpd_C1_Q, TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);

wait on C0_ipd, C1_ipd;
end process VITALBehavior;

end FDDRRSE_V;

configuration CFG_FDDRRSE_V of FDDRRSE is
   for FDDRRSE_V
   end for;
end CFG_FDDRRSE_V;
