          CheckEnabled            => 
                           TO_X01((NOT PRE_ipd)) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/FDPC",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
         VitalRecoveryRemovalCheck (
          Violation               => Tviol_PRE_C_posedge,
          TimingData              => Tmkr_PRE_C_posedge,
          TestSignal              => PRE_ipd,
          TestSignalName          => "PRE",
          TestDelay               => 0 ns,
          RefSignal               => C_ipd,
          RefSignalName          => "C",
          RefDelay                => 0 ns,
