      end if;

      -------------------------
      --  Functionality Section
      -------------------------
      Violation := Tviol_D_C_posedge or Tviol_CLR_C_posedge or Tviol_PRE_C_posedge or Pviol_PRE or Pviol_C or Pviol_CLR;
      VitalStateTable(
        Result => Q_zd,
