library IEEE;
use IEEE.VITAL_Primitives.all;
library UNISIM;
use UNISIM.VPKG.all;
architecture FDRS_1_V of FDRS_1 is
   --attribute VITAL_LEVEL1 of FDRS_1_V : architecture is TRUE;

   SIGNAL D_ipd	 : STD_ULOGIC := 'X';
   SIGNAL C_ipd	 : STD_ULOGIC := 'X';
   SIGNAL R_ipd	 : STD_ULOGIC := 'X';
   SIGNAL S_ipd	 : STD_ULOGIC := 'X';

begin

   ---------------------
   --  INPUT PATH DELAYs
   ---------------------
   WireDelay : block
   begin
   VitalWireDelay (D_ipd, D, tipd_D);
   VitalWireDelay (C_ipd, C, tipd_C);
   VitalWireDelay (R_ipd, R, tipd_R);
   VitalWireDelay (S_ipd, S, tipd_S);
   end block;
   --------------------
   --  BEHAVIOR SECTION
   --------------------
   VITALBehavior : process 

   -- timing check results
   VARIABLE Tviol_D_C_negedge	: STD_ULOGIC := '0';
   VARIABLE Tmkr_D_C_negedge	: VitalTimingDataType := VitalTimingDataInit;
   VARIABLE Tviol_R_C_negedge	: STD_ULOGIC := '0';
   VARIABLE Tmkr_R_C_negedge	: VitalTimingDataType := VitalTimingDataInit;
   VARIABLE Tviol_S_C_negedge	: STD_ULOGIC := '0';
   VARIABLE Tmkr_S_C_negedge	: VitalTimingDataType := VitalTimingDataInit;
   VARIABLE Pviol_C	: STD_ULOGIC := '0';
   VARIABLE PInfo_C	: VitalPeriodDataType := VitalPeriodDataInit;

   -- functionality results
   VARIABLE Violation : STD_ULOGIC := '0';
   VARIABLE PrevData_Q : STD_LOGIC_VECTOR(0 to 4);
   VARIABLE D_delayed : STD_ULOGIC := 'X';
   VARIABLE C_delayed : STD_ULOGIC := 'X';
   VARIABLE R_delayed : STD_ULOGIC := 'X';
   VARIABLE S_delayed : STD_ULOGIC := 'X';
   --VARIABLE Results : STD_LOGIC_VECTOR(1 to 1) := (others => 'X');
   --ALIAS Q_zd : STD_LOGIC is Results(1);
   variable Q_zd : STD_ULOGIC := TO_X01(INIT);
   VARIABLE FIRST_TIME : boolean := True ;

   -- output glitch detection variables
   VARIABLE Q_GlitchData	: VitalGlitchDataType;

   begin

      if (FIRST_TIME = TRUE) then

       Q <= Q_zd;

       wait until (falling_edge(c_ipd ));

       C_delayed := C_ipd'last_value;
       D_delayed := D_ipd;
      R_delayed := R_ipd;
      S_delayed := S_ipd;


       FIRST_TIME := FALSE;
      end if;
      ------------------------
      --  Timing Check Section
      ------------------------
      if (TimingChecksOn) then
         VitalSetupHoldCheck (
          Violation               => Tviol_D_C_negedge,
          TimingData              => Tmkr_D_C_negedge,
          TestSignal              => D_ipd,
          TestSignalName          => "D",
          TestDelay               => 0 ns,
          RefSignal               => C_ipd,
          RefSignalName          => "C",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_D_C_posedge_negedge,
          SetupLow                => tsetup_D_C_negedge_negedge,
          HoldHigh                => thold_D_C_posedge_negedge,
          HoldLow                 => thold_D_C_negedge_negedge,
          CheckEnabled            => 
                           TO_X01(((NOT S_ipd)) AND ((NOT R_ipd))) /= '0',
          RefTransition           => 'F',
          HeaderMsg               => InstancePath & "/FDRS_1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
         VitalSetupHoldCheck (
          Violation               => Tviol_R_C_negedge,
          TimingData              => Tmkr_R_C_negedge,
          TestSignal              => R_ipd,
          TestSignalName          => "R",
          TestDelay               => 0 ns,
          RefSignal               => C_ipd,
          RefSignalName          => "C",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_R_C_posedge_negedge,
          SetupLow                => tsetup_R_C_negedge_negedge,
          HoldHigh                => thold_R_C_posedge_negedge,
          HoldLow                 => thold_R_C_negedge_negedge,
          CheckEnabled            => 
                           TRUE,
          RefTransition           => 'F',
          HeaderMsg               => InstancePath & "/FDRS_1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
         VitalSetupHoldCheck (
          Violation               => Tviol_S_C_negedge,
          TimingData              => Tmkr_S_C_negedge,
          TestSignal              => S_ipd,
          TestSignalName          => "S",
          TestDelay               => 0 ns,
          RefSignal               => C_ipd,
          RefSignalName          => "C",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_S_C_posedge_negedge,
          SetupLow                => tsetup_S_C_negedge_negedge,
          HoldHigh                => thold_S_C_posedge_negedge,
          HoldLow                 => thold_S_C_negedge_negedge,
          CheckEnabled            => 
                           TO_X01((NOT R_ipd)) /= '0',
          RefTransition           => 'F',
          HeaderMsg               => InstancePath & "/FDRS_1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
         VitalPeriodPulseCheck (
          Violation               => Pviol_C,
          PeriodData              => PInfo_C,
          TestSignal              => C_ipd,
          TestSignalName          => "C",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_C_posedge,
          PulseWidthLow           => tpw_C_negedge,
          CheckEnabled            =>  TRUE,
          HeaderMsg               => InstancePath &"/FDRS_1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
      end if;

      -------------------------
      --  Functionality Section
      -------------------------
      Violation := Tviol_D_C_negedge or Tviol_R_C_negedge or Tviol_S_C_negedge or Pviol_C;
      VitalStateTable(
        Result => Q_zd,
        PreviousDataIn => PrevData_Q,
        StateTable => FDRS_Q_tab,
        DataIn => (
               C_ipd, S_delayed, D_delayed, R_delayed, C_delayed));
      Q_zd := Violation XOR Q_zd;
      D_delayed := D_ipd;
      C_delayed := C_ipd;
      R_delayed := R_ipd;
      S_delayed := S_ipd;

      ----------------------
      --  Path Delay Section
      ----------------------
      VitalPathDelay01 (
       OutSignal => Q,
       GlitchData => Q_GlitchData,
       OutSignalName => "Q",
       OutTemp => Q_zd,
       Paths => (0 => (C_ipd'last_event, tpd_C_Q, TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);

   wait on D_ipd, C_ipd, R_ipd, S_ipd;
end process;

end FDRS_1_V;

configuration CFG_FDRS_1_V of FDRS_1 is
   for FDRS_1_V
   end for;
end CFG_FDRS_1_V;
