       Q <= Q_zd;

       wait until (rising_edge(c_ipd ));

       CE_delayed := CE_ipd;
       C_delayed := C_ipd'last_value;
       D_delayed := D_ipd;
      R_delayed := R_ipd;
      S_delayed := S_ipd;

