          HoldLow                => thold_D_C_posedge_posedge,
          HoldHigh                 => thold_D_C_negedge_posedge,
          CheckEnabled            => 
                           TO_X01(((NOT R_ipd)) AND (CE_ipd) AND ((NOT
                            S_ipd))) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/FDRSE",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
         VitalSetupHoldCheck (
          Violation               => Tviol_CE_C_posedge,
          TimingData              => Tmkr_CE_C_posedge,
          TestSignal              => CE_ipd,
          TestSignalName          => "CE",
          TestDelay               => 0 ns,
