          RefSignalName          => "C",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_CE_C_posedge_posedge,
          SetupLow                => tsetup_CE_C_negedge_posedge,
          HoldLow                => thold_CE_C_posedge_posedge,
          HoldHigh                 => thold_CE_C_negedge_posedge,
          CheckEnabled            => 
                           TO_X01(((NOT R_ipd)) AND ((Q_zd) XOR (D_ipd)) AND
                            ((NOT S_ipd))) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/FDRSE",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
