          TestSignal              => S_ipd,
          TestSignalName          => "S",
          TestDelay               => 0 ns,
          RefSignal               => C_ipd,
          RefSignalName          => "C",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_S_C_posedge_posedge,
          SetupLow                => tsetup_S_C_negedge_posedge,
          HoldLow                => thold_S_C_posedge_posedge,
          HoldHigh                 => thold_S_C_negedge_posedge,
