----- CELL GXTL -----
-----------------------------------------------------------------------------
-- Model for XC3100A Oscillator Cell Combined with ACLK
--
-- Version 1.0.1
--
-- Dhimant Patel, September 25, 1997.
 
-- This is the same as the model for the OSC.
-----------------------------------------------------------------------------
library IEEE;
use IEEE.std_logic_1164.all;
use IEEE.VITAL_Timing.all;
 
entity GXTL is
    generic ( InstancePath : STRING := "*";
              PERIOD : Time := 0 ns;
              FRACTION_ON : real := 0.5 );
    port( O : out std_ulogic := '0' );
    attribute VITAL_LEVEL0 of GXTL : entity is TRUE;
end GXTL;
 
architecture GXTL_V of GXTL is
 
attribute VITAL_LEVEL0 of GXTL_V : architecture is TRUE;
 
constant TIME_ON : Time := (FRACTION_ON * PERIOD);
constant TIME_OFF : Time := (PERIOD - TIME_ON);
 
begin
    CLOCK: process
    begin
        if (PERIOD <= 0 ns) then
            assert FALSE report
            "*** Error: A positive value of PERIOD must be specified ***"
            severity failure;
            wait;
        elsif (FRACTION_ON <= 0.0 OR FRACTION_ON >= 1.0) then
            assert FALSE report
            "*** Error: A value of FRACTION_ON between 0 and 1 must be specified ***"
            severity failure;
            wait;
        else
            O <= '0';
            wait for TIME_OFF;
            O <= '1';
            wait for TIME_ON;
        end if;
    end process CLOCK;
end GXTL_V;
 
configuration CFG_GXTL_V of GXTL is
    for GXTL_V
    end for;
end CFG_GXTL_V;
