architecture ILFLX_V of ILFLX is
   --attribute VITAL_LEVEL1 of ILFLX_V : architecture is TRUE;

   SIGNAL D_ipd	 : STD_ULOGIC := 'X';
   SIGNAL GF_ipd	 : STD_ULOGIC := 'X';
   SIGNAL GE_ipd	 : STD_ULOGIC := 'X';
   SIGNAL G_ipd	 : STD_ULOGIC := 'X';

begin

   ---------------------
   --  INPUT PATH DELAYs
   ---------------------
   WireDelay : block
   begin
   VitalWireDelay (D_ipd, D, tipd_D);
   VitalWireDelay (GF_ipd, GF, tipd_GF);
   VitalWireDelay (GE_ipd, GE, tipd_GE);
   VitalWireDelay (G_ipd, G, tipd_G);
   end block;
   --------------------
   --  BEHAVIOR SECTION
   --------------------
   VITALBehavior : process

   -- timing check results
   VARIABLE Tviol_D_GF_posedge	: STD_ULOGIC := '0';
   VARIABLE Tmkr_D_GF_posedge	: VitalTimingDataType := VitalTimingDataInit;
   VARIABLE Tviol_GE_G_negedge	: STD_ULOGIC := '0';
   VARIABLE Tmkr_GE_G_negedge	: VitalTimingDataType := VitalTimingDataInit;
   VARIABLE Pviol_GF	: STD_ULOGIC := '0';
   VARIABLE PInfo_GF	: VitalPeriodDataType := VitalPeriodDataInit;
   VARIABLE Pviol_G	: STD_ULOGIC := '0';
   VARIABLE PInfo_G	: VitalPeriodDataType := VitalPeriodDataInit;

   -- functionality results
   VARIABLE Violation : STD_ULOGIC := '0';
   VARIABLE PrevData_Q : STD_LOGIC_VECTOR(0 to 4);
   VARIABLE PrevData_INT : STD_LOGIC_VECTOR(0 to 1);
   VARIABLE INT : STD_ULOGIC := 'X';
   --VARIABLE Results : STD_LOGIC_VECTOR(1 to 1) := (others => 'X');
   VARIABLE Q_zd : STD_ULOGIC := TO_X01(INIT);
   VARIABLE FIRST_TIME : boolean := True ;
   --ALIAS Q_zd : STD_LOGIC is Results(1);

   -- output glitch detection variables
   VARIABLE Q_GlitchData	: VitalGlitchDataType;

   begin

   if (FIRST_TIME = TRUE) then

       Q <= Q_zd ;
       wait until (G_ipd = '0' or G_ipd = '1');
       FIRST_TIME := FALSE;
    end if;


      ------------------------
      --  Timing Check Section
      ------------------------
      if (TimingChecksOn) then
         VitalSetupHoldCheck (
          Violation               => Tviol_D_GF_posedge,
          TimingData              => Tmkr_D_GF_posedge,
          TestSignal              => D_ipd,
          TestSignalName          => "D",
          TestDelay               => 0 ns,
          RefSignal               => GF_ipd,
          RefSignalName          => "GF",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_D_GF_posedge_posedge,
          SetupLow                => tsetup_D_GF_negedge_posedge,
          HoldLow                => thold_D_GF_posedge_posedge,
          HoldHigh                 => thold_D_GF_negedge_posedge,
          CheckEnabled            => 
                           TRUE,
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/ILFLX",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
         VitalSetupHoldCheck (
          Violation               => Tviol_GE_G_negedge,
          TimingData              => Tmkr_GE_G_negedge,
          TestSignal              => GE_ipd,
          TestSignalName          => "GE",
          TestDelay               => 0 ns,
          RefSignal               => G_ipd,
          RefSignalName          => "G",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_GE_G_posedge_negedge,
          SetupLow                => tsetup_GE_G_negedge_negedge,
          HoldHigh                => thold_GE_G_posedge_negedge,
          HoldLow                 => thold_GE_G_negedge_negedge,
          CheckEnabled            => 
                           TO_X01((Q_zd) XOR (INT)) /= '0',
          RefTransition           => 'F',
          HeaderMsg               => InstancePath & "/ILFLX",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
         VitalPeriodPulseCheck (
          Violation               => Pviol_GF,
          PeriodData              => PInfo_GF,
          TestSignal              => GF_ipd,
          TestSignalName          => "GF",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_GF_posedge,
          PulseWidthLow           => tpw_GF_negedge,
          CheckEnabled            =>  TRUE,
          HeaderMsg               => InstancePath &"/ILFLX",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
         VitalPeriodPulseCheck (
          Violation               => Pviol_G,
          PeriodData              => PInfo_G,
          TestSignal              => G_ipd,
          TestSignalName          => "G",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_G_posedge,
          PulseWidthLow           => tpw_G_negedge,
          CheckEnabled            =>  TRUE,
          HeaderMsg               => InstancePath &"/ILFLX",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
      end if;

      -------------------------
      --  Functionality Section
      -------------------------
      Violation := Tviol_D_GF_posedge or Tviol_GE_G_negedge or Pviol_GF or Pviol_G;
      VitalStateTable(
        Result => INT,
        PreviousDataIn => PrevData_INT,
        StateTable => ILDI_1_Q_tab,
        DataIn => (
               GF_ipd, D_ipd));
      INT := Violation XOR INT;
      VitalStateTable(
        Result => Q_zd,
        PreviousDataIn => PrevData_Q,
        StateTable => ILFLX_Q_tab,
        DataIn => (
               INT, D_ipd, GF_ipd, GE_ipd, G_ipd));
      Q_zd := Violation XOR Q_zd;

      ----------------------
      --  Path Delay Section
      ----------------------
      VitalPathDelay01 (
       OutSignal => Q,
       GlitchData => Q_GlitchData,
       OutSignalName => "Q",
       OutTemp => Q_zd,
       Paths => (0 => (GE_ipd'last_event, tpd_GE_Q, TRUE),
                 1 => (G_ipd'last_event, tpd_G_Q, TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);

wait on D_ipd, GF_ipd, GE_ipd, G_ipd;
end process;

end ILFLX_V;

