-- entity declaration --
entity IOBUFDS is
   generic(
      TimingChecksOn: Boolean := TRUE;
      InstancePath: STRING := "*";
      Xon: Boolean := True;
      MsgOn: Boolean := False;
      tpd_IO_O                       :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_I_IO                       :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_T_IO                       :	VitalDelayType01z := 
               (0.100 ns, 0.100 ns, 0.100 ns, 0.100 ns, 0.100 ns, 0.100 ns);
      tpd_I_IOB                      :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_T_IOB                      :	VitalDelayType01z := 
               (0.100 ns, 0.100 ns, 0.100 ns, 0.100 ns, 0.100 ns, 0.100 ns);
      tipd_IO                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_IOB                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_I                         :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_T                         :	VitalDelayType01 := (0.000 ns, 0.000 ns));

   port(
      O                              :	out   STD_ULOGIC;
      IO                             :	inout STD_ULOGIC;
      IOB                            :	inout STD_ULOGIC;
      I                              :	in    STD_ULOGIC;
      T                              :	in    STD_ULOGIC);
attribute VITAL_LEVEL0 of IOBUFDS : entity is TRUE;
end IOBUFDS;

-- architecture body --
library IEEE;
use IEEE.VITAL_Primitives.all;
library UNISIM;
use UNISIM.VPKG.all;
architecture IOBUFDS_V of IOBUFDS is
   --attribute VITAL_LEVEL1 of IOBUFDS_V : architecture is TRUE;

   SIGNAL IO_ipd	 : STD_ULOGIC := 'X';
   SIGNAL IOB_ipd	 : STD_ULOGIC := 'X';
   SIGNAL I_ipd	 : STD_ULOGIC := 'X';
   SIGNAL T_ipd	 : STD_ULOGIC := 'X';

begin

   ---------------------
   --  INPUT PATH DELAYs
   ---------------------
   WireDelay : block
   begin
   VitalWireDelay (IO_ipd, IO, tipd_IO);
   VitalWireDelay (IOB_ipd, IOB, tipd_IOB);
   VitalWireDelay (I_ipd, I, tipd_I);
   VitalWireDelay (T_ipd, T, tipd_T);
   end block;
   --------------------
   --  BEHAVIOR SECTION
   --------------------
   VPKGBehavior : process (IO_ipd, I_ipd, T_ipd)


   -- functionality results
   VARIABLE Results : STD_LOGIC_VECTOR(1 to 3) := (others => 'X');
   ALIAS O_zd : STD_LOGIC is Results(1);
   ALIAS IO_zd : STD_LOGIC is Results(2);
   ALIAS IOB_zd : STD_LOGIC is Results(3);

   -- output glitch detection variables
   VARIABLE O_GlitchData	: VitalGlitchDataType;
   VARIABLE IO_GlitchData	: VitalGlitchDataType;
   VARIABLE IOB_GlitchData	: VitalGlitchDataType;

   begin

      -------------------------
      --  Functionality Section
      -------------------------
      if (IO_ipd /= IOB_ipd ) then
        O_zd := TO_X01(IO_ipd);
      else
        O_zd := 'X';
      end if;
      IO_zd := VitalBUFIF0 (data => I_ipd,
              enable => T_ipd);
      IOB_zd := VitalBUFIF0 (data => (NOT I_ipd),
              enable => T_ipd);

      ----------------------
      --  Path Delay Section
      ----------------------
      VitalPathDelay01 (
       OutSignal => O,
       GlitchData => O_GlitchData,
       OutSignalName => "O",
       OutTemp => O_zd,
       Paths => (0 => (IO_ipd'last_event, tpd_IO_O, TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);
      VitalPathDelay01Z (
       OutSignal => IO,
       GlitchData => IO_GlitchData,
       OutSignalName => "IO",
       OutTemp => IO_zd,
       Paths => (0 => (I_ipd'last_event, VitalExtendToFillDelay(tpd_I_IO), TRUE),
                 1 => (T_ipd'last_event, VitalExtendToFillDelay(tpd_T_IO), TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING,
       OutputMap => "UX01ZWLH-");
      VitalPathDelay01Z (
       OutSignal => IOB,
       GlitchData => IOB_GlitchData,
       OutSignalName => "IOB",
       OutTemp => IOB_zd,
       Paths => (0 => (I_ipd'last_event, VitalExtendToFillDelay(tpd_I_IOB), TRUE),
                 1 => (T_ipd'last_event, VitalExtendToFillDelay(tpd_T_IOB), TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING,
       OutputMap => "UX01ZWLH-");

