-- entity declaration --
entity IOBUFS is
   generic(
      TimingChecksOn: Boolean := TRUE;
      InstancePath: STRING := "*";
      Xon: Boolean := True;
      MsgOn: Boolean := False;
      tpd_IO_O                       :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_I_IO                       :	VitalDelayType01z := 
               (0.100 ns, 0.100 ns, 0.100 ns, 0.100 ns, 0.100 ns, 0.100 ns);
      tipd_IO                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_I                         :	VitalDelayType01 := (0.000 ns, 0.000 ns));

   port(
      O                              :	out   STD_ULOGIC;
      IO                             :	inout STD_ULOGIC;
      I                              :	in    STD_ULOGIC);
attribute VITAL_LEVEL0 of IOBUFS : entity is TRUE;
end IOBUFS;

-- architecture body --
library IEEE;
use IEEE.VITAL_Primitives.all;
library UNISIM;
use UNISIM.VPKG.all;
architecture IOBUFS_V of IOBUFS is
   attribute VITAL_LEVEL1 of IOBUFS_V : architecture is TRUE;

   SIGNAL IO_ipd	 : STD_ULOGIC := 'X';
   SIGNAL I_ipd	 : STD_ULOGIC := 'X';

begin

   ---------------------
   --  INPUT PATH DELAYs
   ---------------------
   WireDelay : block
   begin
   VitalWireDelay (IO_ipd, IO, tipd_IO);
   VitalWireDelay (I_ipd, I, tipd_I);
   end block;
   --------------------
   --  BEHAVIOR SECTION
   --------------------
   VPKGBehavior : process (IO_ipd, I_ipd)


   -- functionality results
   VARIABLE Results : STD_LOGIC_VECTOR(1 to 2) := (others => 'X');
   ALIAS O_zd : STD_LOGIC is Results(1);
   ALIAS IO_zd : STD_LOGIC is Results(2);

   -- output glitch detection variables
   VARIABLE O_GlitchData	: VitalGlitchDataType;
   VARIABLE IO_GlitchData	: VitalGlitchDataType;

   begin

      -------------------------
      --  Functionality Section
      -------------------------
      O_zd := TO_X01(IO_ipd);
      IO_zd := VitalBUFIF1 (data => '1',
              enable => I_ipd);

      ----------------------
      --  Path Delay Section
      ----------------------
      VitalPathDelay01 (
       OutSignal => O,
       GlitchData => O_GlitchData,
       OutSignalName => "O",
       OutTemp => O_zd,
       Paths => (0 => (IO_ipd'last_event, tpd_IO_O, TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);
      VitalPathDelay01Z (
       OutSignal => IO,
       GlitchData => IO_GlitchData,
       OutSignalName => "IO",
       OutTemp => IO_zd,
       Paths => (0 => (I_ipd'last_event, VitalExtendToFillDelay(tpd_I_IO), TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING,
       OutputMap => "UX01ZWLH-");

end process;

end IOBUFS_V;

configuration CFG_IOBUFS_V of IOBUFS is
   for IOBUFS_V
   end for;
end CFG_IOBUFS_V;
