----- CELL KEEPER -----
-------------------------------------------------------------------------------
-- Model for Weak Keeper
--
-- Version 1.0.1
--
-- Dhimant Patel, November, 1997.
-------------------------------------------------------------------------------
library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.VITAL_Timing.all;

entity KEEPER is
   generic( InstancePath: STRING := "*");
   port(O : inout STD_ULOGIC);

   attribute VITAL_LEVEL0 of KEEPER : entity is TRUE;

end KEEPER;

architecture KEEPER_V of KEEPER is

   attribute VITAL_LEVEL0 of KEEPER_V : architecture is TRUE;

   signal O_ipd : std_ulogic := 'L';

begin

   process (O)
   begin
       if (O'event) then
           if (O = '1') then
               O_ipd <= 'H';
           elsif (O = '0') then
               O_ipd <= 'L';
           end if;
       end if;
   end process;
 
   O <= O_ipd;

end KEEPER_V;

configuration CFG_KEEPER_V of KEEPER is
   for KEEPER_V
   end for;
end CFG_KEEPER_V;
