-------------------------------------------------------------------------------
-- A V2 Model for a multiplier.
--
-- Version 1.0.0
--
-- Version 1.0.0:
--
--
-- Version 1.0.0:
--     Initial rev.
--     SG, 10/12/99.
-------------------------------------------------------------------------------

library IEEE;
use IEEE.std_logic_1164.all;
use IEEE.VITAL_Timing.all;
library unisim;
use unisim.Vpkg.all;

entity MULT18X18 is
    generic (TimingChecksOn    : boolean := TRUE;
             InstancePath : STRING := "*";
             Xon               : boolean := TRUE;
             MsgOn             : boolean := FALSE;
	     tipd_A : VitalDelayArrayType01 (17 downto 0 ) := (others => (0.0 ns, 0.0 ns));
	     tipd_B : VitalDelayArrayType01 (17 downto 0 ) := (others => (0.0 ns, 0.0 ns));
	     tpd_A_P : VitalDelayArrayType01 (647  downto 0) := (others => (0.1 ns, 0.1 ns));
	     tpd_B_P : VitalDelayArrayType01 (647 downto 0 ) := (others => (0.1 ns, 0.1 ns)));
    port (A	: in STD_LOGIC_VECTOR (17 downto 0);
          B	: in STD_LOGIC_VECTOR (17 downto 0);
	  P	: out STD_LOGIC_VECTOR (35 downto 0) );
attribute VITAL_LEVEL0 of MULT18X18 : entity is TRUE;

end MULT18X18;

library IEEE;
use IEEE.std_logic_1164.all;
use IEEE.VITAL_Timing.all;
library unisim;
use unisim.Vpkg.all;

architecture MULT18X18_V of MULT18X18 is

function INT_TO_SLV(ARG: INTEGER; SIZE: INTEGER) RETURN STD_LOGIC_VECTOR is

	variable result : STD_LOGIC_VECTOR (SIZE-1 downto 0);
        variable temp : integer := ARG;
begin
	temp := ARG;
	for i in 0 to SIZE-1 loop
		if (temp mod 2) = 1 then
			result(i) := '1';
		else
			result(i) := '0';
		end if;
		if temp > 0 then
			temp := temp /2 ;
		elsif (temp > integer'low) then
			temp := (temp-1) / 2;
		else
			temp := temp / 2;
		end if;
	end loop;
	return result;
end;

function COMPLEMENT(ARG: STD_LOGIC_VECTOR ) RETURN STD_LOGIC_VECTOR is

	variable 	RESULT : STD_LOGIC_VECTOR (ARG'left downto 0);
	variable	found1 : std_ulogic := '0';
begin
		for i in  0 to ARG'left  loop
			if (found1 = '0') then
				RESULT(i) := ARG(i);
				if (ARG(i) = '1' ) then
					found1 := '1';
				end if;
			else
				RESULT(i) := NOT ARG(i);
			end if;
                end loop;
		return result;
end;

function VECPLUS(A, B: STD_LOGIC_VECTOR ) RETURN STD_LOGIC_VECTOR is

	variable carry: STD_ULOGIC;
        variable BV, sum: STD_LOGIC_VECTOR(A'left downto 0);

begin

	if (A(A'left) = 'X' or B(B'left) = 'X') then
            sum := (others => 'X');
            return(sum);
        end if;
        carry := '0';
        BV := B;

        for i in 0 to A'left loop
            sum(i) := A(i) xor BV(i) xor carry;
            carry := (A(i) and BV(i)) or
                    (A(i) and carry) or
                    (carry and BV(i));
        end loop;
        return sum;
end;
 
  signal A_ipd : STD_LOGIC_VECTOR(17 downto 0) := (others => '0' );
  signal B_ipd : STD_LOGIC_VECTOR(17 downto 0) := (others => '0' );
			
  attribute VITAL_LEVEL0 of MULT18X18_V : architecture is TRUE;


begin

  ---------------------
   --  INPUT PATH DELAYs
   ---------------------
   WireDelay : block
   begin
   A_DELAY : FOR i IN 17 downto 0 GENERATE
	VitalWireDelay ( A_ipd(i), A(i), tipd_A(i));
   END GENERATE A_DELAY;

   B_DELAY : FOR i IN 17 downto 0 GENERATE
        VitalWireDelay ( B_ipd(i), B(i), tipd_B(i));
   END GENERATE B_DELAY;

  END BLOCK;

  VITALBehaviour : process (A_ipd, B_ipd)

    variable FIRST_TIME : boolean := TRUE;
    variable O_zd,O1_zd, O2_zd : std_logic_vector( A'length+B'length-1 downto 0);
    variable B1_zd,B2_zd : bit_vector(A'length+B'length-1 downto 0);
    variable IA, IB1,Ib2  : integer ;
    variable sign : std_logic := '0';
    variable A_i : std_logic_vector(A'left downto 0);
    variable B_i : std_logic_vector(B'left downto 0);
    VARIABLE O_GlitchData        : VitalGlitchDataArrayType (35 downto 0);

  begin -- process

    if (A_ipd(A'left) = 'X' or B_ipd(B'left) = 'X') then
            O_zd := (others => 'X');
    else
       if (A_ipd(A'left) = '1' ) then
         A_i :=  complement(A_ipd);
       else 
         A_i := A_ipd;
       end if;

       if (B_ipd(B'left)  = '1') then
         B_i := complement(B_ipd);
       else
         B_i := B_ipd;
       end if;

        IA := SLV_TO_INT(A_i);
        IB1 := SLV_TO_INT(B_i (17 downto 9));
        IB2 := SLV_TO_INT(B_i (8 downto 0));


       O1_zd := INT_TO_SLV((IA * IB1), A'length+B'length);
	-- shift I1_zd 9 to the left
           for j in 0 to 8 loop
            O1_zd(A'length+B'length-1 downto 0) := O1_zd(A'length+B'length-2 downto 0) & '0';
           end loop;
       O2_zd := INT_TO_SLV((IA * IB2), A'length+B'length);
       O_zd  := VECPLUS(O1_zd, O2_zd);

       sign := A_ipd(A'left) xor B_ipd(B'left);
       if (sign = '1' ) then
              O_zd := complement(O_zd);
       end if;
    end if;


    VitalPathDelay01 (
       OutSignal => P(35),
       GlitchData => O_GlitchData(35),
       OutSignalName => "P(35)",
       OutTemp => O_zd(35),
       Paths => (0 => (A_ipd(17)'last_event, tpd_A_P(647 - 36*0), TRUE),
                 1 => (A_ipd(16)'last_event, tpd_A_P(647 - 36*1), TRUE),
                 2 => (A_ipd(15)'last_event, tpd_A_P(647 - 36*2), TRUE),
                 3 => (A_ipd(14)'last_event, tpd_A_P(647 - 36*3), TRUE),
                 4 => (A_ipd(13)'last_event, tpd_A_P(647 - 36*4), TRUE),
                 5 => (A_ipd(12)'last_event, tpd_A_P(647 - 36*5), TRUE),
                 6 => (A_ipd(11)'last_event, tpd_A_P(647 - 36*6), TRUE),
                 7 => (A_ipd(10)'last_event, tpd_A_P(647 - 36*7), TRUE),
                 8 => (A_ipd(9)'last_event, tpd_A_P(647 - 36*8), TRUE),
                 9 => (A_ipd(8)'last_event, tpd_A_P(647 - 36*9), TRUE),
                 10 => (A_ipd(7)'last_event, tpd_A_P(647 - 36*10), TRUE),
                 11 => (A_ipd(6)'last_event, tpd_A_P(647 - 36*11), TRUE),
                 12 => (A_ipd(5)'last_event, tpd_A_P(647 - 36*12), TRUE),
                 13 => (A_ipd(4)'last_event, tpd_A_P(647 - 36*13), TRUE),
                 14 => (A_ipd(3)'last_event, tpd_A_P(647 - 36*14), TRUE),
                 15 => (A_ipd(2)'last_event, tpd_A_P(647 - 36*15), TRUE),
                 16 => (A_ipd(1)'last_event, tpd_A_P(647 - 36*16), TRUE),
		 17 => (A_ipd(0)'last_event, tpd_A_P(647 - 36*17), TRUE),
                 18 => (B_ipd(17)'last_event, tpd_B_P(647 - 36*0), TRUE),
		 19 => (B_ipd(16)'last_event, tpd_B_P(647 - 36*1), TRUE),
                 20 => (B_ipd(15)'last_event, tpd_B_P(647 - 36*2), TRUE),
                 21 => (B_ipd(14)'last_event, tpd_B_P(647 - 36*3), TRUE),
                 22 => (B_ipd(13)'last_event, tpd_B_P(647 - 36*4), TRUE),
                 23 => (B_ipd(12)'last_event, tpd_B_P(647 - 36*5), TRUE),
                 24 => (B_ipd(11)'last_event, tpd_B_P(647 - 36*6), TRUE),
                 25 => (B_ipd(10)'last_event, tpd_B_P(647 - 36*7), TRUE),
                 26 => (B_ipd(9)'last_event, tpd_B_P(647 - 36*8), TRUE),
                 27 => (B_ipd(8)'last_event, tpd_B_P(647 - 36*9), TRUE),
                 28 => (B_ipd(7)'last_event, tpd_B_P(647 - 36*10), TRUE),
                 29 => (B_ipd(6)'last_event, tpd_B_P(647 - 36*11), TRUE),
                 30 => (B_ipd(5)'last_event, tpd_B_P(647 - 36*12), TRUE),
                 31 => (B_ipd(4)'last_event, tpd_B_P(647 - 36*13), TRUE),
                 32 => (B_ipd(3)'last_event, tpd_B_P(647 - 36*14), TRUE),
                 33 => (B_ipd(2)'last_event, tpd_B_P(647 - 36*15), TRUE),
                 34 => (B_ipd(1)'last_event, tpd_B_P(647 - 36*16), TRUE),
                 35 => (B_ipd(0)'last_event, tpd_B_P(647 - 36*17), TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);

    VitalPathDelay01 (
       OutSignal => P(34),
       GlitchData => O_GlitchData(34),
       OutSignalName => "P(34)",
       OutTemp => O_zd(34),
       Paths => (0 => (A_ipd(17)'last_event, tpd_A_P((647 -1 ) - 36*0), TRUE),
                 1 => (A_ipd(16)'last_event, tpd_A_P((647 -1 ) - 36*1), TRUE),
                 2 => (A_ipd(15)'last_event, tpd_A_P((647 -1 ) - 36*2), TRUE),
                 3 => (A_ipd(14)'last_event, tpd_A_P((647 -1 ) - 36*3), TRUE),
                 4 => (A_ipd(13)'last_event, tpd_A_P((647 -1 ) - 36*4), TRUE),
                 5 => (A_ipd(12)'last_event, tpd_A_P((647 -1 ) - 36*5), TRUE),
                 6 => (A_ipd(11)'last_event, tpd_A_P((647 -1 ) - 36*6), TRUE),
                 7 => (A_ipd(10)'last_event, tpd_A_P((647 -1 ) - 36*7), TRUE),
                 8 => (A_ipd(9)'last_event, tpd_A_P((647 -1 ) - 36*8), TRUE),
                 9 => (A_ipd(8)'last_event, tpd_A_P((647 -1 ) - 36*9), TRUE),
                 10 => (A_ipd(7)'last_event, tpd_A_P((647 -1 ) - 36*10), TRUE),
                 11 => (A_ipd(6)'last_event, tpd_A_P((647 -1 ) - 36*11), TRUE),
                 12 => (A_ipd(5)'last_event, tpd_A_P((647 -1 ) - 36*12), TRUE),
                 13 => (A_ipd(4)'last_event, tpd_A_P((647 -1 ) - 36*13), TRUE),
