----- CELL MULT_AND -----
library IEEE;
use IEEE.STD_LOGIC_1164.all;
library IEEE;
use IEEE.VITAL_Timing.all;


-- entity declaration --
entity MULT_AND is
   generic(
      TimingChecksOn: Boolean := TRUE;
      InstancePath: STRING := "*";
      Xon: Boolean := True;
      MsgOn: Boolean := False;
      tpd_I0_LO                      :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_I1_LO                      :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tipd_I1                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_I0                        :	VitalDelayType01 := (0.000 ns, 0.000 ns));

   port(
      LO                             :	out   STD_ULOGIC;
      I1                             :	in    STD_ULOGIC;
      I0                             :	in    STD_ULOGIC);
attribute VITAL_LEVEL0 of MULT_AND : entity is TRUE;
end MULT_AND;

-- architecture body --
library IEEE;
use IEEE.VITAL_Primitives.all;
library UNISIM;
use UNISIM.VPKG.all;
architecture MULT_AND_V of MULT_AND is
   attribute VITAL_LEVEL1 of MULT_AND_V : architecture is TRUE;

   SIGNAL I1_ipd	 : STD_ULOGIC := 'X';
   SIGNAL I0_ipd	 : STD_ULOGIC := 'X';

begin

   ---------------------
   --  INPUT PATH DELAYs
   ---------------------
   WireDelay : block
   begin
   VitalWireDelay (I1_ipd, I1, tipd_I1);
   VitalWireDelay (I0_ipd, I0, tipd_I0);
   end block;
   --------------------
   --  BEHAVIOR SECTION
   --------------------
   VITALBehavior : process (I1_ipd, I0_ipd)


   -- functionality results
   VARIABLE Results : STD_LOGIC_VECTOR(1 to 1) := (others => 'X');
   ALIAS LO_zd : STD_LOGIC is Results(1);

   -- output glitch detection variables
   VARIABLE LO_GlitchData	: VitalGlitchDataType;

   begin

      -------------------------
      --  Functionality Section
      -------------------------
      LO_zd := (I0_ipd) AND (I1_ipd);

      ----------------------
      --  Path Delay Section
      ----------------------
      VitalPathDelay01 (
       OutSignal => LO,
       GlitchData => LO_GlitchData,
       OutSignalName => "LO",
       OutTemp => LO_zd,
       Paths => (0 => (I0_ipd'last_event, tpd_I0_LO, TRUE),
                 1 => (I1_ipd'last_event, tpd_I1_LO, TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);

end process;

end MULT_AND_V;

configuration CFG_MULT_AND_V of MULT_AND is
   for MULT_AND_V
   end for;
end CFG_MULT_AND_V;
