library IEEE;
use IEEE.STD_LOGIC_1164.all;
library IEEE;
use IEEE.VITAL_Timing.all;


-- entity declaration --
entity MUXCY is
   generic(
      TimingChecksOn: Boolean := TRUE;
      InstancePath: STRING := "*";
      Xon: Boolean := True;
      MsgOn: Boolean := False;
      tpd_DI_O                       :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_CI_O                       :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_S_O                        :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tipd_DI                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_CI                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_S                         :	VitalDelayType01 := (0.000 ns, 0.000 ns));

   port(
      O                              :	out   STD_ULOGIC;
      DI                             :	in    STD_ULOGIC;
      CI                             :	in    STD_ULOGIC;
      S                              :	in    STD_ULOGIC);
attribute VITAL_LEVEL0 of MUXCY : entity is TRUE;
end MUXCY;

-- architecture body --
library IEEE;
use IEEE.VITAL_Primitives.all;
library UNISIM;
use UNISIM.VPKG.all;
architecture MUXCY_V of MUXCY is
   attribute VITAL_LEVEL1 of MUXCY_V : architecture is TRUE;

   SIGNAL DI_ipd	 : STD_ULOGIC := 'X';
   SIGNAL CI_ipd	 : STD_ULOGIC := 'X';
   SIGNAL S_ipd	 : STD_ULOGIC := 'X';

begin

   ---------------------
   --  INPUT PATH DELAYs
   ---------------------
   WireDelay : block
   begin
   VitalWireDelay (DI_ipd, DI, tipd_DI);
   VitalWireDelay (CI_ipd, CI, tipd_CI);
   VitalWireDelay (S_ipd, S, tipd_S);
   end block;
   --------------------
   --  BEHAVIOR SECTION
   --------------------
   VITALBehavior : process (DI_ipd, CI_ipd, S_ipd)


   -- functionality results
   VARIABLE Results : STD_LOGIC_VECTOR(1 to 1) := (others => 'X');
   ALIAS O_zd : STD_LOGIC is Results(1);

   -- output glitch detection variables
   VARIABLE O_GlitchData	: VitalGlitchDataType;

   begin

      -------------------------
      --  Functionality Section
      -------------------------
      O_zd := VitalMUX
