library UNISIM;
use UNISIM.VPKG.all;
architecture OFDTXI_S_24_V of OFDTXI_S_24 is
   attribute VITAL_LEVEL1 of OFDTXI_S_24_V : architecture is TRUE;

   SIGNAL D_ipd	 : STD_ULOGIC := 'X';
   SIGNAL C_ipd	 : STD_ULOGIC := 'X';
   SIGNAL CE_ipd	 : STD_ULOGIC := 'X';
   SIGNAL T_ipd	 : STD_ULOGIC := 'X';

begin

   ---------------------
   --  INPUT PATH DELAYs
   ---------------------
   WireDelay : block
   begin
   VitalWireDelay (D_ipd, D, tipd_D);
   VitalWireDelay (C_ipd, C, tipd_C);
   VitalWireDelay (CE_ipd, CE, tipd_CE);
   VitalWireDelay (T_ipd, T, tipd_T);
   end block;
   --------------------
   --  BEHAVIOR SECTION
   --------------------
   VITALBehavior : process (D_ipd, C_ipd, CE_ipd, T_ipd)

   -- timing check results
   VARIABLE Tviol_D_C_posedge	: STD_ULOGIC := '0';
   VARIABLE Tmkr_D_C_posedge	: VitalTimingDataType := VitalTimingDataInit;
   VARIABLE Tviol_CE_C_posedge	: STD_ULOGIC := '0';
   VARIABLE Tmkr_CE_C_posedge	: VitalTimingDataType := VitalTimingDataInit;
   VARIABLE Pviol_C	: STD_ULOGIC := '0';
   VARIABLE PInfo_C	: VitalPeriodDataType := VitalPeriodDataInit;

   -- functionality results
   VARIABLE Violation : STD_ULOGIC := '0';
   VARIABLE PrevData_O : STD_LOGIC_VECTOR(0 to 4);
   VARIABLE D_delayed : STD_ULOGIC := 'X';
   VARIABLE C_delayed : STD_ULOGIC := 'X';
   VARIABLE CE_delayed : STD_ULOGIC := 'X';
   VARIABLE Results : STD_LOGIC_VECTOR(1 to 1) := (others => 'X');
   ALIAS O_zdi : STD_LOGIC is Results(1);
   VARIABLE O_zd : STD_ULOGIC := 'X';

   -- output glitch detection variables
   VARIABLE O_GlitchData	: VitalGlitchDataType;

   begin

      ------------------------
      --  Timing Check Section
      ------------------------
      if (TimingChecksOn) then
         VitalSetupHoldCheck (
          Violation               => Tviol_D_C_posedge,
          TimingData              => Tmkr_D_C_posedge,
          TestSignal              => D_ipd,
          TestSignalName          => "D",
          TestDelay               => 0 ns,
          RefSignal               => C_ipd,
          RefSignalName          => "C",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_D_C_posedge_posedge,
          SetupLow                => tsetup_D_C_negedge_posedge,
          HoldLow                => thold_D_C_posedge_posedge,
          HoldHigh                 => thold_D_C_negedge_posedge,
          CheckEnabled            => 
                           TO_X01(CE_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/OFDTXI_S_24",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
         VitalSetupHoldCheck (
          Violation               => Tviol_CE_C_posedge,
          TimingData              => Tmkr_CE_C_posedge,
          TestSignal              => CE_ipd,
          TestSignalName          => "CE",
          TestDelay               => 0 ns,
          RefSignal               => C_ipd,
          RefSignalName          => "C",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_CE_C_posedge_posedge,
          SetupLow                => tsetup_CE_C_negedge_posedge,
          HoldLow                => thold_CE_C_posedge_posedge,
          HoldHigh                 => thold_CE_C_negedge_posedge,
          CheckEnabled            => 
                           TO_X01((O_zdi) XOR (D_ipd)) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/OFDTXI_S_24",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
         VitalPeriodPulseCheck (
          Violation               => Pviol_C,
          PeriodData              => PInfo_C,
          TestSignal              => C_ipd,
          TestSignalName          => "C",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_C_posedge,
          PulseWidthLow           => tpw_C_negedge,
          CheckEnabled            =>  TRUE,
          HeaderMsg               => InstancePath &"/OFDTXI_S_24",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
      end if;

      -------------------------
      --  Functionality Section
      -------------------------
      Violation := Tviol_D_C_posedge or Pviol_C or Tviol_CE_C_posedge;
      VitalStateTable(
        Result => O_zdi,
        PreviousDataIn => PrevData_O,
        StateTable => FDE_Q_tab,
        DataIn => (
               C_delayed, O_zdi, D_delayed, CE_delayed, C_ipd));
      O_zdi := Violation XOR O_zdi;
      O_zd := VitalBUFIF0 (data => O_zdi,
             enable => T_ipd);
      D_delayed := D_ipd;
      C_delayed := C_ipd;
      CE_delayed := CE_ipd;

      ----------------------
      --  Path Delay Section
      ----------------------
      VitalPathDelay01Z (
       OutSignal => O,
       GlitchData => O_GlitchData,
       OutSignalName => "O",
       OutTemp => O_zd,
       Paths => (0 => (T_ipd'last_event, VitalExtendToFillDelay(tpd_T_O), TRUE),
                 1 => (C_ipd'last_event, VitalExtendToFillDelay(tpd_C_O), TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING,
       OutputMap => "UX01ZWLH-");

end process;

end OFDTXI_S_24_V;

configuration CFG_OFDTXI_S_24_V of OFDTXI_S_24 is
   for OFDTXI_S_24_V
   end for;
end CFG_OFDTXI_S_24_V;
