----- CELL OSC -----
-----------------------------------------------------------------------------
-- Model for XC3100A Oscillator Cell
--
-- Version 1.0.1
--
-- Dhimant Patel, August 27, 1996.

-- Version 1.0.2, DP, 06/18/97
-- 1. Changed default value of PERIOD from 100 ns to 0 ns.
-- 2. Incorporated error checking to ensure that PERIOD > 0 ns.
-- 3. Incorporated error checking to ensure that 0 < FRACTION_ON < 1.
-----------------------------------------------------------------------------
library IEEE;
use IEEE.std_logic_1164.all;
use IEEE.VITAL_Timing.all;

entity OSC is
    generic ( InstancePath : STRING := "*";
              PERIOD : Time := 0 ns;
              FRACTION_ON : real := 0.5 );
    port( O : out std_ulogic := '0' );
    attribute VITAL_LEVEL0 of OSC : entity is TRUE;
end OSC;

architecture OSC_V of OSC is

attribute VITAL_LEVEL0 of OSC_V : architecture is TRUE;

constant TIME_ON : Time := (FRACTION_ON * PERIOD);
constant TIME_OFF : Time := (PERIOD - TIME_ON);

begin
    CLOCK: process
    begin
        if (PERIOD <= 0 ns) then
            assert FALSE report
            "*** Error: A positive value of PERIOD must be specified ***"
            severity failure;
            wait;
        elsif (FRACTION_ON <= 0.0 OR FRACTION_ON >= 1.0) then
            assert FALSE report
            "*** Error: A value of FRACTION_ON between 0 and 1 must be specified ***"
            severity failure;
            wait;
        else
            O <= '0';
            wait for TIME_OFF;
            O <= '1';
            wait for TIME_ON;
        end if;
    end process CLOCK;
end OSC_V;

configuration CFG_OSC_V of OSC is
    for OSC_V
    end for;
end CFG_OSC_V;
----- CELL OSC4 -----
-----------------------------------------------------------------------------
-- Model for XC4000E/EX Oscillator Cell
--
-- Version 1.0.1
--
-- Dhimant Patel, August 27, 1996.

-- Version 1.0.2, DP, 06/18/97
-- 1. Changed default value of PERIOD_8M from 125 ns to 0 ns.
-- 2. Changed name of function SEL_ERROR to ERROR_CHECK.
-- 3. Modified ERROR_CHECK to check for PERIOD_8M <= 0 ns.

-- Version 1.0.3, DP, 05/18/98
-- 1. Changed default value of PERIOD_8M from 0 ns to 100 ns.
-----------------------------------------------------------------------------
library IEEE;
use IEEE.std_logic_1164.all;
use IEEE.VITAL_Timing.all;

entity OSC4 is
    generic ( InstancePath : STRING := "*";
              PERIOD_8M : Time := 100 ns;
              SEL_F500K : Boolean := FALSE;
              SEL_F16K : Boolean := FALSE;
              SEL_F490 : Boolean := FALSE;
              SEL_F15 : Boolean := FALSE);
    port( F8M : out std_ulogic := '0'; 
          F500K : out std_ulogic := '0'; 
          F16K : out std_ulogic := '0'; 
          F490 : out std_ulogic := '0'; 
          F15 : out std_ulogic := '0'); 
    attribute VITAL_LEVEL0 of OSC4 : entity is TRUE;
end OSC4;

architecture OSC4_V of OSC4 is

attribute VITAL_LEVEL0 of OSC4_V : architecture is TRUE;

constant HALF_PERIOD_8M : Time := (0.5 * PERIOD_8M);
constant HALF_PERIOD_F500K : Time := (16.0 * HALF_PERIOD_8M);
constant HALF_PERIOD_F16K : Time := (32.0 * HALF_PERIOD_F500K);
constant HALF_PERIOD_F490 : Time := (32.0 * HALF_PERIOD_F16K);
constant HALF_PERIOD_F15 : Time := (32.0 * HALF_PERIOD_F490);

function ERROR_CHECK ( SEL1, SEL2, SEL3, SEL4 : in Boolean; PERIOD : in Time ) return Boolean is
variable NSEL : integer := 0;
variable ERR : Boolean := FALSE;
begin
    if (SEL1) then NSEL := NSEL + 1; end if;
    if (SEL2) then NSEL := NSEL + 1; end if;
    if (SEL3) then NSEL := NSEL + 1; end if;
    if (SEL4) then NSEL := NSEL + 1; end if;
    if (NSEL > 2) then
        ERR := TRUE;
        assert FALSE report
        "*** Error: Can only set two of SEL_F500K, SEL_F16K, SEL_F490, and SEL_F15 to TRUE ***"
        severity failure;
    elsif (PERIOD <= 0 ns) then
        ERR := TRUE;
        assert FALSE report
        "*** Error: a positive value of PERIOD_8M must be specified ***"
        severity failure;
    end if;
    return ERR;
end ERROR_CHECK;

constant HAS_ERROR : Boolean := ERROR_CHECK ( SEL_F500K, SEL_F16K, SEL_F490, SEL_F15, PERIOD_8M );

begin

    CLOCK_8M: process
    begin
        if (NOT HAS_ERROR) then
