----- CELL OSC5 -----
-----------------------------------------------------------------------------
-- Model for XC5200 Oscillator Cell Using Internal Clock
--
-- Version 1.0.1
--
-- Dhimant Patel, August 27, 1996.

-- Version 1.0.2, DP, 06/18/97
-- 1. Changed default value of PERIOD from 62.5 ns to 0 ns.
-- 2. Incorporated error checking to ensure that PERIOD > 0 ns.

-- Version 1.0.3, DP, 05/18/98
-- 1. Changed default value of PERIOD from 0 ns to 55.6 ns.
-----------------------------------------------------------------------------
library IEEE;
use IEEE.std_logic_1164.all;
use IEEE.VITAL_Timing.all;

entity OSC5 is
    generic ( InstancePath : STRING := "*";
              PERIOD : Time := 55.6 ns;
              DIVIDE1_BY : integer := 4;
              DIVIDE2_BY : integer := 2);
    port( OSC1 : out std_ulogic := '0'; 
          OSC2 : out std_ulogic := '0'); 
    attribute VITAL_LEVEL0 of OSC5 : entity is TRUE;
end OSC5;

architecture OSC5_V of OSC5 is

attribute VITAL_LEVEL0 of OSC5_V : architecture is TRUE;

type DIV1_ARRAY is array (0 to 3) of integer;
type DIV2_ARRAY is array (0 to 7) of integer;

constant DIVISOR1 : DIV1_ARRAY := (4, 16, 64, 256);
constant DIVISOR2 : DIV2_ARRAY := (2, 8, 32, 128, 1024, 4096, 16394, 65536);

constant HALF_PERIOD1 : Time := (0.5 * PERIOD * DIVIDE1_BY);
constant HALF_PERIOD2 : Time := (0.5 * PERIOD * DIVIDE2_BY);

constant DIV1_ERROR : string := "(4, 16, 64, 256)";
constant DIV2_ERROR : string := "(2, 8, 32, 128, 1024, 4096, 16394, 65536)";

begin

    CLOCK1: process
    variable COUNT1 : integer := 0;
    variable FREQ1 : std_ulogic := '0';
    variable VALID1 : boolean := FALSE;
    begin
        for I1 in DIVISOR1'range loop
            if (DIVIDE1_BY = DIVISOR1(I1)) then
                VALID1 := TRUE;
            end if;
        end loop;
        if (NOT VALID1) then
            assert FALSE report
            "*** Error: DIVIDE1_BY is not one of " & DIV1_ERROR & " ***"
            severity failure;
            wait;
        elsif (PERIOD <= 0 ns) then
            assert FALSE report
            "*** Error: a positive value of PERIOD must be specified ***"
            severity failure;
            wait;
        else
            OSC1 <= '0';
            wait for HALF_PERIOD1;
            OSC1 <= '1';
            wait for HALF_PERIOD1;
        end if;
    end process CLOCK1;

    CLOCK2: process
    variable COUNT2 : integer := 0;
    variable FREQ2 : std_ulogic := '0';
    variable VALID2 : boolean := FALSE;
    begin
        for I2 in DIVISOR2'range loop
            if (DIVIDE2_BY = DIVISOR2(I2)) then
                VALID2 := TRUE;
            end if;
        end loop;
        if (NOT VALID2) then
            assert FALSE report
            "*** Error: DIVIDE2_BY is not one of " & DIV2_ERROR & " ***"
            severity failure;
            wait;
        elsif (PERIOD <= 0 ns) then
            assert FALSE report
            "*** Error: a positive value of PERIOD must be specified ***"
            severity failure;
            wait;
        else
            OSC2 <= '0';
            wait for HALF_PERIOD2;
            OSC2 <= '1';
            wait for HALF_PERIOD2;
        end if;
    end process CLOCK2;

end OSC5_V;

configuration CFG_OSC5_V of OSC5 is
    for OSC5_V
    end for;
end CFG_OSC5_V;
----- CELL OSC52 -----
-----------------------------------------------------------------------------
-- Model for XC5200 Oscillator Cell Using Either User-Supplied or Internal
-- Clock
--
-- Version 1.0.1
--
-- Dhimant Patel, August 27, 1996.

-- Version 1.0.2, DP, 06/18/97
-- 1. Changed default value of PERIOD from 62.5 ns to 0 ns.
-- 2. Incorporated error checking to ensure that PERIOD > 0 ns.

-- Version 1.0.3, DP, 05/18/97
-- 1. Changed default value of PERIOD from 0 ns to 55.6 ns.
-----------------------------------------------------------------------------
library IEEE;
use IEEE.std_logic_1164.all;
use IEEE.VITAL_Timing.all;

entity OSC52 is
    generic ( InstancePath : STRING := "*";
              OSC : STRING := "INTERNAL"; 
              PERIOD : Time := 0 ns;
              DIVIDE1_BY : integer := 4;
              DIVIDE2_BY : integer := 2);
    port( C : in std_ulogic := '0'; 
          OSC1 : out std_ulogic := '0'; 
          OSC2 : out std_ulogic := '0'); 
    attribute VITAL_LEVEL0 of OSC52 : entity is TRUE;
end OSC52;

architecture OSC52_V of OSC52 is

attribute VITAL_LEVEL0 of OSC52_V : architecture is TRUE;

type DIV1_ARRAY is array (0 to 3) of integer;
type DIV2_ARRAY is array (0 to 7) of integer;

constant DIVISOR1 : DIV1_ARRAY := (4, 16, 64, 256);
constant DIVISOR2 : DIV2_ARRAY := (2, 8, 32, 128, 1024, 4096, 16394, 65536);

constant HALF_DIVIDE1 : integer := (DIVIDE1_BY / 2);
constant HALF_DIVIDE2 : integer := (DIVIDE2_BY / 2);

constant HALF_PERIOD1 : Time := (0.5 * PERIOD * DIVIDE1_BY);
constant HALF_PERIOD2 : Time := (0.5 * PERIOD * DIVIDE2_BY);

constant OSC_ERROR : string := "(INTERNAL, USER)";
constant DIV1_ERROR : string := "(4, 16, 64, 256)";
constant DIV2_ERROR : string := "(2, 8, 32, 128, 1024, 4096, 16394, 65536)";

begin

    CLOCK1: process
    variable COUNT1 : integer := 0;
    variable FREQ1 : std_ulogic := '0';
    variable VALID1 : boolean := FALSE;
    begin
        for I1 in DIVISOR1'range loop
            if (DIVIDE1_BY = DIVISOR1(I1)) then
                VALID1 := TRUE;
            end if;
        end loop;
        if (NOT VALID1) then
            assert FALSE report
            "*** Error: DIVIDE1_BY is not one of " & DIV1_ERROR & " ***"
            severity failure;
            wait;
        elsif (PERIOD <= 0 ns) then
            assert FALSE report
            "*** Error: a positive value of PERIOD must be specified ***"
            severity failure;
            wait;
        else
            if (OSC = "USER") then
                wait until (C'event and C = '1');
                COUNT1 := COUNT1 + 1;
                if (COUNT1 = HALF_DIVIDE1) then
                    COUNT1 := 0;
                    FREQ1 := not FREQ1;
                    OSC1 <= FREQ1;
                end if;
            elsif (OSC = "INTERNAL") then
                OSC1 <= '0';
                wait for HALF_PERIOD1;
                OSC1 <= '1';
                wait for HALF_PERIOD1;
            else
                assert FALSE report
                "*** Error: OSC is not one of " & OSC_ERROR & " ***"
                severity failure;
                wait;
            end if;
        end if;
    end process CLOCK1;

    CLOCK2: process
    variable COUNT2 : integer := 0;
    variable FREQ2 : std_ulogic := '0';
    variable VALID2 : boolean := FALSE;
    begin
        for I2 in DIVISOR2'range loop
            if (DIVIDE2_BY = DIVISOR2(I2)) then
                VALID2 := TRUE;
            end if;
        end loop;
        if (NOT VALID2) then
            assert FALSE report
            "*** Error: DIVIDE2_BY is not one of " & DIV2_ERROR & " ***"
            severity failure;
            wait;
        elsif (PERIOD <= 0 ns) then
            assert FALSE report
            "*** Error: a positive value of PERIOD must be specified ***"
            severity failure;
            wait;
        else
            if (OSC = "USER") then
                wait until (C'event and C = '1');
                COUNT2 := COUNT2 + 1;
                if (COUNT2 = HALF_DIVIDE2) then
                    COUNT2 := 0;
                    FREQ2 := not FREQ2;
                    OSC2 <= FREQ2;
                end if;
            elsif (OSC = "INTERNAL") then
                OSC2 <= '0';
                wait for HALF_PERIOD2;
                OSC2 <= '1';
                wait for HALF_PERIOD2;
            else
                assert FALSE report
                "*** Error: OSC is not one of " & OSC_ERROR & " ***"
                severity failure;
                wait;
            end if;
        end if;
    end process CLOCK2;

end OSC52_V;

configuration CFG_OSC52_V of OSC52 is
    for OSC52_V
    end for;
end CFG_OSC52_V;
