        O    : out std_ulogic
       ); 
attribute VITAL_LEVEL0 of RAM128X1S : entity is TRUE;

end RAM128X1S;

-----------------------------------------------------------------------------

architecture RAM128X1S_V of RAM128X1S is

  attribute VITAL_LEVEL0 of RAM128X1S_V : architecture is TRUE;

  -- Local signals used to propagate input wire delay

  signal A0_ipd   : std_ulogic := 'X';
  signal A1_ipd   : std_ulogic := 'X';
  signal A2_ipd   : std_ulogic := 'X';
  signal A3_ipd   : std_ulogic := 'X';
  signal A4_ipd   : std_ulogic := 'X';
  signal A5_ipd   : std_ulogic := 'X';
  signal A6_ipd   : std_ulogic := 'X';

  signal D_ipd    : std_ulogic := 'X';
  signal WE_ipd   : std_ulogic := 'X';
  signal WCLK_ipd : std_ulogic := 'X';

  signal MEM        : std_logic_vector( 128 downto 0 ) := ('X' & To_StdLogicVector(INIT) );

begin -- architecture

  ----------------------
  --  Wire Delay Section
  ----------------------
  WireDelay : block
  begin
    VitalWireDelay (A0_ipd,   A0,   tipd_A0);
    VitalWireDelay (A1_ipd,   A1,   tipd_A1);
    VitalWireDelay (A2_ipd,   A2,   tipd_A2);
    VitalWireDelay (A3_ipd,   A3,   tipd_A3);
    VitalWireDelay (A4_ipd,   A4,   tipd_A4);
    VitalWireDelay (A5_ipd,   A5,   tipd_A5);
    VitalWireDelay (A6_ipd,   A6,   tipd_A6);

    VitalWireDelay (D_ipd,    D,    tipd_D);
    VitalWireDelay (WE_ipd,   WE,   tipd_WE);
    VitalWireDelay (WCLK_ipd, WCLK, tipd_WCLK);
  end block;

  --------------------
  -- RAM128X1S Behavior
  --------------------
  VITALReadBehavior : process(A0_ipd, A1_ipd, A2_ipd, A3_ipd, A4_ipd, A5_ipd, A6_ipd, WCLK_ipd, MEM)
         Variable Index      : integer  := 128 ;
         variable O_zd      : std_ulogic := 'X';
         variable O_GlitchData : VitalGlitchDataType;
         variable Address : std_logic_vector( 6 downto 0);

  begin -- process
        Address := (A6_ipd,A5_ipd, A4_ipd,A3_ipd,A2_ipd,A1_ipd,A0_ipd);
        Index      := SLV_TO_INT(SLV => Address);
        O_zd       := MEM(Index);

    ----------------------
    --  Path Delay Section
    ----------------------
    VitalPathDelay01 (
      OutSignal => O,
      GlitchData => O_GlitchData,
      OutSignalName => "O",
      OutTemp => O_zd,
      Paths => (0 => (WCLK_ipd'last_event,  tpd_WCLK_O,  TRUE),
                1 => (A0_ipd'last_event, tpd_A0_O, TRUE),
                2 => (A1_ipd'last_event, tpd_A1_O, TRUE),
                3 => (A2_ipd'last_event, tpd_A2_O, TRUE),
                4 => (A3_ipd'last_event, tpd_A3_O, TRUE),
                5 => (A4_ipd'last_event, tpd_A4_O, TRUE),
                6 => (A5_ipd'last_event, tpd_A5_O, TRUE),
                7 => (A5_ipd'last_event, tpd_A5_O, TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

  end process VITALReadBehavior;

  VITALWriteBehavior : process

    -- Local variables used for functionality
    variable Violation : std_ulogic := '0';
    variable PrevData  : std_logic_vector(0 to 4) := (others => '0');
    variable WCLK_prev  : std_ulogic := 'X';
    variable D_prev  : std_ulogic := 'X';
    variable WE_prev  : std_ulogic := 'X';
    variable O_zd      : std_ulogic := 'X';
    variable FIRST_TIME : boolean := TRUE;
    Variable Index      : integer  := 128;

    -- Local variables used for timing checks
    variable Tviol_D_WCLK_posedge  : std_ulogic := '0';
    variable Tviol_WE_WCLK_posedge : std_ulogic := '0';
    variable Tviol_A0_WCLK_posedge : std_ulogic := '0';
    variable Tviol_A1_WCLK_posedge : std_ulogic := '0';
    variable Tviol_A2_WCLK_posedge : std_ulogic := '0';
    variable Tviol_A3_WCLK_posedge : std_ulogic := '0';
    variable Tviol_A4_WCLK_posedge : std_ulogic := '0';
    variable Tviol_A5_WCLK_posedge : std_ulogic := '0';
    variable Tviol_A6_WCLK_posedge : std_ulogic := '0';

    variable Tmkr_D_WCLK_posedge   : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_WE_WCLK_posedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A0_WCLK_posedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A1_WCLK_posedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A2_WCLK_posedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A3_WCLK_posedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A4_WCLK_posedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A5_WCLK_posedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A6_WCLK_posedge  : VitalTimingDataType := VitalTimingDataInit;

    variable PViol_WCLK : std_ulogic := '0';
    variable PInfo_WCLK : VitalPeriodDataType := VitalPeriodDataInit;

    variable Address : std_logic_vector (6 downto 0);

    -- Local variables used for functionality

  begin -- process
 
    if (FIRST_TIME) then
        wait until ((WCLK_ipd = '0' or WCLK_ipd = '1') and
                    (D_ipd = '0' or D_ipd = '1') and
                    (WE_ipd = '0' or WE_ipd = '1') and
                    (A6_ipd = '0' or A6_ipd = '1') and
                    (A5_ipd = '0' or A5_ipd = '1') and
                    (A4_ipd = '0' or A4_ipd = '1') and
                    (A3_ipd = '0' or A3_ipd = '1') and
                    (A2_ipd = '0' or A2_ipd = '1') and
                    (A1_ipd = '0' or A1_ipd = '1') and
                    (A0_ipd = '0' or A0_ipd = '1'));

        WCLK_prev  := WCLK_ipd;
        WE_prev    := WE_ipd;
        D_prev     := D_ipd;
        Address    := (A6_ipd, A5_ipd, A4_ipd, A3_ipd, A2_ipd, A1_ipd, A0_ipd);
        Index      := SLV_TO_INT(SLV => Address);
        O_zd       := MEM(Index);
        FIRST_TIME := FALSE;
    end if;
    ------------------------
    --  Timing Check Section
    ------------------------
    if (TimingChecksOn ) then

         VitalSetupHoldCheck (
          Violation               => Tviol_D_WCLK_posedge,
          TimingData              => Tmkr_D_WCLK_posedge,
          TestSignal              => D_ipd,
          TestSignalName          => "D",
          TestDelay               => 0 ns,
          RefSignal               => WCLK_ipd,
          RefSignalName           => "WCLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_D_WCLK_posedge_posedge,
          SetupLow                => tsetup_D_WCLK_negedge_posedge,
          HoldLow                => thold_D_WCLK_posedge_posedge,
          HoldHigh                 => thold_D_WCLK_negedge_posedge,
          CheckEnabled            => TO_X01(WE_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM128X1S",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_WE_WCLK_posedge,
          TimingData              => Tmkr_WE_WCLK_posedge,
          TestSignal              => WE_ipd,
          TestSignalName          => "WE",
          TestDelay               => 0 ns,
          RefSignal               => WCLK_ipd,
          RefSignalName           => "WCLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_WE_WCLK_posedge_posedge,
          SetupLow                => tsetup_WE_WCLK_negedge_posedge,
          HoldLow                => thold_WE_WCLK_posedge_posedge,
          HoldHigh                 => thold_WE_WCLK_negedge_posedge,
          CheckEnabled            => TRUE,
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM128X1S",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A0_WCLK_posedge,
          TimingData              => Tmkr_A0_WCLK_posedge,
          TestSignal              => A0_ipd,
          TestSignalName          => "A0",
          TestDelay               => 0 ns,
          RefSignal               => WCLK_ipd,
          RefSignalName           => "WCLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_A0_WCLK_posedge_posedge,
          SetupLow                => tsetup_A0_WCLK_negedge_posedge,
          HoldLow                => thold_A0_WCLK_posedge_posedge,
          HoldHigh                 => thold_A0_WCLK_negedge_posedge,
          CheckEnabled            => TO_X01(WE_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM128X1S",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A1_WCLK_posedge,
          TimingData              => Tmkr_A1_WCLK_posedge,
          TestSignal              => A1_ipd,
          TestSignalName          => "A1",
          TestDelay               => 0 ns,
          RefSignal               => WCLK_ipd,
          RefSignalName           => "WCLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_A1_WCLK_posedge_posedge,
          SetupLow                => tsetup_A1_WCLK_negedge_posedge,
          HoldLow                => thold_A1_WCLK_posedge_posedge,
          HoldHigh                 => thold_A1_WCLK_negedge_posedge,
          CheckEnabled            => TO_X01(WE_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM128X1S",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A2_WCLK_posedge,
          TimingData              => Tmkr_A2_WCLK_posedge,
          TestSignal              => A2_ipd,
          TestSignalName          => "A2",
          TestDelay               => 0 ns,
          RefSignal               => WCLK_ipd,
          RefSignalName           => "WCLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_A2_WCLK_posedge_posedge,
          SetupLow                => tsetup_A2_WCLK_negedge_posedge,
          HoldLow                => thold_A2_WCLK_posedge_posedge,
          HoldHigh                 => thold_A2_WCLK_negedge_posedge,
          CheckEnabled            => TO_X01(WE_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM128X1S",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A3_WCLK_posedge,
          TimingData              => Tmkr_A3_WCLK_posedge,
          TestSignal              => A3_ipd,
          TestSignalName          => "A3",
          TestDelay               => 0 ns,
          RefSignal               => WCLK_ipd,
          RefSignalName           => "WCLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_A3_WCLK_posedge_posedge,
          SetupLow                => tsetup_A3_WCLK_negedge_posedge,
          HoldLow                => thold_A3_WCLK_posedge_posedge,
          HoldHigh                 => thold_A3_WCLK_negedge_posedge,
          CheckEnabled            => TO_X01(WE_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM128X1S",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A4_WCLK_posedge,
          TimingData              => Tmkr_A4_WCLK_posedge,
          TestSignal              => A4_ipd,
          TestSignalName          => "A4",
          TestDelay               => 0 ns,
          RefSignal               => WCLK_ipd,
          RefSignalName           => "WCLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_A4_WCLK_posedge_posedge,
          SetupLow                => tsetup_A4_WCLK_negedge_posedge,
          HoldLow                => thold_A4_WCLK_posedge_posedge,
          HoldHigh                 => thold_A4_WCLK_negedge_posedge,
          CheckEnabled            => TO_X01(WE_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM128X1S",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
         
         VitalSetupHoldCheck (
          Violation               => Tviol_A5_WCLK_posedge,
          TimingData              => Tmkr_A5_WCLK_posedge,
          TestSignal              => A5_ipd,
          TestSignalName          => "A5",
          TestDelay               => 0 ns,
          RefSignal               => WCLK_ipd,
          RefSignalName           => "WCLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_A5_WCLK_posedge_posedge,
          SetupLow                => tsetup_A5_WCLK_negedge_posedge,
          HoldLow                => thold_A5_WCLK_posedge_posedge,
          HoldHigh                 => thold_A5_WCLK_negedge_posedge,
          CheckEnabled            => TO_X01(WE_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM128X1S",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A6_WCLK_posedge,
          TimingData              => Tmkr_A6_WCLK_posedge,
          TestSignal              => A6_ipd,
          TestSignalName          => "A6",
          TestDelay               => 0 ns,
          RefSignal               => WCLK_ipd,
          RefSignalName           => "WCLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_A6_WCLK_posedge_posedge,
          SetupLow                => tsetup_A6_WCLK_negedge_posedge,
          HoldLow                => thold_A6_WCLK_posedge_posedge,
          HoldHigh                 => thold_A6_WCLK_negedge_posedge,
          CheckEnabled            => TO_X01(WE_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM128X1S",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalPeriodPulseCheck (
          Violation               => Pviol_WCLK,
          PeriodData              => PInfo_WCLK,
          TestSignal              => WCLK_ipd,
          TestSignalName          => "WCLK",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_WCLK_posedge,
          PulseWidthLow           => tpw_WCLK_negedge,
          CheckEnabled            => TRUE,
          HeaderMsg               => InstancePath &"/RAM128X1S",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

    end if;

    Violation := Tviol_D_WCLK_posedge  or Tviol_WE_WCLK_posedge or 
                 Tviol_A0_WCLK_posedge or Tviol_A1_WCLK_posedge or 
                 Tviol_A2_WCLK_posedge or Tviol_A3_WCLK_posedge or 
                 Tviol_A4_WCLK_posedge or Tviol_A5_WCLK_posedge or 
                 Tviol_A6_WCLK_posedge or Pviol_WCLK;

    -------------------------
    --  Functionality Section
    -------------------------
    Address := (A6_ipd, A5_ipd, A4_ipd, A3_ipd, A2_ipd, A1_ipd, A0_ipd);

    Index := SLV_TO_INT(SLV => Address );

    O_zd := MEM(Index);

    VitalStateTable(Result => O_zd,
                    PreviousDataIn => PrevData,
                    StateTable => RAMS_O_tab,
                    DataIn => (WCLK_prev, O_zd, D_prev, WE_prev, WCLK_ipd));

    O_zd := Violation XOR O_zd;

    WE_prev   := WE_ipd;
    WCLK_prev := WCLK_ipd;
    D_prev    := D_ipd;

    MEM(Index) <= O_zd;

   wait on A0_ipd, A1_ipd, A2_ipd, A3_ipd, A4_ipd, A5_ipd, A6_ipd, D_ipd, WE_ipd, WCLK_ipd;

end process VITALWriteBehavior;


end RAM128X1S_V;

configuration CFG_RAM128X1S_V of RAM128X1S is
   for RAM128X1S_V
   end for;
end CFG_RAM128X1S_V;
