library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.STD_LOGIC_UNSIGNED.all;
use IEEE.VITAL_Timing.all; 
use IEEE.VITAL_Primitives.all;

library UNISIM;
use UNISIM.VPKG.all;

entity RAM16X1D is

  generic (
       TimingChecksOn: Boolean := TRUE;
       InstancePath:   STRING  := "*";
       Xon:  Boolean := True;
       MsgOn:  Boolean := False;

       -- VITAL input wire delays

       tipd_A0    : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_A1    : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_A2    : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_A3    : VitalDelayType01 := ( 0.0 ns,  0.0 ns);

       tipd_DPRA0 : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_DPRA1 : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_DPRA2 : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_DPRA3 : VitalDelayType01 := ( 0.0 ns,  0.0 ns);

       tipd_D     : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_WE    : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_WCLK  : VitalDelayType01 := ( 0.0 ns,  0.0 ns);

       -- VITAL pin-to-pin propagation delays

       tpd_A0_SPO    : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A1_SPO    : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A2_SPO    : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A3_SPO    : VitalDelayType01 := (0.1 ns, 0.1 ns);
 
       tpd_WCLK_SPO  : VitalDelayType01 := (0.1 ns, 0.1 ns);

       tpd_DPRA0_DPO : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_DPRA1_DPO : VitalDelayType01 := (0.1 ns, 0.1 ns); 
       tpd_DPRA2_DPO : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_DPRA3_DPO : VitalDelayType01 := (0.1 ns, 0.1 ns);

       tpd_WCLK_DPO  : VitalDelayType01 := (0.1 ns, 0.1 ns); 

       -- VITAL setup and hold times

       tsetup_D_WCLK_posedge_posedge  : VitalDelayType := 0.01 ns;
       tsetup_D_WCLK_negedge_posedge  : VitalDelayType := 0.01 ns;
       tsetup_WE_WCLK_posedge_posedge : VitalDelayType := 0.01 ns;
       tsetup_WE_WCLK_negedge_posedge : VitalDelayType := 0.01 ns;
       tsetup_A0_WCLK_posedge_posedge : VitalDelayType := 0.01 ns;
       tsetup_A0_WCLK_negedge_posedge : VitalDelayType := 0.01 ns;
       tsetup_A1_WCLK_posedge_posedge : VitalDelayType := 0.01 ns;
       tsetup_A1_WCLK_negedge_posedge : VitalDelayType := 0.01 ns;
       tsetup_A2_WCLK_posedge_posedge : VitalDelayType := 0.01 ns;
       tsetup_A2_WCLK_negedge_posedge : VitalDelayType := 0.01 ns;
       tsetup_A3_WCLK_posedge_posedge : VitalDelayType := 0.01 ns;
       tsetup_A3_WCLK_negedge_posedge : VitalDelayType := 0.01 ns;

       thold_D_WCLK_posedge_posedge   : VitalDelayType := 0.01 ns;
       thold_D_WCLK_negedge_posedge   : VitalDelayType := 0.01 ns;
       thold_WE_WCLK_posedge_posedge  : VitalDelayType := 0.01 ns;
       thold_WE_WCLK_negedge_posedge  : VitalDelayType := 0.01 ns;
       thold_A0_WCLK_posedge_posedge  : VitalDelayType := 0.01 ns;
       thold_A0_WCLK_negedge_posedge  : VitalDelayType := 0.01 ns;
       thold_A1_WCLK_posedge_posedge  : VitalDelayType := 0.01 ns;
       thold_A1_WCLK_negedge_posedge  : VitalDelayType := 0.01 ns;
       thold_A2_WCLK_posedge_posedge  : VitalDelayType := 0.01 ns;
       thold_A2_WCLK_negedge_posedge  : VitalDelayType := 0.01 ns;
       thold_A3_WCLK_posedge_posedge  : VitalDelayType := 0.01 ns;
       thold_A3_WCLK_negedge_posedge  : VitalDelayType := 0.01 ns;

       -- VITAL minimum pulse width

       tpw_WCLK_posedge : VitalDelayType := 0.01 ns;
       tpw_WCLK_negedge : VitalDelayType := 0.01 ns;

       INIT : bit_vector(15 downto 0) := X"0000"
  );

  port (D     : in std_ulogic;
        WE    : in std_ulogic;
        WCLK  : in std_ulogic;
        A0    : in std_ulogic;
        A1    : in std_ulogic;
        A2    : in std_ulogic;
        A3    : in std_ulogic;
        DPRA0 : in std_ulogic;
        DPRA1 : in std_ulogic;
        DPRA2 : in std_ulogic;
        DPRA3 : in std_ulogic;

        SPO   : out std_ulogic;
        DPO   : out std_ulogic
       ); 
attribute VITAL_LEVEL0 of RAM16X1D : entity is TRUE;

end RAM16X1D;

-----------------------------------------------------------------------------

architecture RAM16X1D_V of RAM16X1D is

  attribute VITAL_LEVEL0 of RAM16X1D_V : architecture is TRUE;

  -- Local signals used to propagate input wire delay

  signal A0_ipd    : std_ulogic := 'X';
  signal A1_ipd    : std_ulogic := 'X';
  signal A2_ipd    : std_ulogic := 'X';
  signal A3_ipd    : std_ulogic := 'X';

  signal DPRA0_ipd : std_ulogic := 'X';
  signal DPRA1_ipd : std_ulogic := 'X';
  signal DPRA2_ipd : std_ulogic := 'X';
  signal DPRA3_ipd : std_ulogic := 'X';

  signal D_ipd     : std_ulogic := 'X';
  signal WE_ipd    : std_ulogic := 'X';
  signal WCLK_ipd  : std_ulogic := 'X';
  signal MEM       : std_logic_vector( 16 downto 0 ) := ('X' & To_StdLogicVector(INIT) );

begin -- architecture

  ----------------------
  --  Wire Delay Section
  ----------------------
  WireDelay : block
  begin
    VitalWireDelay (A0_ipd,    A0,    tipd_A0);
    VitalWireDelay (A1_ipd,    A1,    tipd_A1);
    VitalWireDelay (A2_ipd,    A2,    tipd_A2);
    VitalWireDelay (A3_ipd,    A3,    tipd_A3);

    VitalWireDelay (DPRA0_ipd, DPRA0, tipd_DPRA0);
    VitalWireDelay (DPRA1_ipd, DPRA1, tipd_DPRA1);
    VitalWireDelay (DPRA2_ipd, DPRA2, tipd_DPRA2);
    VitalWireDelay (DPRA3_ipd, DPRA3, tipd_DPRA3);

    VitalWireDelay (D_ipd,     D,     tipd_D);
    VitalWireDelay (WE_ipd,    WE,    tipd_WE);
    VitalWireDelay (WCLK_ipd,  WCLK,  tipd_WCLK);
  end block;

  --------------------
  -- RAM16X1D Behavior
  --------------------
 VITALReadBehavior : process(A0_ipd, A1_ipd, A2_ipd, A3_ipd, 
     DPRA3_ipd, DPRA2_ipd, DPRA1_ipd, DPRA0_ipd, WCLK_ipd, MEM)
       Variable Index_SP   : integer  := 16 ;
       Variable Index_DP   : integer  := 16 ;
       variable SPO_zd    : std_ulogic := 'X';
    variable DPO_zd    : std_ulogic := 'X';
    variable SPO_GlitchData : VitalGlitchDataType;
    variable DPO_GlitchData : VitalGlitchDataType;

  begin -- process
    Index_SP := DECODE_ADDR4(ADDRESS => (A3_ipd, A2_ipd, A1_ipd,
      A0_ipd));
    Index_DP := DECODE_ADDR4(ADDRESS => (DPRA3_ipd, DPRA2_ipd, DPRA1_ipd,
        DPRA0_ipd));

    SPO_zd := MEM(Index_SP);
    DPO_zd := MEM(Index_DP);

 ----------------------
    --  Path Delay Section
    ----------------------
     VitalPathDelay01 (
      OutSignal => SPO,
      GlitchData => SPO_GlitchData,
      OutSignalName => "SPO",
      OutTemp => SPO_zd,
      Paths => (0 => (WCLK_ipd'last_event, tpd_WCLK_SPO, TRUE),
                1 => (A0_ipd'last_event, tpd_A0_SPO, TRUE),
                2 => (A1_ipd'last_event, tpd_A1_SPO, TRUE),
                3 => (A2_ipd'last_event, tpd_A2_SPO, TRUE),
                4 => (A3_ipd'last_event, tpd_A3_SPO, TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

      VitalPathDelay01 (
      OutSignal => DPO,
      GlitchData => DPO_GlitchData,
      OutSignalName => "DPO",
      OutTemp => DPO_zd,
      Paths => (0 => (WCLK_ipd'last_event, tpd_WCLK_DPO, TRUE),
                1 => (DPRA0_ipd'last_event, tpd_DPRA0_DPO, TRUE),
                2 => (DPRA1_ipd'last_event, tpd_DPRA1_DPO, TRUE),
                3 => (DPRA2_ipd'last_event, tpd_DPRA2_DPO, TRUE),
                4 => (DPRA3_ipd'last_event, tpd_DPRA3_DPO, TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);
  end process VITALReadBehavior;

 VITALWriteBehavior : process

    -- Local variables used for functionality
    variable Index_SP  : integer := 16;
    variable Index_DP  : integer := 16;
    variable PrevData  : std_logic_vector(0 to 4) := (others => '0');
    variable WE_prev   : std_ulogic := 'X';
    variable WCLK_prev : std_ulogic := 'X';
    variable D_prev    : std_ulogic := 'X';
    variable FIRST_TIME : boolean := TRUE;

    -- Local variables used for timing checks
    variable Tviol_D_WCLK_posedge  : std_ulogic := '0';
    variable Tviol_WE_WCLK_posedge : std_ulogic := '0';
    variable Tviol_A0_WCLK_posedge : std_ulogic := '0';
    variable Tviol_A1_WCLK_posedge : std_ulogic := '0';
    variable Tviol_A2_WCLK_posedge : std_ulogic := '0';
    variable Tviol_A3_WCLK_posedge : std_ulogic := '0';

    variable Tmkr_D_WCLK_posedge   : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_WE_WCLK_posedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A0_WCLK_posedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A1_WCLK_posedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A2_WCLK_posedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A3_WCLK_posedge  : VitalTimingDataType := VitalTimingDataInit;

    variable PViol_WCLK : std_ulogic := '0';
    variable PInfo_WCLK : VitalPeriodDataType := VitalPeriodDataInit;

    -- Local variables used for functionality
    variable SPO_zd    : std_ulogic := 'X';
    variable DPO_zd    : std_ulogic := 'X';
    variable Violation : std_ulogic := '0';

  begin -- process

    if (FIRST_TIME) then
        wait until ( (WCLK_ipd = '0' or WCLK_ipd = '1') and
                    (WE_ipd = '0' or WE_ipd = '1') and
                    (A3_ipd = '0' or A3_ipd = '1') and
                    (A2_ipd = '0' or A2_ipd = '1') and
                    (A1_ipd = '0' or A1_ipd = '1') and
                    (A0_ipd = '0' or A0_ipd = '1') );
        WCLK_prev := WCLK_ipd;
        WE_prev  := WE_ipd;
        D_prev   := D_ipd;
        Index_SP := DECODE_ADDR4(ADDRESS => (A3_ipd, A2_ipd, A1_ipd, A0_ipd));
        SPO_zd   := MEM(Index_SP);
        FIRST_TIME := FALSE;

    end if;
    ------------------------
    --  Timing Check Section
    ------------------------
    if (TimingChecksOn ) then

         VitalSetupHoldCheck (
          Violation               => Tviol_D_WCLK_posedge,
          TimingData              => Tmkr_D_WCLK_posedge,
          TestSignal              => D_ipd,
          TestSignalName          => "D",
          TestDelay               => 0 ns,
          RefSignal               => WCLK_ipd,
          RefSignalName           => "WCLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_D_WCLK_posedge_posedge,
          SetupLow                => tsetup_D_WCLK_negedge_posedge,
          HoldLow                => thold_D_WCLK_posedge_posedge,
          HoldHigh                 => thold_D_WCLK_negedge_posedge,
          CheckEnabled            => TO_X01(WE_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM16X1D",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_WE_WCLK_posedge,
          TimingData              => Tmkr_WE_WCLK_posedge,
          TestSignal              => WE_ipd,
          TestSignalName          => "WE",
          TestDelay               => 0 ns,
          RefSignal               => WCLK_ipd,
          RefSignalName           => "WCLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_WE_WCLK_posedge_posedge,
          SetupLow                => tsetup_WE_WCLK_negedge_posedge,
          HoldLow                => thold_WE_WCLK_posedge_posedge,
          HoldHigh                 => thold_WE_WCLK_negedge_posedge,
          CheckEnabled            => TRUE,
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM16X1D",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A0_WCLK_posedge,
          TimingData              => Tmkr_A0_WCLK_posedge,
          TestSignal              => A0_ipd,
          TestSignalName          => "A0",
          TestDelay               => 0 ns,
          RefSignal               => WCLK_ipd,
          RefSignalName           => "WCLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_A0_WCLK_posedge_posedge,
          SetupLow                => tsetup_A0_WCLK_negedge_posedge,
          HoldLow                => thold_A0_WCLK_posedge_posedge,
          HoldHigh                 => thold_A0_WCLK_negedge_posedge,
          CheckEnabled            => TO_X01(WE_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM16X1D",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A1_WCLK_posedge,
          TimingData              => Tmkr_A1_WCLK_posedge,
          TestSignal              => A1_ipd,
          TestSignalName          => "A1",
          TestDelay               => 0 ns,
          RefSignal               => WCLK_ipd,
          RefSignalName           => "WCLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_A1_WCLK_posedge_posedge,
          SetupLow                => tsetup_A1_WCLK_negedge_posedge,
          HoldLow                => thold_A1_WCLK_posedge_posedge,
          HoldHigh                 => thold_A1_WCLK_negedge_posedge,
          CheckEnabled            => TO_X01(WE_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM16X1D",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A2_WCLK_posedge,
          TimingData              => Tmkr_A2_WCLK_posedge,
          TestSignal              => A2_ipd,
          TestSignalName          => "A2",
          TestDelay               => 0 ns,
          RefSignal               => WCLK_ipd,
          RefSignalName           => "WCLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_A2_WCLK_posedge_posedge,
          SetupLow                => tsetup_A2_WCLK_negedge_posedge,
          HoldLow                => thold_A2_WCLK_posedge_posedge,
          HoldHigh                 => thold_A2_WCLK_negedge_posedge,
          CheckEnabled            => TO_X01(WE_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM16X1D",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A3_WCLK_posedge,
          TimingData              => Tmkr_A3_WCLK_posedge,
          TestSignal              => A3_ipd,
          TestSignalName          => "A3",
          TestDelay               => 0 ns,
          RefSignal               => WCLK_ipd,
          RefSignalName           => "WCLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_A3_WCLK_posedge_posedge,
          SetupLow                => tsetup_A3_WCLK_negedge_posedge,
          HoldLow                => thold_A3_WCLK_posedge_posedge,
          HoldHigh                 => thold_A3_WCLK_negedge_posedge,
          CheckEnabled            => TO_X01(WE_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM16X1D",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalPeriodPulseCheck (
          Violation               => Pviol_WCLK,
          PeriodData              => PInfo_WCLK,
          TestSignal              => WCLK_ipd,
          TestSignalName          => "WCLK",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_WCLK_posedge,
          PulseWidthLow           => tpw_WCLK_negedge,
          CheckEnabled            => TRUE,
          HeaderMsg               => InstancePath &"/RAM16X1D",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

    end if;

    Violation := Tviol_D_WCLK_posedge  or Tviol_WE_WCLK_posedge or 
                 Tviol_A0_WCLK_posedge or Tviol_A1_WCLK_posedge or 
                 Tviol_A2_WCLK_posedge or Tviol_A3_WCLK_posedge or 
                 Pviol_WCLK;

    -------------------------
    --  Functionality Section
    -------------------------
    Index_SP := DECODE_ADDR4(ADDRESS => (A3_ipd, A2_ipd, A1_ipd, A0_ipd));

    SPO_zd := MEM(Index_SP);

    VitalStateTable(Result => SPO_zd,
                    PreviousDataIn => PrevData,
                    StateTable => RAMS_O_tab,
                    DataIn => (WCLK_prev, SPO_zd, D_prev, WE_prev, WCLK_ipd));

    SPO_zd := Violation XOR SPO_zd;

    WE_prev   := WE_ipd;
    WCLK_prev := WCLK_ipd;
    D_prev    := D_ipd;

    MEM(Index_SP) <= SPO_zd;

    wait on A0_ipd, A1_ipd, A2_ipd, A3_ipd, D_ipd, WCLK_ipd, WE_ipd;

  end process VITALWriteBehavior;

end RAM16X1D_V;
 
