architecture RAM16X1S_1_V of RAM16X1S_1 is

  attribute VITAL_LEVEL0 of RAM16X1S_1_V : architecture is TRUE;

  -- Local signals used to propagate input wire delay

  signal A0_ipd   : std_ulogic := 'X';
