use IEEE.STD_LOGIC_UNSIGNED.all;
use IEEE.VITAL_Timing.all;
use IEEE.VITAL_Primitives.all;

library UNISIM;
use UNISIM.VPKG.all;

entity RAM32X1 is

  generic (
       TimingChecksOn: Boolean := TRUE;
       InstancePath:   STRING  := "*";
       Xon:  Boolean := True;
       MsgOn:  Boolean := False;

       -- VITAL input wire delays

       tipd_D    : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_WE   : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_A0   : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_A1   : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_A2   : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_A3   : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_A4   : VitalDelayType01 := ( 0.0 ns,  0.0 ns);

       -- VITAL pin-to-pin propagation delays

       tpd_D_O   : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_WE_O  : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A0_O  : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A1_O  : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A2_O  : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A3_O  : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A4_O  : VitalDelayType01 := (0.1 ns, 0.1 ns);

       -- VITAL setup and hold times

       tsetup_D_WE_posedge_negedge  : VitalDelayType := 0.01 ns;
       tsetup_D_WE_negedge_negedge  : VitalDelayType := 0.01 ns;
       tsetup_A0_WE_posedge_posedge : VitalDelayType := 0.01 ns;
       tsetup_A0_WE_negedge_posedge : VitalDelayType := 0.01 ns;
       tsetup_A1_WE_posedge_posedge : VitalDelayType := 0.01 ns;
       tsetup_A1_WE_negedge_posedge : VitalDelayType := 0.01 ns;
       tsetup_A2_WE_posedge_posedge : VitalDelayType := 0.01 ns;
       tsetup_A2_WE_negedge_posedge : VitalDelayType := 0.01 ns;
       tsetup_A3_WE_posedge_posedge : VitalDelayType := 0.01 ns;
       tsetup_A3_WE_negedge_posedge : VitalDelayType := 0.01 ns;
       tsetup_A4_WE_posedge_posedge : VitalDelayType := 0.01 ns;
       tsetup_A4_WE_negedge_posedge : VitalDelayType := 0.01 ns;

       thold_D_WE_posedge_negedge   : VitalDelayType := 0.01 ns;
       thold_D_WE_negedge_negedge   : VitalDelayType := 0.01 ns;
       thold_A0_WE_posedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A0_WE_negedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A1_WE_posedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A1_WE_negedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A2_WE_posedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A2_WE_negedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A3_WE_posedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A3_WE_negedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A4_WE_posedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A4_WE_negedge_negedge  : VitalDelayType := 0.01 ns;
 
       -- VITAL minimum pulse width
 
       tpw_WE_posedge : VitalDelayType := 0.01 ns;
 
       INIT : bit_vector(31 downto 0) := X"00000000"
  );

  port ( D : in STD_ULOGIC;
        WE : in STD_ULOGIC;
        A0 : in STD_ULOGIC;
        A1 : in STD_ULOGIC;
        A2 : in STD_ULOGIC;
        A3 : in STD_ULOGIC;
        A4 : in STD_ULOGIC;

        O  : out STD_ULOGIC
       ); 
attribute VITAL_LEVEL0 of RAM32X1 : entity is TRUE;

end RAM32X1;

-----------------------------------------------------------------------------

architecture RAM32X1_V of RAM32X1 is

  attribute VITAL_LEVEL0 of RAM32X1_V : architecture is TRUE;

  -- Local signals used to propagate input wire delay
 
  signal D_ipd    : std_ulogic := 'X';
  signal WE_ipd   : std_ulogic := 'X';
  signal A0_ipd   : std_ulogic := 'X';
  signal A1_ipd   : std_ulogic := 'X';
  signal A2_ipd   : std_ulogic := 'X';
  signal A3_ipd   : std_ulogic := 'X';
  signal A4_ipd   : std_ulogic := 'X';

  signal MEM        : std_logic_vector( 32 downto 0 ) := ('X' & To_StdLogicVector(INIT) );
 
 
begin -- architecture

  ----------------------
  --  Wire Delay Section
  ----------------------
  WireDelay : block
  begin
    VitalWireDelay (D_ipd,    D,    tipd_D);
    VitalWireDelay (WE_ipd,   WE,   tipd_WE);
    VitalWireDelay (A0_ipd,   A0,   tipd_A0);
    VitalWireDelay (A1_ipd,   A1,   tipd_A1);
    VitalWireDelay (A2_ipd,   A2,   tipd_A2);
    VitalWireDelay (A3_ipd,   A3,   tipd_A3);
    VitalWireDelay (A4_ipd,   A4,   tipd_A4);
  end block;

  -------------------
  -- RAM32X1 behavior
  -------------------
VITALReadBehavior : process(A0_ipd, A1_ipd, A2_ipd, A3_ipd, A4_ipd, WE_ipd, D_ipd, MEM)
         Variable Index      : integer  := 16 ;
         variable O_zd      : std_ulogic := 'X';
         variable O_GlitchData : VitalGlitchDataType;

  begin -- process
        Index      := DECODE_ADDR5(ADDRESS => (A4_ipd, A3_ipd, A2_ipd, A1_ipd, A0_ipd));
        O_zd       := MEM(Index) ;

    ----------------------
    --  Path Delay Section
    ----------------------
    VitalPathDelay01 (
      OutSignal => O,
      GlitchData => O_GlitchData,
      OutSignalName => "O",
      OutTemp => O_zd,
      Paths => (0 => (WE_ipd'last_event, tpd_WE_O, TRUE),
                1 => (D_ipd'last_event,  tpd_D_O,  TRUE),
                2 => (A0_ipd'last_event, tpd_A0_O, TRUE),
                3 => (A1_ipd'last_event, tpd_A1_O, TRUE),
                4 => (A2_ipd'last_event, tpd_A2_O, TRUE),
                5 => (A3_ipd'last_event, tpd_A3_O, TRUE),
                6 => (A4_ipd'last_event, tpd_A4_O, TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

  end process VITALReadBehavior;

  VITALWriteBehavior : process

    -- Local variables used for functionality
    variable PrevData  : std_logic_vector(0 to 1) := (others => '0');
    variable O_zd      : std_ulogic := 'X';
    variable FIRST_TIME : boolean := TRUE;
    Variable Index      : integer  := 32 ;
    variable Violation : std_ulogic := '0';

    -- Local variables used for timing checks
    variable Tviol_D_WE_negedge  : std_ulogic := '0';
    variable Tviol_A0_WE_posedge : std_ulogic := '0';
    variable Tviol_A0_WE_negedge : std_ulogic := '0';
    variable Tviol_A1_WE_posedge : std_ulogic := '0';
    variable Tviol_A1_WE_negedge : std_ulogic := '0';
    variable Tviol_A2_WE_posedge : std_ulogic := '0';
    variable Tviol_A2_WE_negedge : std_ulogic := '0';
    variable Tviol_A3_WE_posedge : std_ulogic := '0';
    variable Tviol_A3_WE_negedge : std_ulogic := '0';
    variable Tviol_A4_WE_posedge : std_ulogic := '0';
    variable Tviol_A4_WE_negedge : std_ulogic := '0';

    variable Tmkr_D_WE_negedge   : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A0_WE_posedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A0_WE_negedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A1_WE_posedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A1_WE_negedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A2_WE_posedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A2_WE_negedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A3_WE_posedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A3_WE_negedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A4_WE_posedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A4_WE_negedge  : VitalTimingDataType := VitalTimingDataInit;
 
    variable PViol_WE : std_ulogic := '0';
    variable PInfo_WE : VitalPeriodDataType := VitalPeriodDataInit;
 
  begin -- process
 
    if (FIRST_TIME) then
        wait until ((WE_ipd = '0' or WE_ipd = '1') and
                    (D_ipd = '0' or D_ipd = '1') and
                    (A4_ipd = '0' or A4_ipd = '1') and
                    (A3_ipd = '0' or A3_ipd = '1') and
                    (A2_ipd = '0' or A2_ipd = '1') and
                    (A1_ipd = '0' or A1_ipd = '1') and
                    (A0_ipd = '0' or A0_ipd = '1'));
        Index      := DECODE_ADDR5(ADDRESS => (A4_ipd, A3_ipd, A2_ipd, A1_ipd, A0_ipd));
        O_zd       := MEM(Index);
        FIRST_TIME := FALSE;
    end if;
    ------------------------
    --  Timing Check Section
    ------------------------
    if (TimingChecksOn ) then
 
         VitalSetupHoldCheck (
          Violation               => Tviol_D_WE_negedge,
          TimingData              => Tmkr_D_WE_negedge,
          TestSignal              => D_ipd,
          TestSignalName          => "D",
          TestDelay               => 0 ns,
          RefSignal               => WE_ipd,
          RefSignalName           => "WE",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_D_WE_posedge_negedge,
          SetupLow                => tsetup_D_WE_negedge_negedge,
          HoldHigh                => thold_D_WE_posedge_negedge,
          HoldLow                 => thold_D_WE_negedge_negedge,
          CheckEnabled            => TRUE,
          RefTransition           => 'F',
          HeaderMsg               => InstancePath & "/RAM32X1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A0_WE_posedge,
          TimingData              => Tmkr_A0_WE_posedge,
          TestSignal              => A0_ipd,
          TestSignalName          => "A0",
          TestDelay               => 0 ns,
          RefSignal               => WE_ipd,
          RefSignalName           => "WE",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_A0_WE_posedge_posedge,
          SetupLow                => tsetup_A0_WE_negedge_posedge,
          HoldHigh                => 0 ns,
          HoldLow                 => 0 ns,
          CheckEnabled            => TRUE,
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM32X1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A0_WE_negedge,
          TimingData              => Tmkr_A0_WE_negedge,
          TestSignal              => A0_ipd,
          TestSignalName          => "A0",
          TestDelay               => 0 ns,
          RefSignal               => WE_ipd,
          RefSignalName           => "WE",
          RefDelay                => 0 ns,
          SetupHigh               => 0 ns,
          SetupLow                => 0 ns,
          HoldHigh                => thold_A0_WE_posedge_negedge,
          HoldLow                 => thold_A0_WE_negedge_negedge,
          CheckEnabled            => TRUE,
          RefTransition           => 'F',
          HeaderMsg               => InstancePath & "/RAM32X1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
