          TestSignal              => A1_ipd,
          TestSignalName          => "A1",
          TestDelay               => 0 ns,
          RefSignal               => WE_ipd,
          RefSignalName           => "WE",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_A1_WE_posedge_posedge,
          SetupLow                => tsetup_A1_WE_negedge_posedge,
          HoldHigh                => 0 ns,
          HoldLow                 => 0 ns,
          CheckEnabled            => TRUE,
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM32X1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A1_WE_negedge,
          TimingData              => Tmkr_A1_WE_negedge,
          TestSignal              => A1_ipd,
          TestSignalName          => "A1",
          TestDelay               => 0 ns,
          RefSignal               => WE_ipd,
          RefSignalName           => "WE",
          RefDelay                => 0 ns,
          SetupHigh               => 0 ns,
          SetupLow                => 0 ns,
          HoldHigh                => thold_A1_WE_posedge_negedge,
          HoldLow                 => thold_A1_WE_negedge_negedge,
          CheckEnabled            => TRUE,
          RefTransition           => 'F',
          HeaderMsg               => InstancePath & "/RAM32X1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A2_WE_posedge,
          TimingData              => Tmkr_A2_WE_posedge,
          TestSignal              => A2_ipd,
          TestSignalName          => "A2",
          TestDelay               => 0 ns,
          RefSignal               => WE_ipd,
          RefSignalName           => "WE",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_A2_WE_posedge_posedge,
          SetupLow                => tsetup_A2_WE_negedge_posedge,
          HoldHigh                => 0 ns,
          HoldLow                 => 0 ns,
          CheckEnabled            => TRUE,
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM32X1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A2_WE_negedge,
          TimingData              => Tmkr_A2_WE_negedge,
          TestSignal              => A2_ipd,
          TestSignalName          => "A2",
          TestDelay               => 0 ns,
          RefSignal               => WE_ipd,
          RefSignalName           => "WE",
          RefDelay                => 0 ns,
          SetupHigh               => 0 ns,
          SetupLow                => 0 ns,
          HoldHigh                => thold_A2_WE_posedge_negedge,
          HoldLow                 => thold_A2_WE_negedge_negedge,
          CheckEnabled            => TRUE,
          RefTransition           => 'F',
          HeaderMsg               => InstancePath & "/RAM32X1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A3_WE_posedge,
          TimingData              => Tmkr_A3_WE_posedge,
          TestSignal              => A3_ipd,
          TestSignalName          => "A3",
          TestDelay               => 0 ns,
          RefSignal               => WE_ipd,
          RefSignalName           => "WE",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_A3_WE_posedge_posedge,
          SetupLow                => tsetup_A3_WE_negedge_posedge,
          HoldHigh                => 0 ns,
          HoldLow                 => 0 ns,
          CheckEnabled            => TRUE,
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM32X1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A3_WE_negedge,
          TimingData              => Tmkr_A3_WE_negedge,
          TestSignal              => A3_ipd,
          TestSignalName          => "A3",
          TestDelay               => 0 ns,
          RefSignal               => WE_ipd,
          RefSignalName           => "WE",
          RefDelay                => 0 ns,
          SetupHigh               => 0 ns,
          SetupLow                => 0 ns,
          HoldHigh                => thold_A3_WE_posedge_negedge,
          HoldLow                 => thold_A3_WE_negedge_negedge,
          CheckEnabled            => TRUE,
          RefTransition           => 'F',
          HeaderMsg               => InstancePath & "/RAM32X1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A4_WE_posedge,
          TimingData              => Tmkr_A4_WE_posedge,
          TestSignal              => A4_ipd,
          TestSignalName          => "A4",
          TestDelay               => 0 ns,
          RefSignal               => WE_ipd,
          RefSignalName           => "WE",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_A4_WE_posedge_posedge,
          SetupLow                => tsetup_A4_WE_negedge_posedge,
          HoldHigh                => 0 ns,
          HoldLow                 => 0 ns,
          CheckEnabled            => TRUE,
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAM32X1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A4_WE_negedge,
          TimingData              => Tmkr_A4_WE_negedge,
          TestSignal              => A4_ipd,
          TestSignalName          => "A4",
          TestDelay               => 0 ns,
          RefSignal               => WE_ipd,
          RefSignalName           => "WE",
          RefDelay                => 0 ns,
          SetupHigh               => 0 ns,
          SetupLow                => 0 ns,
          HoldHigh                => thold_A4_WE_posedge_negedge,
          HoldLow                 => thold_A4_WE_negedge_negedge,
          CheckEnabled            => TRUE,
          RefTransition           => 'F',
          HeaderMsg               => InstancePath & "/RAM32X1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalPeriodPulseCheck (
          Violation               => Pviol_WE,
          PeriodData              => PInfo_WE,
          TestSignal              => WE_ipd,
          TestSignalName          => "WE",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_WE_posedge,
          PulseWidthLow           => 0 ns,
          CheckEnabled            => TRUE,
          HeaderMsg               => InstancePath &"/RAM32X1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

    end if;

    Violation := Tviol_A0_WE_posedge or Tviol_A0_WE_negedge or
                 Tviol_A1_WE_posedge or Tviol_A1_WE_negedge or
                 Tviol_A2_WE_posedge or Tviol_A2_WE_negedge or
                 Tviol_A3_WE_posedge or Tviol_A3_WE_negedge or
                 Tviol_A4_WE_posedge or Tviol_A4_WE_negedge or
                 Tviol_D_WE_negedge  or Pviol_WE;

    if(WE_ipd = '1' and 
       (A0_ipd'event or A1_ipd'event or A2_ipd'event or A3_ipd'event or A4_ipd'event)) then
          assert false 
          report "Address changed during high WE"
          severity warning; 
          Violation := 'X'; 
    end if;
    -------------------------
    --  Functionality Section
    -------------------------

    Index := DECODE_ADDR5(ADDRESS => (A4_ipd, A3_ipd, A2_ipd, A1_ipd, A0_ipd));

    O_zd := MEM(Index);

    VitalStateTable(Result => O_zd,
                    PreviousDataIn => PrevData,
                    StateTable => RAM_O_tab,
                    DataIn => (D_ipd, WE_ipd));

    O_zd := Violation XOR O_zd;

    MEM(Index) <= O_zd;

    wait on A0_ipd, A1_ipd, A2_ipd, A3_ipd, A4_ipd, D_ipd, WE_ipd;

  end process VITALWriteBehavior;
 
end RAM32X1_V;

configuration CFG_RAM32X1_V of RAM32X1 is
   for RAM32X1_V
   end for;
end CFG_RAM32X1_V;
