entity RAM64X1S_1 is

  generic (
       TimingChecksOn: Boolean := TRUE;
       InstancePath:   STRING  := "*";
       Xon:  Boolean := True;
       MsgOn:  Boolean := False;

       -- VITAL input wire delays

       tipd_A0     : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_A1     : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_A2     : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_A3     : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_A4     : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_A5     : VitalDelayType01 := ( 0.0 ns,  0.0 ns);

       tipd_D      : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_WE     : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_WCLK   : VitalDelayType01 := ( 0.0 ns,  0.0 ns);

       -- VITAL pin-to-pin propagation delays

       tpd_A0_O    : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A1_O    : VitalDelayType01 := (0.1 ns, 0.1 ns); 
       tpd_A2_O    : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A3_O    : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A4_O    : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A5_O    : VitalDelayType01 := (0.1 ns, 0.1 ns);

       tpd_WCLK_O  : VitalDelayType01 := (0.1 ns, 0.1 ns); 

       -- VITAL setup and hold times

       tsetup_D_WCLK_posedge_negedge  : VitalDelayType := 0.01 ns;
       tsetup_D_WCLK_negedge_negedge  : VitalDelayType := 0.01 ns;
       tsetup_WE_WCLK_posedge_negedge : VitalDelayType := 0.01 ns;
       tsetup_WE_WCLK_negedge_negedge : VitalDelayType := 0.01 ns;
       tsetup_A0_WCLK_posedge_negedge : VitalDelayType := 0.01 ns;
       tsetup_A0_WCLK_negedge_negedge : VitalDelayType := 0.01 ns;
       tsetup_A1_WCLK_posedge_negedge : VitalDelayType := 0.01 ns;
       tsetup_A1_WCLK_negedge_negedge : VitalDelayType := 0.01 ns;
       tsetup_A2_WCLK_posedge_negedge : VitalDelayType := 0.01 ns;
       tsetup_A2_WCLK_negedge_negedge : VitalDelayType := 0.01 ns;
       tsetup_A3_WCLK_posedge_negedge : VitalDelayType := 0.01 ns;
       tsetup_A3_WCLK_negedge_negedge : VitalDelayType := 0.01 ns;
       tsetup_A4_WCLK_posedge_negedge : VitalDelayType := 0.01 ns;
       tsetup_A4_WCLK_negedge_negedge : VitalDelayType := 0.01 ns;
       tsetup_A5_WCLK_posedge_negedge : VitalDelayType := 0.01 ns;
       tsetup_A5_WCLK_negedge_negedge : VitalDelayType := 0.01 ns;

       thold_D_WCLK_posedge_negedge   : VitalDelayType := 0.01 ns;
       thold_D_WCLK_negedge_negedge   : VitalDelayType := 0.01 ns;
       thold_WE_WCLK_posedge_negedge  : VitalDelayType := 0.01 ns;
       thold_WE_WCLK_negedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A0_WCLK_posedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A0_WCLK_negedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A1_WCLK_posedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A1_WCLK_negedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A2_WCLK_posedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A2_WCLK_negedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A3_WCLK_posedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A3_WCLK_negedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A4_WCLK_posedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A4_WCLK_negedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A5_WCLK_posedge_negedge  : VitalDelayType := 0.01 ns;
       thold_A5_WCLK_negedge_negedge  : VitalDelayType := 0.01 ns;

       -- VITAL minimum pulse width

       tpw_WCLK_posedge : VitalDelayType := 0.01 ns;
       tpw_WCLK_negedge : VitalDelayType := 0.01 ns;

       INIT : bit_vector(63 downto 0) := X"0000000000000000"
  );

  port (D    : in std_ulogic;
        WE   : in std_ulogic;
        WCLK : in std_ulogic;
        A0   : in std_ulogic;
        A1   : in std_ulogic;
        A2   : in std_ulogic;
        A3   : in std_ulogic;
        A4   : in std_ulogic;
        A5   : in std_ulogic;

        O    : out std_ulogic
       ); 
attribute VITAL_LEVEL0 of RAM64X1S_1 : entity is TRUE;

end RAM64X1S_1;

architecture RAM64X1S_1_V of RAM64X1S_1 is

  attribute VITAL_LEVEL0 of RAM64X1S_1_V : architecture is TRUE;

  -- Local signals used to propagate input wire delay

  signal A0_ipd   : std_ulogic := 'X';
  signal A1_ipd   : std_ulogic := 'X';
  signal A2_ipd   : std_ulogic := 'X';
  signal A3_ipd   : std_ulogic := 'X';
  signal A4_ipd   : std_ulogic := 'X';
  signal A5_ipd   : std_ulogic := 'X';

  signal D_ipd    : std_ulogic := 'X';
  signal WE_ipd   : std_ulogic := 'X';
  signal WCLK_ipd : std_ulogic := 'X';

  signal MEM        : std_logic_vector( 64 downto 0 ) := ('X' & To_StdLogicVector(INIT) );

begin -- architecture

  ----------------------
  --  Wire Delay Section
  ----------------------
  WireDelay : block
  begin
    VitalWireDelay (A0_ipd,   A0,   tipd_A0);
    VitalWireDelay (A1_ipd,   A1,   tipd_A1);
    VitalWireDelay (A2_ipd,   A2,   tipd_A2);
    VitalWireDelay (A3_ipd,   A3,   tipd_A3);
    VitalWireDelay (A4_ipd,   A4,   tipd_A4);
    VitalWireDelay (A5_ipd,   A5,   tipd_A5);

    VitalWireDelay (D_ipd,    D,    tipd_D);
    VitalWireDelay (WE_ipd,   WE,   tipd_WE);
    VitalWireDelay (WCLK_ipd, WCLK, tipd_WCLK);
  end block;

  --------------------
  -- RAM64X1S_1 Behavior
  --------------------
  VITALReadBehavior : process(A0_ipd, A1_ipd, A2_ipd, A3_ipd, A4_ipd, A5_ipd, WCLK_ipd, MEM)
         Variable Index      : integer  := 16 ;
         variable O_zd      : std_ulogic := 'X';
         variable O_GlitchData : VitalGlitchDataType;
         variable Address : std_logic_vector ( 5 downto 0);

  begin -- process
        Address    := (A5_ipd, A4_ipd, A3_ipd, A2_ipd, A1_ipd, A0_ipd);
        Index      := SLV_TO_INT(SLV => Address);
        O_zd       := MEM(Index);

    ----------------------
    --  Path Delay Section
    ----------------------
    VitalPathDelay01 (
      OutSignal => O,
      GlitchData => O_GlitchData,
      OutSignalName => "O",
      OutTemp => O_zd,
      Paths => (0 => (WCLK_ipd'last_event,  tpd_WCLK_O,  TRUE),
                1 => (A0_ipd'last_event, tpd_A0_O, TRUE),
                2 => (A1_ipd'last_event, tpd_A1_O, TRUE),
                3 => (A2_ipd'last_event, tpd_A2_O, TRUE),
                4 => (A3_ipd'last_event, tpd_A3_O, TRUE),
                5 => (A4_ipd'last_event, tpd_A4_O, TRUE),
                6 => (A5_ipd'last_event, tpd_A5_O, TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);
  end process VITALReadBehavior;

  VITALWriteBehavior : process

    -- Local variables used for functionality
    variable Violation : std_ulogic := '0';
    variable PrevData  : std_logic_vector(0 to 4) := (others => '0');
    variable WCLK_prev  : std_ulogic := 'X';
    variable WE_prev  : std_ulogic := 'X';
    variable D_prev  : std_ulogic := 'X';
    variable O_zd      : std_ulogic := 'X';
    variable FIRST_TIME : boolean := TRUE;
    Variable Index      : integer  := 64 ;
    Variable Address    : std_logic_vector (5 downto 0);

    -- Local variables used for timing checks
    variable Tviol_D_WCLK_negedge  : std_ulogic := '0';
    variable Tviol_WE_WCLK_negedge : std_ulogic := '0';
    variable Tviol_A0_WCLK_negedge : std_ulogic := '0';
    variable Tviol_A1_WCLK_negedge : std_ulogic := '0';
    variable Tviol_A2_WCLK_negedge : std_ulogic := '0';
    variable Tviol_A3_WCLK_negedge : std_ulogic := '0';
    variable Tviol_A4_WCLK_negedge : std_ulogic := '0';
    variable Tviol_A5_WCLK_negedge : std_ulogic := '0';

    variable Tmkr_D_WCLK_negedge   : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_WE_WCLK_negedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A0_WCLK_negedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A1_WCLK_negedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A2_WCLK_negedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A3_WCLK_negedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A4_WCLK_negedge  : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_A5_WCLK_negedge  : VitalTimingDataType := VitalTimingDataInit;

    variable PViol_WCLK : std_ulogic := '0';
    variable PInfo_WCLK : VitalPeriodDataType := VitalPeriodDataInit;

    -- Local variables used for functionality

  begin -- process
 
if (FIRST_TIME) then
        wait until ((WCLK_ipd = '0' or WCLK_ipd = '1') and
                    (WE_ipd = '0' or WE_ipd = '1') and
                    (A5_ipd = '0' or A5_ipd = '1') and
                    (A4_ipd = '0' or A4_ipd = '1') and
                    (A3_ipd = '0' or A3_ipd = '1') and
                    (A2_ipd = '0' or A2_ipd = '1') and
                    (A1_ipd = '0' or A1_ipd = '1') and
                    (A0_ipd = '0' or A0_ipd = '1'));
        WCLK_prev   := WCLK_ipd;
        WE_prev    := WE_ipd;
        D_prev     := D_ipd;
        Address    := (A5_ipd, A4_ipd, A3_ipd, A2_ipd, A1_ipd, A0_ipd);
        Index      := SLV_TO_INT(SLV => Address);
        O_zd       := MEM(Index);
        FIRST_TIME := FALSE;
    end if;
    ------------------------
    --  Timing Check Section
    ------------------------
    if (TimingChecksOn ) then

         VitalSetupHoldCheck (
          Violation               => Tviol_D_WCLK_negedge,
          TimingData              => Tmkr_D_WCLK_negedge,
          TestSignal              => D_ipd,
          TestSignalName          => "D",
          TestDelay               => 0 ns,
          RefSignal               => WCLK_ipd,
          RefSignalName           => "WCLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_D_WCLK_posedge_negedge,
          SetupLow                => tsetup_D_WCLK_negedge_negedge,
          HoldLow                => thold_D_WCLK_posedge_negedge,
          HoldHigh                 => thold_D_WCLK_negedge_negedge,
          CheckEnabled            => TO_X01(WE_ipd) /= '0',
          RefTransition           => 'F',
          HeaderMsg               => InstancePath & "/RAM64X1S_1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_WE_WCLK_negedge,
          TimingData              => Tmkr_WE_WCLK_negedge,
          TestSignal              => WE_ipd,
          TestSignalName          => "WE",
          TestDelay               => 0 ns,
          RefSignal               => WCLK_ipd,
          RefSignalName           => "WCLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_WE_WCLK_posedge_negedge,
          SetupLow                => tsetup_WE_WCLK_negedge_negedge,
          HoldLow                => thold_WE_WCLK_posedge_negedge,
          HoldHigh                 => thold_WE_WCLK_negedge_negedge,
          CheckEnabled            => TRUE,
          RefTransition           => 'F',
          HeaderMsg               => InstancePath & "/RAM64X1S_1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_A0_WCLK_negedge,
