                    PreviousDataIn => PrevData,
                    StateTable => RAMS_O_tab_1,
                    DataIn => (WCLK_prev, O_zd, D_prev, WE_prev, WCLK_ipd));

    O_zd := Violation XOR O_zd;

    WE_prev   := WE_ipd;
    WCLK_prev := WCLK_ipd;
    D_prev    := D_ipd;

    MEM(Index) <= O_zd;

    wait on A0_ipd, A1_ipd, A2_ipd, A3_ipd, A4_ipd, A5_ipd, D_ipd, WE_ipd, WCLK_ipd;

