          HoldHigh                 => thold_ADDRA_CLKA_negedge_posedge(2),
          CheckEnabled            => TO_X01(ENA_ipd) = '1',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAMB16_S1_S4",
