          TestSignalName          => "CLKA", 
          TestDelay               => 0 ns, 
          RefSignal               => CLKB_ipd, 
          RefSignalName           => "CLKB", 
          RefDelay                => 0 ns, 
          SetupHigh               => tsetup_CLKA_CLKB_posedge_posedge, 
          CheckEnabled            => ((TO_X01(ENA_ipd) = '1' AND TO_X01(ENB_ipd) = '1') AND
                                      (TO_X01(WEA_ipd) = '1' OR  TO_X01(WEB_ipd) = '1')),
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAMB16_S4_S18",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
     end if;

    --
    -- Port A
    --
    WR_A_LATER := FALSE;
    WR_B_LATER := FALSE;


    if (ENA_ipd = '1') then
        if (CLKA_ipd'event AND CLKA_ipd'last_value = '0') then
            if (CLKA_ipd = '1') then
                if (WEA_ipd = '1') then
                    if (VALID_ADDRA) then
                        if(WRITE_MODE_A = "WRITE_FIRST") then
                              DOA_zd := DIA_ipd;
                        elsif(WRITE_MODE_A = "READ_FIRST") then
                              DOA_zd := MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW));
                        elsif(WRITE_MODE_A /= "NO_CHANGE") then
                              assert false report
                              " Wrong value for WRITE_MODE, assuming WRITE_FIRST "
                              severity warning;
                              DOA_zd := DIA_ipd;
                        end if;
                       if (WRITE_MODE_A /= "READ_FIRST" ) then
                        MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := DIA_ipd;
                        else WR_A_LATER := TRUE;
                        end if;
                        if (ENB_ipd = '1' AND VALID_ADDRB AND HAS_OVERLAP) then
                            if (Tviol_CLKB_CLKA_posedge = 'X') then
                                if (WEB_ipd /= '0') then
                                  if (WRITE_MODE_A /= "READ_FIRST" AND WRITE_MODE_B /= "READ_FIRST") then
                                    COLLISION (ADDRA_ipd, OLP_LSB, OLP_MSB, "write", 
                                    "port A", "port B", InstancePath, MEM);
                                 end if;
                                if (WRITE_MODE_A /= "NO_CHANGE" AND WRITE_MODE_B /= "READ_FIRST" ) then
                                    DOA_zd (DOA_OV_MSB downto DOA_OV_LSB) := (others =>'X');
                               end if;
                                 if (WRITE_MODE_A /= "READ_FIRST" AND WRITE_MODE_B /= "NO_CHANGE" ) then
                                    DOB_zd (DOB_OV_MSB downto DOB_OV_LSB) := (others =>'X');
				end if;
                                else
				  if (WRITE_MODE_A /= "READ_FIRST" ) then
                                    COLLISION (ADDRA_ipd, OLP_LSB, OLP_MSB, "read",
                                    "port A", "port B", InstancePath, MEM);
                                    DOB_zd (DOB_OV_MSB downto DOB_OV_LSB) := (others =>'X');
				  end if;
                                end if;
                            end if;
                        end if;
                    else
                        SET_MEM_TO_X(ADDRA_ipd, MEM);
                        --SET_MEM_TO_X(ADDRA_ipd, MEMP);
			if (WRITE_MODE_A /= "NO_CHANGE") then
                        DOA_zd := (others => 'X');
			end if;
                    end if;
                elsif (WEA_ipd = 'X') then
                    if (VALID_ADDRA) then
                        MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := (others => 'X');
                    else
                        SET_MEM_TO_X(ADDRA_ipd, MEM);
                        --SET_MEM_TO_X(ADDRA_ipd, MEMP);
                    end if;
                    DOA_zd := (others => 'X');
                else
                    if (VALID_ADDRA) then
                        DOA_zd := MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW));
                    else
                        DOA_zd := (others => 'X');
                    end if;
                end if;
                if (SSRA_ipd = '1') then
                    DOA_zd := SRVA_A(3 downto 0 );
                elsif (SSRA_ipd = 'X') then
                    DOA_zd := (others => 'X');
                end if;
            elsif (CLKA_ipd = 'X') then
                if (WEA_ipd /= '0') then
                    if (VALID_ADDRA) then
                        MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := (others => 'X');
                    else
                        SET_MEM_TO_X(ADDRA_ipd, MEM);
                       -- SET_MEM_TO_X(ADDRA_ipd, MEMP);
                    end if;
                end if;
		if (WRITE_MODE_A /= "NO_CHANGE" ) then
                DOA_zd := (others => 'X');
		end if;
            end if; 
        elsif (CLKA_ipd'event AND CLKA_ipd'last_value = 'X') then
            if (CLKA_ipd = '1') then
                if (WEA_ipd /= '0') then
                    if (VALID_ADDRA) then
                        MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := (others => 'X');
                    else
                        SET_MEM_TO_X(ADDRA_ipd, MEM);
                        --SET_MEM_TO_X(ADDRA_ipd, MEMP);
                    end if;
                end if;
                DOA_zd := (others => 'X');
            end if;
        end if; 
    elsif (ENA_ipd = 'X') then
        if (CLKA_ipd'event AND CLKA_ipd'last_value /= '1') then
            if (CLKA_ipd /= '0') then
                if (WEA_ipd /= '0') then
                    if (VALID_ADDRA) then
                        MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := (others => 'X');
                    else
                        SET_MEM_TO_X(ADDRA_ipd, MEM);
                        --SET_MEM_TO_X(ADDRA_ipd, MEMP);
                        MEM := (others => 'X');
                        --MEMP := (others => 'X');
                    end if;
                end if;
                DOA_zd := (others => 'X');
            end if;
        end if; 
    end if; 
    
    --
    -- Port B
    --
    if (ENB_ipd = '1') then
        if (CLKB_ipd'event AND CLKB_ipd'last_value = '0') then
            if (CLKB_ipd = '1') then
                if (WEB_ipd = '1') then
                    if (VALID_ADDRB) then
                        if(WRITE_MODE_B = "WRITE_FIRST") then
                             DOB_zd := DIB_ipd;
                             DOPB_zd := DIPB_ipd;
                        elsif(WRITE_MODE_B = "READ_FIRST") then
                             DOB_zd := MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) ;
                             DOPB_zd :=MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (
ADDRESS_B*DIPBW)) ;
                        elsif(WRITE_MODE_B /= "NO_CHANGE") then
                            assert false report
                            " Wrong value for write_mode, assuming WRITE_FIRST "
                            severity warning;
                            DOB_zd := DIB_ipd;
                            DOPB_zd := DIPB_ipd;
                        end if;
			if (WRITE_MODE_B /= "READ_FIRST") then
                        MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := DIB_ipd;
                        MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (ADDRESS_B*DIPBW)) := DIPB_ipd;
			else WR_B_LATER := TRUE;
			end if;
                        if (ENA_ipd = '1' AND VALID_ADDRA AND HAS_OVERLAP) then
                            if (Tviol_CLKA_CLKB_posedge = 'X') then
                                if (WEA_ipd /= '0') then
				  if (WRITE_MODE_A /= "READ_FIRST" AND WRITE_MODE_B /= "READ_FIRST" ) then
                                    COLLISION (ADDRB_ipd, OLP_LSB, OLP_MSB, "write",
                                    "port B", "port A", InstancePath, MEM);
				  end if;
				  if ( SSRA_ipd = '0' AND WRITE_MODE_A /= "NO_CHANGE" AND WRITE_MODE_B /= "READ_FIRST") then
                                    DOA_zd (DOA_OV_MSB downto DOA_OV_LSB) := (others => 'X');
				  end if;
				  if (WRITE_MODE_A /= "READ_FIRST" AND WRITE_MODE_B /= "NO_CHANGE" ) then
                                    DOB_zd (DOB_OV_MSB downto DOB_OV_LSB) := (others => 'X');
				  end if;
                                else
				  if (WRITE_MODE_B /= "READ_FIRST" ) then
                                    COLLISION (ADDRB_ipd, OLP_LSB, OLP_MSB, "read",
                                    "port B", "port A", InstancePath, MEM);
				  end if;
				  if ( SSRA_ipd = '0' AND WRITE_MODE_B /= "READ_FIRST" ) then
                                    DOA_zd (DOA_OV_MSB downto DOA_OV_LSB) := (others => 'X');
                                  end if;
                                end if;
                            end if;
                        end if;
                    else
                        SET_MEM_TO_X(ADDRB_ipd, MEM);
                        SET_MEM_TO_X(ADDRB_ipd, MEMP);
			if (WRITE_MODE_B /= "NO_CHANGE" ) then
                        DOB_zd := (others => 'X');
                        DOPB_zd := (others => 'X');
			end if;
                    end if;
                elsif (WEB_ipd = 'X') then
                    if (VALID_ADDRB) then
                        MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := (others => 'X');
                        MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (ADDRESS_B*DIPBW)) := (others => 'X');
                    else
                        SET_MEM_TO_X(ADDRB_ipd, MEM);
                        SET_MEM_TO_X(ADDRB_ipd, MEMP);
                    end if;
                    DOB_zd := (others => 'X');
                    DOPB_zd := (others => 'X');
                else 
                    if (VALID_ADDRB ) then
                      --if (ENA_ipd = '0' OR WEA_ipd = '0' OR Tviol_CLKB_CLKA_posedge /= 'X' OR (HAS_OVERLAP = FALSE)) then
                        DOB_zd := MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW));
                        DOPB_zd := MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (ADDRESS_B*DIPBW));
                      if (Tviol_CLKB_CLKA_posedge = 'X' AND HAS_OVERLAP = TRUE AND WRITE_MODE_A /= "READ_FIRST") then
                          DOB_zd (DOB_OV_MSB downto DOB_OV_LSB) := (others => 'X');
                      end if;
                    else
                        DOB_zd := (others => 'X');
                        DOPB_zd := (others => 'X');
                    end if;
                end if;
                if (SSRB_ipd = '1') then
                    DOB_zd := SRVA_B(15 downto 0 );
                    DOPB_zd :=  SRVA_B(17 downto 16 );
                elsif (SSRB_ipd = 'X') then
                    DOB_zd := (others => 'X');
                    DOPB_zd := (others => 'X');
                end if;
            elsif (CLKB_ipd = 'X') then
                if (WEB_ipd /= '0') then
                    if (VALID_ADDRB) then
                        MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := (others => 'X');
                        MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (ADDRESS_B*DIPBW)) := (others => 'X');
                    else
                        SET_MEM_TO_X(ADDRB_ipd, MEM);
                        SET_MEM_TO_X(ADDRB_ipd, MEMP);
                    end if;
                end if;
                DOB_zd := (others => 'X');
                DOPB_zd := (others => 'X');
            end if; 
        elsif (CLKB_ipd'event AND CLKB_ipd'last_value = 'X') then
            if (CLKB_ipd = '1') then
                if (WEB_ipd /= '0') then
                    if (VALID_ADDRB) then
                        MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := (others => 'X');
                        MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (ADDRESS_B*DIPBW)) := (others => 'X');
                    else
                        SET_MEM_TO_X(ADDRB_ipd, MEM);
                        SET_MEM_TO_X(ADDRB_ipd, MEMP);
                    end if;
                end if;
                DOB_zd := (others => 'X');
                DOPB_zd := (others => 'X');
            end if;
        end if; 
    elsif (ENB_ipd = 'X') then
        if (CLKB_ipd'event AND CLKB_ipd'last_value /= '1') then
            if (CLKB_ipd /= '0') then
                if (WEB_ipd /= '0') then
                    if (VALID_ADDRB) then
                        MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := (others => 'X');
                        MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (ADDRESS_B*DIPBW)) := (others => 'X');
                    else
                        SET_MEM_TO_X(ADDRB_ipd, MEM);
                        SET_MEM_TO_X(ADDRB_ipd, MEMP);
                        MEM := (others => 'X');
                        MEMP := (others => 'X');
                    end if;
                end if;
                DOB_zd := (others => 'X');
                DOPB_zd := (others => 'X');
            end if;
        end if; 
    end if;

    if (WR_A_LATER = TRUE ) then

        MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := DIA_ipd ;
    end if;

    if (WR_B_LATER = TRUE ) then

        MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := DIB_ipd;
        MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (ADDRESS_B*DIPBW)) := DIPB_ipd;
    end if;

    if (WR_A_LATER AND WR_B_LATER ) then
        COLLISION (ADDRB_ipd, OLP_LSB, OLP_MSB, "write", "port B", "port A", InstancePath, MEM);
    end if;

    DOA_zd(3)  := Violation XOR DOA_zd(3);
    DOA_zd(2)  := Violation XOR DOA_zd(2);
    DOA_zd(1)  := Violation XOR DOA_zd(1);
    DOA_zd(0)  := Violation XOR DOA_zd(0);
    DOB_zd(15) := Violation XOR DOB_zd(15);
    DOB_zd(14) := Violation XOR DOB_zd(14);
    DOB_zd(13) := Violation XOR DOB_zd(13);
    DOB_zd(12) := Violation XOR DOB_zd(12);
    DOB_zd(11) := Violation XOR DOB_zd(11);
    DOB_zd(10) := Violation XOR DOB_zd(10);
    DOB_zd(9)  := Violation XOR DOB_zd(9);
    DOB_zd(8)  := Violation XOR DOB_zd(8);
    DOB_zd(7)  := Violation XOR DOB_zd(7);
    DOB_zd(6)  := Violation XOR DOB_zd(6);
    DOB_zd(5)  := Violation XOR DOB_zd(5);
    DOB_zd(4)  := Violation XOR DOB_zd(4);
    DOB_zd(3)  := Violation XOR DOB_zd(3);
    DOB_zd(2)  := Violation XOR DOB_zd(2);
    DOB_zd(1)  := Violation XOR DOB_zd(1);
    DOB_zd(0)  := Violation XOR DOB_zd(0);
    DOPB_zd(1)  := Violation XOR DOPB_zd(1);
    DOPB_zd(0)  := Violation XOR DOPB_zd(0);


    ----------------------
    --  Path Delay Section
    ----------------------

    VitalPathDelay01 (
      OutSignal => DOA(3),
      GlitchData => DOA_GlitchData3,
      OutSignalName => "DOA(3)",
      OutTemp => DOA_zd(3),
      Paths => (0 => (CLKA_ipd'last_event,  tpd_CLKA_DOA(3),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DOA(2),
      GlitchData => DOA_GlitchData2,
      OutSignalName => "DOA(2)",    
      OutTemp => DOA_zd(2),  
      Paths => (0 => (CLKA_ipd'last_event,  tpd_CLKA_DOA(2),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DOA(1),
      GlitchData => DOA_GlitchData1,
      OutSignalName => "DOA(1)",    
      OutTemp => DOA_zd(1),  
      Paths => (0 => (CLKA_ipd'last_event,  tpd_CLKA_DOA(1),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DOA(0),
      GlitchData => DOA_GlitchData0,
      OutSignalName => "DOA(0)",    
      OutTemp => DOA_zd(0),  
      Paths => (0 => (CLKA_ipd'last_event,  tpd_CLKA_DOA(0),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(15),
      GlitchData => DOB_GlitchData15,
      OutSignalName => "DOB(15)",
      OutTemp => DOB_zd(15),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(15),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(14),
      GlitchData => DOB_GlitchData14,
      OutSignalName => "DOB(14)",
      OutTemp => DOB_zd(14),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(14),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(13),
      GlitchData => DOB_GlitchData13,
      OutSignalName => "DOB(13)",
      OutTemp => DOB_zd(13),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(13),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(12),
      GlitchData => DOB_GlitchData12,
      OutSignalName => "DOB(12)",
      OutTemp => DOB_zd(12),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(12),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(11),
      GlitchData => DOB_GlitchData11,
      OutSignalName => "DOB(11)",
      OutTemp => DOB_zd(11),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(11),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(10),
      GlitchData => DOB_GlitchData10,
      OutSignalName => "DOB(10)",
      OutTemp => DOB_zd(10),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(10),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(9),
      GlitchData => DOB_GlitchData9,
      OutSignalName => "DOB(9)",
      OutTemp => DOB_zd(9),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(9),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(8),
      GlitchData => DOB_GlitchData8,
      OutSignalName => "DOB(8)",
      OutTemp => DOB_zd(8),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(8),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(7),
      GlitchData => DOB_GlitchData7,
      OutSignalName => "DOB(7)",
      OutTemp => DOB_zd(7),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(7),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(6),
      GlitchData => DOB_GlitchData6,
      OutSignalName => "DOB(6)",
      OutTemp => DOB_zd(6),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(6),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(5),
      GlitchData => DOB_GlitchData5,
      OutSignalName => "DOB(5)",
      OutTemp => DOB_zd(5),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(5),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(4),
      GlitchData => DOB_GlitchData4,
      OutSignalName => "DOB(4)",
      OutTemp => DOB_zd(4),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(4),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(3),
      GlitchData => DOB_GlitchData3,
      OutSignalName => "DOB(3)",
      OutTemp => DOB_zd(3),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(3),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DOB(2),
      GlitchData => DOB_GlitchData2,
      OutSignalName => "DOB(2)",    
      OutTemp => DOB_zd(2),  
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(2),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DOB(1),
      GlitchData => DOB_GlitchData1,
      OutSignalName => "DOB(1)",    
      OutTemp => DOB_zd(1),  
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(1),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DOB(0),
      GlitchData => DOB_GlitchData0,
      OutSignalName => "DOB(0)",    
      OutTemp => DOB_zd(0),  
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(0),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DOPB(1),
      GlitchData => DOPB_GlitchData1,
      OutSignalName => "DOPB(1)",    
      OutTemp => DOPB_zd(1),  
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOPB(1),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DOPB(0),
      GlitchData => DOPB_GlitchData0,
      OutSignalName => "DOPB(0)",    
      OutTemp => DOPB_zd(0),  
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOPB(0),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    wait on CLKA_ipd, CLKB_ipd, WEA_ipd, WEB_ipd, ENA_ipd, ENB_ipd, 
            SSRA_ipd, SSRB_ipd, DIA_ipd, DIB_ipd, DIPB_ipd, 
            ADDRA_ipd, ADDRB_ipd;

  end process VITALBehavior;

end RAMB16_S4_S18_V;

configuration CFG_RAMB16_S4_S18_V of RAMB16_S4_S18 is
