          Violation               => Tviol_ADDRB6_CLKB_posedge,
          TimingData              => Tmkr_ADDRB6_CLKB_posedge,
          TestSignal              => ADDRB_ipd(6),
          TestSignalName          => "ADDRB(6)",
          TestDelay               => 0 ns,
          RefSignal               => CLKB_ipd,
          RefSignalName           => "CLKB",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_ADDRB_CLKB_posedge_posedge(6),
