    VitalWireDelay (DI_ipd(6),   DI(6),   tipd_DI(6));
    VitalWireDelay (DI_ipd(7),   DI(7),   tipd_DI(7));
    VitalWireDelay (EN_ipd,      EN,      tipd_EN);
