    VitalWireDelay (CLK_ipd,     CLK,     tipd_CLK);
  end block;

  --------------------
  -- RAMB16_S9 Behavior
  --------------------
  VITALBehavior : process

    -- Local variables used for timing checks
    variable Tviol_DIP0_CLK_posedge   : std_ulogic := '0';
