        ADDRESS := SLV_TO_INT(ADDR_ipd);
    end if;

    if (EN_ipd = '1') then
        if (CLK_ipd'event AND CLK_ipd'last_value = '0') then
            if (CLK_ipd = '1') then
                if (WE_ipd = '1') then
                    if (VALID_ADDR) then
                        if(WRITE_MODE = "WRITE_FIRST") then
                              DO_zd := DI_ipd;
                              DOP_zd := DIP_ipd;
                        elsif(WRITE_MODE = "READ_FIRST") then
                              DO_zd := MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW));
                              DOP_zd := MEMP((ADDRESS*DIPW + DIPW_1) downto (ADDRESS*DIPW));
                        elsif(WRITE_MODE /= "NO_CHANGE") then
                              assert false report
                              " Wrong value for WRITE_MODE, assuming WRITE_FIRST "
                              severity warning;
                              DO_zd := DI_ipd;
                              DOP_zd := DIP_ipd;
                        end if;

                        MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := DI_ipd;
                        MEMP((ADDRESS*DIPW + DIPW_1) downto (ADDRESS*DIPW)) := DIP_ipd;
                    else
                        SET_MEM_TO_X(ADDR_ipd, MEM);
                        DO_zd := (others => 'X');
                        DOP_zd := (others => 'X');
                    end if;
                elsif (WE_ipd = 'X') then
                    if (VALID_ADDR) then
                        MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := (others => 'X');
                        MEMP((ADDRESS*DIPW + DIPW_1) downto (ADDRESS*DIPW)) := (others => 'X');
                    else
                        SET_MEM_TO_X(ADDR_ipd, MEM);
                        SET_MEM_TO_X(ADDR_ipd, MEMP);
                    end if;
                    DO_zd := (others => 'X');
                    DOP_zd := (others => 'X');
                else 
                    if (VALID_ADDR) then
                        DO_zd := MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW));
                        DOP_zd := MEMP((ADDRESS*DIPW + DIPW_1) downto (ADDRESS*DIPW));
                    else
                        DO_zd := (others => 'X');
                        DOP_zd := (others => 'X');
                    end if;
                end if;
                if (SSR_ipd = '1') then
                    DO_zd :=  SRVA(7 downto 0 );
                    DOP_zd := SRVA(0 downto 0 );
                elsif (SSR_ipd = 'X') then
                    DO_zd := (others => 'X');
                    DOP_zd := (others => 'X');
                end if;
            elsif (CLK_ipd = 'X') then
                if (WE_ipd /= '0') then
                    if (VALID_ADDR) then
                        MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := (others => 'X');
                        MEMP((ADDRESS*DIPW + DIPW_1) downto (ADDRESS*DIPW)) := (others => 'X');
                    else
                        SET_MEM_TO_X(ADDR_ipd, MEM);
                        SET_MEM_TO_X(ADDR_ipd, MEMP);
                    end if;
                end if;
                DO_zd := (others => 'X');
                DOP_zd := (others => 'X');
            end if; 
        elsif (CLK_ipd'event AND CLK_ipd'last_value = 'X') then
            if (CLK_ipd = '1') then
                if (WE_ipd /= '0') then
                    if (VALID_ADDR) then
                        MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := (others => 'X');
                        MEMP((ADDRESS*DIPW + DIPW_1) downto (ADDRESS*DIPW)) := (others => 'X');
                    else
                        SET_MEM_TO_X(ADDR_ipd, MEM);
                        SET_MEM_TO_X(ADDR_ipd, MEMP);
                    end if;
                end if;
                DO_zd := (others => 'X');
                DOP_zd := (others => 'X');
            end if;
        end if; 
    elsif (EN_ipd = 'X') then
        if (CLK_ipd'event AND CLK_ipd'last_value /= '1') then
            if (CLK_ipd /= '0') then
                if (WE_ipd /= '0') then
                    if (VALID_ADDR) then
