      OutTemp => DO_zd(3),
      Paths => (0 => (CLK_ipd'last_event,  tpd_CLK_DO(3),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
