      GlitchData => DO_GlitchData1,
      OutSignalName => "DO(1)",    
      OutTemp => DO_zd(1),  
      Paths => (0 => (CLK_ipd'last_event,  tpd_CLK_DO(1),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DO(0),
      GlitchData => DO_GlitchData0,
      OutSignalName => "DO(0)",    
      OutTemp => DO_zd(0),  
      Paths => (0 => (CLK_ipd'last_event,  tpd_CLK_DO(0),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DOP(0),
      GlitchData => DOP_GlitchData0,
      OutSignalName => "DOP(0)",    
      OutTemp => DOP_zd(0),  
      Paths => (0 => (CLK_ipd'last_event,  tpd_CLK_DOP(0),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    wait on CLK_ipd, WE_ipd, EN_ipd, SSR_ipd, DI_ipd, DIP_ipd, ADDR_ipd;

  end process VITALBehavior;

end RAMB16_S9_V;

