          MsgSeverity             => WARNING);

         VitalPeriodPulseCheck (
          Violation               => Pviol_CLKA,
          PeriodData              => PInfo_CLKA,
          TestSignal              => CLKA_ipd,
          TestSignalName          => "CLKA",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_CLKA_posedge,
          PulseWidthLow           => tpw_CLKA_negedge,
          CheckEnabled            => TO_X01(ENA_ipd) = '1',
          HeaderMsg               => InstancePath &"/RAMB16_S9_S9",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalPeriodPulseCheck (
          Violation               => Pviol_CLKB,
          PeriodData              => PInfo_CLKB,
          TestSignal              => CLKB_ipd,
          TestSignalName          => "CLKB",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_CLKB_posedge,
          PulseWidthLow           => tpw_CLKB_negedge,
          CheckEnabled            => TO_X01(ENB_ipd) = '1',
          HeaderMsg               => InstancePath &"/RAMB16_S9_S9",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

    end if;

    Violation := 
                 Tviol_DIA7_CLKA_posedge   or Tviol_DIA6_CLKA_posedge   or
                 Tviol_DIA5_CLKA_posedge   or Tviol_DIA4_CLKA_posedge   or
                 Tviol_DIA3_CLKA_posedge   or Tviol_DIA2_CLKA_posedge   or
                 Tviol_DIA1_CLKA_posedge   or Tviol_DIA0_CLKA_posedge   or

                 Tviol_ENA_CLKA_posedge    or Tviol_WEA_CLKA_posedge    or
                 Tviol_SSRA_CLKA_posedge   or

                 Tviol_ADDRA7_CLKA_posedge or Tviol_ADDRA6_CLKA_posedge or
                 Tviol_ADDRA5_CLKA_posedge or Tviol_ADDRA4_CLKA_posedge or
                 Tviol_ADDRA3_CLKA_posedge or Tviol_ADDRA2_CLKA_posedge or
                 Tviol_ADDRA1_CLKA_posedge or Tviol_ADDRA0_CLKA_posedge or 

                 Pviol_CLKA                or

                 Tviol_DIB7_CLKB_posedge   or Tviol_DIB6_CLKB_posedge   or
                 Tviol_DIB5_CLKB_posedge   or Tviol_DIB4_CLKB_posedge   or
                 Tviol_DIB3_CLKB_posedge   or Tviol_DIB2_CLKB_posedge   or
                 Tviol_DIB1_CLKB_posedge   or Tviol_DIB0_CLKB_posedge   or

                 Tviol_ENB_CLKB_posedge    or Tviol_WEB_CLKB_posedge    or
                 Tviol_SSRB_CLKB_posedge   or

                 Tviol_ADDRB7_CLKB_posedge or Tviol_ADDRB6_CLKB_posedge or
                 Tviol_ADDRB5_CLKB_posedge or Tviol_ADDRB4_CLKB_posedge or
                 Tviol_ADDRB3_CLKB_posedge or Tviol_ADDRB2_CLKB_posedge or
                 Tviol_ADDRB1_CLKB_posedge or Tviol_ADDRB0_CLKB_posedge or

                 Pviol_CLKB;

    -------------------------
    --  Functionality Section
    -------------------------

    VALID_ADDRA := ADDR_IS_VALID(ADDRA_ipd);
    VALID_ADDRB := ADDR_IS_VALID(ADDRB_ipd);

    if (VALID_ADDRA) then
        ADDRESS_A := SLV_TO_INT(ADDRA_ipd);
    end if;

    if (VALID_ADDRB) then
        ADDRESS_B := SLV_TO_INT(ADDRB_ipd);
    end if;

    if (VALID_ADDRA AND VALID_ADDRB) then
        ADDR_OVERLAP (ADDRESS_A, ADDRESS_B, DIAW, DIBW, HAS_OVERLAP, 
        OLP_LSB, OLP_MSB, DOA_OV_LSB, DOA_OV_MSB, DOB_OV_LSB, DOB_OV_MSB);
        ADDR_OVERLAP (ADDRESS_A, ADDRESS_B, DIPAW, DIPBW, HAS_OVERLAP_P,
        OLPP_LSB, OLPP_MSB, DOPA_OV_LSB, DOPA_OV_MSB, DOPB_OV_LSB, DOPB_OV_MSB);
    end if;

    if (HAS_OVERLAP = TRUE ) then
         VitalSetupHoldCheck (
          Violation               => Tviol_CLKB_CLKA_posedge,
          TimingData              => Tmkr_CLKB_CLKA_posedge,
          TestSignal              => CLKB_ipd,
          TestSignalName          => "CLKB",
          TestDelay               => 0 ns,
          RefSignal               => CLKA_ipd,
          RefSignalName           => "CLKA",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_CLKB_CLKA_posedge_posedge,
          CheckEnabled            => ((TO_X01(ENA_ipd) = '1' AND TO_X01(ENB_ipd) = '1') AND
                                      (TO_X01(WEA_ipd) = '1' OR  TO_X01(WEB_ipd) = '1')),
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAMB16_S9_S9",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck ( 
          Violation               => Tviol_CLKA_CLKB_posedge, 
          TimingData              => Tmkr_CLKA_CLKB_posedge, 
          TestSignal              => CLKA_ipd, 
          TestSignalName          => "CLKA", 
          TestDelay               => 0 ns, 
          RefSignal               => CLKB_ipd, 
          RefSignalName           => "CLKB", 
          RefDelay                => 0 ns, 
          SetupHigh               => tsetup_CLKA_CLKB_posedge_posedge, 
          CheckEnabled            => ((TO_X01(ENA_ipd) = '1' AND TO_X01(ENB_ipd) = '1') AND
                                      (TO_X01(WEA_ipd) = '1' OR  TO_X01(WEB_ipd) = '1')),
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/RAMB16_S9_S9",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);
     end if;

    --
    -- Port A
    --
    WR_A_LATER := FALSE;
    WR_B_LATER := FALSE;

    if (ENA_ipd = '1') then
        if (CLKA_ipd'event AND CLKA_ipd'last_value = '0') then
            if (CLKA_ipd = '1') then
                if (WEA_ipd = '1') then
                    if (VALID_ADDRA) then
                        if(WRITE_MODE_A = "WRITE_FIRST") then
                              DOA_zd := DIA_ipd;
                              DOPA_zd := DIPA_ipd;
                        elsif(WRITE_MODE_A = "READ_FIRST") then
                              DOA_zd := MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW));
                              DOPA_zd := MEMP((ADDRESS_A*DIPAW + DIPAW_1) downto (ADDRESS_A*DIPAW));
                        elsif(WRITE_MODE_A /= "NO_CHANGE") then
                              assert false report
                              " Wrong value for WRITE_MODE, assuming WRITE_FIRST "
                              severity warning;
                              DOA_zd := DIA_ipd;
                              DOPA_zd := DIPA_ipd;
                        end if;
                        if (WRITE_MODE_A /= "READ_FIRST" ) then
                        MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := DIA_ipd;
                        MEMP((ADDRESS_A*DIPAW + DIPAW_1) downto (ADDRESS_A*DIPAW)) := DIPA_ipd;
                        else WR_A_LATER := TRUE;
                        end if;

                        if (ENB_ipd = '1' AND VALID_ADDRB AND HAS_OVERLAP) then
                            if (Tviol_CLKB_CLKA_posedge = 'X') then
                                if (WEB_ipd /= '0') then
                                  if (WRITE_MODE_A /= "READ_FIRST" AND WRITE_MODE_B /= "READ_FIRST") then
                                    COLLISION (ADDRA_ipd, OLP_LSB, OLP_MSB, "write", 
                                    "port A", "port B", InstancePath, MEM);
                                    COLLISION (ADDRA_ipd, OLPP_LSB, OLPP_MSB, "write", 
                                    "port A", "port B", InstancePath, MEMP);
                                  end if;
                                  if (WRITE_MODE_A /= "NO_CHANGE" AND WRITE_MODE_B/= "READ_FIRST" ) then
                                    DOA_zd (DOA_OV_MSB downto DOA_OV_LSB) := (others =>'X');
                                    DOPA_zd (DOPA_OV_MSB downto DOPA_OV_LSB) := (others =>'X');
                                  end if;
                                  if (WRITE_MODE_A /= "READ_FIRST" AND WRITE_MODE_B /= "NO_CHANGE" ) then
                                    DOB_zd (DOB_OV_MSB downto DOB_OV_LSB) := (others =>'X');
                                    DOPB_zd (DOPB_OV_MSB downto DOPB_OV_LSB) := (others =>'X');
				  end if;
                                else
				  if (WRITE_MODE_A /= "READ_FIRST" ) then
                                    COLLISION (ADDRA_ipd, OLP_LSB, OLP_MSB, "read",
                                    "port A", "port B", InstancePath, MEM);
                                    COLLISION (ADDRA_ipd, OLPP_LSB, OLPP_MSB, "read",
                                    "port A", "port B", InstancePath, MEMP);
                                    DOB_zd (DOB_OV_MSB downto DOB_OV_LSB) := (others =>'X');
                                    DOPB_zd (DOPB_OV_MSB downto DOPB_OV_LSB) := (others =>'X');
                                  end if;
                                end if;
                            end if;
                        end if;
                    else
                        SET_MEM_TO_X(ADDRA_ipd, MEM);
                        SET_MEM_TO_X(ADDRA_ipd, MEMP);
                        if (WRITE_MODE_A /= "NO_CHANGE") then
                        DOA_zd := (others => 'X');
                        DOPA_zd := (others => 'X');
                        end if;
                    end if;
                elsif (WEA_ipd = 'X') then
                    if (VALID_ADDRA) then
                        MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := (others => 'X');
                        MEMP((ADDRESS_A*DIPAW + DIPAW_1) downto (ADDRESS_A*DIPAW)) := (others => 'X');
                    else
                        SET_MEM_TO_X(ADDRA_ipd, MEM);
                        SET_MEM_TO_X(ADDRA_ipd, MEMP);
                    end if;
                    DOA_zd := (others => 'X');
                    DOPA_zd := (others => 'X');
                else
                    if (VALID_ADDRA) then
                        DOA_zd := MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW));
                        DOPA_zd := MEMP((ADDRESS_A*DIPAW + DIPAW_1) downto (ADDRESS_A*DIPAW));
                    else
                        DOA_zd := (others => 'X');
                        DOPA_zd := (others => 'X');
                    end if;
                end if;
                if (SSRA_ipd = '1') then
                    DOA_zd := SRVA_A(7 downto 0 );
                    DOPA_zd := SRVA_A( 8 downto 8 );
                elsif (SSRA_ipd = 'X') then
                    DOA_zd := (others => 'X');
                    DOPA_zd := (others => 'X');
                end if;
            elsif (CLKA_ipd = 'X') then
                if (WEA_ipd /= '0') then
                    if (VALID_ADDRA) then
                        MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := (others => 'X');
                        MEMP((ADDRESS_A*DIPAW + DIPAW_1) downto (ADDRESS_A*DIPAW)) := (others => 'X');
                    else
                        SET_MEM_TO_X(ADDRA_ipd, MEM);
                        SET_MEM_TO_X(ADDRA_ipd, MEMP);
                    end if;
                end if;
                if (WRITE_MODE_A /= "NO_CHANGE" ) then
                DOA_zd := (others => 'X');
                DOPA_zd := (others => 'X');
		end if;
            end if; 
        elsif (CLKA_ipd'event AND CLKA_ipd'last_value = 'X') then
            if (CLKA_ipd = '1') then
                if (WEA_ipd /= '0') then
                    if (VALID_ADDRA) then
                        MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := (others => 'X');
                        MEMP((ADDRESS_A*DIPAW + DIPAW_1) downto (ADDRESS_A*DIPAW)) := (others => 'X');
                    else
                        SET_MEM_TO_X(ADDRA_ipd, MEM);
                        SET_MEM_TO_X(ADDRA_ipd, MEMP);
                    end if;
                end if;
                DOA_zd := (others => 'X');
                DOPA_zd := (others => 'X');
            end if;
        end if; 
    elsif (ENA_ipd = 'X') then
        if (CLKA_ipd'event AND CLKA_ipd'last_value /= '1') then
            if (CLKA_ipd /= '0') then
                if (WEA_ipd /= '0') then
                    if (VALID_ADDRA) then
                        MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := (others => 'X');
                        MEMP((ADDRESS_A*DIPAW + DIPAW_1) downto (ADDRESS_A*DIPAW)) := (others => 'X');
                    else
                        SET_MEM_TO_X(ADDRA_ipd, MEM);
                        SET_MEM_TO_X(ADDRA_ipd, MEMP);
                        MEM := (others => 'X');
                        MEMP := (others => 'X');
                    end if;
                end if;
                DOA_zd := (others => 'X');
                DOPA_zd := (others => 'X');
            end if;
        end if; 
    end if; 
    
    --
    -- Port B
    --
    if (ENB_ipd = '1') then
        if (CLKB_ipd'event AND CLKB_ipd'last_value = '0') then
            if (CLKB_ipd = '1') then
                if (WEB_ipd = '1') then
                    if (VALID_ADDRB) then
                        if(WRITE_MODE_B = "WRITE_FIRST") then
                             DOB_zd := DIB_ipd;
                             DOPB_zd := DIPB_ipd;
                        elsif(WRITE_MODE_B = "READ_FIRST") then
                             DOB_zd := MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) ;
                             DOPB_zd :=MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (
ADDRESS_B*DIPBW)) ;
                        elsif(WRITE_MODE_B /= "NO_CHANGE") then
                            assert false report
                            " Wrong value for write_mode, assuming WRITE_FIRST "
                            severity warning;
                            DOB_zd := DIB_ipd;
                            DOPB_zd := DIPB_ipd;
                        end if;
			if (WRITE_MODE_B /= "READ_FIRST") then
                        MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := DIB_ipd;
                        MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (ADDRESS_B*DIPBW)) := DIPB_ipd;
			else WR_B_LATER := TRUE;
                        end if;
                        if (ENA_ipd = '1' AND VALID_ADDRA AND HAS_OVERLAP) then
                            if (Tviol_CLKA_CLKB_posedge = 'X') then
                                if (WEA_ipd /= '0') then
				   if (WRITE_MODE_A /= "READ_FIRST" AND WRITE_MODE_B /= "READ_FIRST" ) then
                                    COLLISION (ADDRB_ipd, OLP_LSB, OLP_MSB, "write",
                                    "port B", "port A", InstancePath, MEM);
                                    COLLISION (ADDRB_ipd, OLPP_LSB, OLPP_MSB, "write",
                                    "port B", "port A", InstancePath, MEMP);
				   end if;
				  if ( SSRA_ipd = '0' AND WRITE_MODE_A /= "NO_CHANGE" AND WRITE_MODE_B /= "READ_FIRST"  ) then
                                    DOA_zd (DOA_OV_MSB downto DOA_OV_LSB) := (others => 'X');
                                    DOPA_zd (DOPA_OV_MSB downto DOPA_OV_LSB) := (others => 'X');
                                  end if;
				  if (WRITE_MODE_A /= "READ_FIRST" AND WRITE_MODE_B /= "NO_CHANGE" ) then
                                    DOB_zd (DOB_OV_MSB downto DOB_OV_LSB) := (others => 'X');
                                    DOPB_zd (DOPB_OV_MSB downto DOPB_OV_LSB) := (others => 'X');
				  end if;
                                else
				  if (WRITE_MODE_B /= "READ_FIRST" ) then
                                    COLLISION (ADDRB_ipd, OLP_LSB, OLP_MSB, "read",
                                    "port B", "port A", InstancePath, MEM);
                                    COLLISION (ADDRB_ipd, OLPP_LSB, OLPP_MSB, "read",
                                    "port B", "port A", InstancePath, MEMP);
				  end if;
				  if ( SSRA_ipd = '0' AND WRITE_MODE_B /= "READ_FIRST" ) then
                                    DOA_zd (DOA_OV_MSB downto DOA_OV_LSB) := (others => 'X');
                                    DOPA_zd (DOPA_OV_MSB downto DOPA_OV_LSB) := (others => 'X');
                                  end if;

                                end if;
                            end if;
                        end if;
                    else
                        SET_MEM_TO_X(ADDRB_ipd, MEM);
                        SET_MEM_TO_X(ADDRB_ipd, MEMP);
                        if (WRITE_MODE_B /= "NO_CHANGE" ) then
                        DOB_zd := (others => 'X');
                        DOPB_zd := (others => 'X');
			end if;
                    end if;
                elsif (WEB_ipd = 'X') then
                    if (VALID_ADDRB) then
                        MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := (others => 'X');
                        MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (ADDRESS_B*DIPBW)) := (others => 'X');
                    else
                        SET_MEM_TO_X(ADDRB_ipd, MEM);
                        SET_MEM_TO_X(ADDRB_ipd, MEMP);
                    end if;
                    DOB_zd := (others => 'X');
                    DOPB_zd := (others => 'X');
                else 
                    if (VALID_ADDRB ) then
                        DOB_zd := MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW));
                        DOPB_zd := MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (ADDRESS_B*DIPBW));
		     if (Tviol_CLKB_CLKA_posedge = 'X' AND HAS_OVERLAP = TRUE AND WRITE_MODE_A /= "READ_FIRST") then
		      DOB_zd (DOB_OV_MSB downto DOB_OV_LSB) := (others => 'X');
		      DOPB_zd (DOPB_OV_MSB downto DOPB_OV_LSB) := (others => 'X');
                     end if;
                    else
                        DOB_zd := (others => 'X');
                        DOPB_zd := (others => 'X');
                    end if;
                end if;
                if (SSRB_ipd = '1') then
                    DOB_zd := SRVA_B(7 downto 0 );
                    DOPB_zd :=  SRVA_B( 8 downto 8 );
                elsif (SSRB_ipd = 'X') then
                    DOB_zd := (others => 'X');
                    DOPB_zd := (others => 'X');
                end if;
            elsif (CLKB_ipd = 'X') then
                if (WEB_ipd /= '0') then
                    if (VALID_ADDRB) then
                        MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := (others => 'X');
                        MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (ADDRESS_B*DIPBW)) := (others => 'X');
                    else
                        SET_MEM_TO_X(ADDRB_ipd, MEM);
                        SET_MEM_TO_X(ADDRB_ipd, MEMP);
                    end if;
                end if;
                DOB_zd := (others => 'X');
                DOPB_zd := (others => 'X');
            end if; 
        elsif (CLKB_ipd'event AND CLKB_ipd'last_value = 'X') then
            if (CLKB_ipd = '1') then
                if (WEB_ipd /= '0') then
                    if (VALID_ADDRB) then
                        MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := (others => 'X');
                        MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (ADDRESS_B*DIPBW)) := (others => 'X');
                    else
                        SET_MEM_TO_X(ADDRB_ipd, MEM);
                        SET_MEM_TO_X(ADDRB_ipd, MEMP);
                    end if;
                end if;
                DOB_zd := (others => 'X');
                DOPB_zd := (others => 'X');
            end if;
        end if; 
    elsif (ENB_ipd = 'X') then
        if (CLKB_ipd'event AND CLKB_ipd'last_value /= '1') then
            if (CLKB_ipd /= '0') then
                if (WEB_ipd /= '0') then
                    if (VALID_ADDRB) then
                        MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := (others => 'X');
                        MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (ADDRESS_B*DIPBW)) := (others => 'X');
                    else
                        SET_MEM_TO_X(ADDRB_ipd, MEM);
                        SET_MEM_TO_X(ADDRB_ipd, MEMP);
                        MEM := (others => 'X');
                        MEMP := (others => 'X');
                    end if;
                end if;
                DOB_zd := (others => 'X');
                DOPB_zd := (others => 'X');
            end if;
        end if; 
    end if;

    if (WR_A_LATER = TRUE ) then

        MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := DIA_ipd ;
        MEMP((ADDRESS_A*DIPAW + DIPAW_1) downto (ADDRESS_A*DIPAW)) := DIPA_ipd ;
    end if;

    if (WR_B_LATER = TRUE ) then

        MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := DIB_ipd;
        MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (ADDRESS_B*DIPBW)) := DIPB_ipd;
    end if;

    if (WR_A_LATER AND WR_B_LATER ) then
        COLLISION (ADDRB_ipd, OLP_LSB, OLP_MSB, "write", "port B", "port A", InstancePath, MEM);
        COLLISION (ADDRB_ipd, OLPP_LSB, OLPP_MSB, "write", "port B", "port A", InstancePath, MEMP);
    end if;

    DOA_zd(7)  := Violation XOR DOA_zd(7);
    DOA_zd(6)  := Violation XOR DOA_zd(6);
    DOA_zd(5)  := Violation XOR DOA_zd(5);
    DOA_zd(4)  := Violation XOR DOA_zd(4);
    DOA_zd(3)  := Violation XOR DOA_zd(3);
    DOA_zd(2)  := Violation XOR DOA_zd(2);
    DOA_zd(1)  := Violation XOR DOA_zd(1);
    DOA_zd(0)  := Violation XOR DOA_zd(0);
    DOPA_zd(0)  := Violation XOR DOPA_zd(0);
    DOB_zd(7)  := Violation XOR DOB_zd(7);
    DOB_zd(6)  := Violation XOR DOB_zd(6);
    DOB_zd(5)  := Violation XOR DOB_zd(5);
    DOB_zd(4)  := Violation XOR DOB_zd(4);
    DOB_zd(3)  := Violation XOR DOB_zd(3);
    DOB_zd(2)  := Violation XOR DOB_zd(2);
    DOB_zd(1)  := Violation XOR DOB_zd(1);
    DOB_zd(0)  := Violation XOR DOB_zd(0);
    DOPB_zd(0)  := Violation XOR DOPB_zd(0);


    ----------------------
    --  Path Delay Section
    ----------------------

    VitalPathDelay01 (
      OutSignal => DOA(7),
      GlitchData => DOA_GlitchData7,
      OutSignalName => "DOA(7)",
      OutTemp => DOA_zd(7),
      Paths => (0 => (CLKA_ipd'last_event,  tpd_CLKA_DOA(7),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOA(6),
      GlitchData => DOA_GlitchData6,
      OutSignalName => "DOA(6)",
      OutTemp => DOA_zd(6),
      Paths => (0 => (CLKA_ipd'last_event,  tpd_CLKA_DOA(6),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOA(5),
      GlitchData => DOA_GlitchData5,
      OutSignalName => "DOA(5)",
      OutTemp => DOA_zd(5),
      Paths => (0 => (CLKA_ipd'last_event,  tpd_CLKA_DOA(5),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOA(4),
      GlitchData => DOA_GlitchData4,
      OutSignalName => "DOA(4)",
      OutTemp => DOA_zd(4),
      Paths => (0 => (CLKA_ipd'last_event,  tpd_CLKA_DOA(4),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOA(3),
      GlitchData => DOA_GlitchData3,
      OutSignalName => "DOA(3)",
      OutTemp => DOA_zd(3),
      Paths => (0 => (CLKA_ipd'last_event,  tpd_CLKA_DOA(3),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DOA(2),
      GlitchData => DOA_GlitchData2,
      OutSignalName => "DOA(2)",    
      OutTemp => DOA_zd(2),  
      Paths => (0 => (CLKA_ipd'last_event,  tpd_CLKA_DOA(2),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DOA(1),
      GlitchData => DOA_GlitchData1,
      OutSignalName => "DOA(1)",    
      OutTemp => DOA_zd(1),  
      Paths => (0 => (CLKA_ipd'last_event,  tpd_CLKA_DOA(1),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DOA(0),
      GlitchData => DOA_GlitchData0,
      OutSignalName => "DOA(0)",    
      OutTemp => DOA_zd(0),  
      Paths => (0 => (CLKA_ipd'last_event,  tpd_CLKA_DOA(0),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DOPA(0),
      GlitchData => DOPA_GlitchData0,
      OutSignalName => "DOPA(0)",    
      OutTemp => DOPA_zd(0),  
      Paths => (0 => (CLKA_ipd'last_event,  tpd_CLKA_DOPA(0),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(7),
      GlitchData => DOB_GlitchData7,
      OutSignalName => "DOB(7)",
      OutTemp => DOB_zd(7),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(7),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(6),
      GlitchData => DOB_GlitchData6,
      OutSignalName => "DOB(6)",
      OutTemp => DOB_zd(6),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(6),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(5),
      GlitchData => DOB_GlitchData5,
      OutSignalName => "DOB(5)",
      OutTemp => DOB_zd(5),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(5),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(4),
      GlitchData => DOB_GlitchData4,
      OutSignalName => "DOB(4)",
      OutTemp => DOB_zd(4),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(4),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
