      GlitchData => DOB_GlitchData2,
      OutSignalName => "DOB(2)",    
      OutTemp => DOB_zd(2),  
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(2),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DOB(1),
      GlitchData => DOB_GlitchData1,
      OutSignalName => "DOB(1)",    
      OutTemp => DOB_zd(1),  
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(1),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
