    VitalPathDelay01 (   
      OutSignal => DOB(0),
      GlitchData => DOB_GlitchData0,
      OutSignalName => "DOB(0)",    
      OutTemp => DOB_zd(0),  
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(0),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DOPB(0),
      GlitchData => DOPB_GlitchData0,
      OutSignalName => "DOPB(0)",    
      OutTemp => DOPB_zd(0),  
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOPB(0),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    wait on CLKA_ipd, CLKB_ipd, WEA_ipd, WEB_ipd, ENA_ipd, ENB_ipd, 
            SSRA_ipd, SSRB_ipd, DIA_ipd, DIB_ipd, DIPA_ipd, DIPB_ipd, 
            ADDRA_ipd, ADDRB_ipd;

  end process VITALBehavior;

end RAMB16_S9_S9_V;

