  WireDelay : block
  begin
    VitalWireDelay (ADDR_ipd(0),  ADDR(0),  tipd_ADDR(0));
    VitalWireDelay (ADDR_ipd(1),  ADDR(1),  tipd_ADDR(1));
    VitalWireDelay (ADDR_ipd(2),  ADDR(2),  tipd_ADDR(2));
