          TestSignal              => CLKA_ipd,
          TestSignalName          => "CLKA",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_CLKA_posedge,
          PulseWidthLow           => tpw_CLKA_negedge,
          CheckEnabled            => TO_X01(ENA_ipd) = '1',
          HeaderMsg               => InstancePath &"/RAMB4_S8_S16",
          Xon                     => Xon,
