----- CELL ROC -----
-----------------------------------------------------------------------------
-- Model for  Reset-On-Configuration Cell
--
-- Version 1.0.1
--
-- Dhimant Patel, August 22, 1996.

-- Version 1.0.2, DP, 06/18/97
-- 1. Incorporated error checking to ensure that WIDTH > 0 ns.
-----------------------------------------------------------------------------
library IEEE;
use IEEE.std_logic_1164.all;
use IEEE.VITAL_Timing.all;

entity ROC is
    generic ( InstancePath: STRING := "*";
              WIDTH : Time := 100 ns);
    port( O : out std_ulogic := '1' );
    attribute VITAL_LEVEL0 of ROC : entity is TRUE;
end ROC;

architecture ROC_V of ROC is
attribute VITAL_LEVEL0 of ROC_V : architecture is TRUE;
begin
    ONE_SHOT: process
    begin
        if (WIDTH <= 0 ns) then
            assert FALSE report
            "*** Error: a positive value of WIDTH must be specified ***"
            severity failure;
        else
            wait for WIDTH;
            O <= '0';
        end if;
        wait;
    end process ONE_SHOT;
end ROC_V;

configuration CFG_ROC_V of ROC is
    for ROC_V
    end for;
end CFG_ROC_V;
----- CELL ROCBUF -----
-----------------------------------------------------------------------------
-- Model for ROCBUF Cell
--
-- Version 1.0.1
--
-- Dhimant Patel, August 22, 1996.

-- Version 1.0.2, DP, 06/18/97
-- 1. Incorporated error checking to ensure that WIDTH > 0 ns.

-- Version 1.0.3, DP, 09/25/97
-- 1. Changed model from one incorporating a ROC cell and OR2 to a simple
--    buffer.
-----------------------------------------------------------------------------
library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.VITAL_Timing.all;

entity ROCBUF is
    generic(
      InstancePath: STRING := "*";
      Xon: Boolean := True;
      MsgOn: Boolean := False;
      tpd_I_O                        :  VitalDelayType01 := (0.100 ns, 0.100 ns);
      tipd_I                         :  VitalDelayType01 := (0.000 ns, 0.000 ns));

    port( I : in  std_ulogic;
          O : out std_ulogic );
    attribute VITAL_LEVEL0 of ROCBUF : entity is TRUE;
end ROCBUF;

architecture ROCBUF_V of ROCBUF is

attribute VITAL_LEVEL1 of ROCBUF_V : architecture is TRUE;

   SIGNAL I_ipd  : STD_ULOGIC := 'X';

begin

   ---------------------
   --  INPUT PATH DELAYs
   ---------------------
   WireDelay : block
   begin
   VitalWireDelay (I_ipd, I, tipd_I);
   end block;
   --------------------
   --  BEHAVIOR SECTION
   --------------------
   VITALBehavior : process (I_ipd)
 
 
   -- functionality results
   VARIABLE O_zd : STD_ULOGIC := 'X';
 
   -- output glitch detection variables
   VARIABLE O_GlitchData        : VitalGlitchDataType;
 
   begin
 
      -------------------------
      --  Functionality Section
      -------------------------
      O_zd := TO_X01(I_ipd);

      ----------------------
      --  Path Delay Section
      ----------------------
      VitalPathDelay01 (
       OutSignal => O,
       GlitchData => O_GlitchData,
       OutSignalName => "O",
       OutTemp => O_zd,
       Paths => (0 => (I_ipd'last_event, tpd_I_O, TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);
 
    end process;

end ROCBUF_V;

configuration CFG_ROCBUF_V of ROCBUF is
   for ROCBUF_V
   end for;
end CFG_ROCBUF_V;
