------------------------------------------
--
--  Xilinx ROM16X1 VITAL model
--
--  Dhimant Patel, July, 1996.
-----------------------------------------
library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.STD_LOGIC_UNSIGNED.all;
use IEEE.VITAL_Timing.all;
use IEEE.VITAL_Primitives.all;

library UNISIM;
use UNISIM.VPKG.all;

entity ROM16X1 is

  generic (
       TimingChecksOn: Boolean := TRUE;
       InstancePath:   STRING  := "*";
       Xon:  Boolean := True;
       MsgOn:  Boolean := False;

       -- VITAL input wire delays

       tipd_A0   : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_A1   : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_A2   : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_A3   : VitalDelayType01 := ( 0.0 ns,  0.0 ns);

       -- VITAL pin-to-pin propagation delays

       tpd_A0_O   : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A1_O   : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A2_O   : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A3_O   : VitalDelayType01 := (0.1 ns, 0.1 ns);

       INIT : bit_vector := X"0000"
  );

  port (A0 : in std_ulogic;
        A1 : in std_ulogic;
        A2 : in std_ulogic;
        A3 : in std_ulogic;

        O : out std_ulogic
       ); 
attribute VITAL_LEVEL0 of ROM16X1 : entity is TRUE;

end ROM16X1;

-----------------------------------------------------------------------------

architecture ROM16X1_V of ROM16X1 is

  attribute VITAL_LEVEL0 of ROM16X1_V : architecture is TRUE;

  -- Local signals used to propagate input wire delay
 
  signal A0_ipd   : std_ulogic := 'X';
  signal A1_ipd   : std_ulogic := 'X';
  signal A2_ipd   : std_ulogic := 'X';
  signal A3_ipd   : std_ulogic := 'X';

 
begin -- architecture

  ----------------------
  --  Wire Delay Section
  ----------------------
  WireDelay : block
  begin
    VitalWireDelay (A0_ipd,     A0,     tipd_A0);
    VitalWireDelay (A1_ipd,     A1,     tipd_A1);
    VitalWireDelay (A2_ipd,     A2,     tipd_A2);
    VitalWireDelay (A3_ipd,     A3,     tipd_A3);
  end block;

  -------------------
  -- ROM16X1 behavior
  -------------------
  VITALBehavior : process (A3_ipd, A2_ipd, A1_ipd, A0_ipd)

    -- Local variables used for functionality
    variable INIT_BITS : std_logic_vector(15 downto 0) := To_StdLogicVector(INIT);
    variable MEM : std_logic_vector( 16 downto 0 ) := ('X' & INIT_BITS(15 downto 0));
    variable Index : integer := 16;
    variable O_zd : std_ulogic := 'X';
    variable O_GlitchData : VitalGlitchDataType;

  begin -- process
 
    -------------------------
    --  Functionality Section
    -------------------------

    Index := DECODE_ADDR4(ADDRESS => (A3_ipd, A2_ipd, A1_ipd, A0_ipd));

    O_zd := MEM(Index);

    ----------------------
    --  Path Delay Section
    ----------------------
    VitalPathDelay01 (
      OutSignal => O,
      GlitchData => O_GlitchData,
      OutSignalName => "O",
      OutTemp => O_zd,
      Paths => (0 => (A0_ipd'last_event, tpd_A0_O, TRUE),
                1 => (A1_ipd'last_event, tpd_A1_O, TRUE),
                2 => (A2_ipd'last_event, tpd_A2_O, TRUE),
                3 => (A3_ipd'last_event, tpd_A3_O, TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

  end process VITALBehavior;
 
end ROM16X1_V;

configuration CFG_ROM16X1_V of ROM16X1 is
   for ROM16X1_V
   end for;
end CFG_ROM16X1_V;
