    end if;

    if (CLK_ipd'event AND CLK_ipd'last_value = '1') then
        if (CLK_ipd = '0') then
                    for I in 15 downto 1 loop
                        SHIFT_REG(I) <= SHIFT_REG(I-1);
                    end loop;
