    if (CLK_ipd'event AND CLK_ipd'last_value = '0') then
        if (CLK_ipd = '1') then
            if (CE_ipd = '1') then
                    for I in 15 downto 1 loop
                        SHIFT_REG(I) <= SHIFT_REG(I-1);
                    end loop;
                SHIFT_REG(0) <= D_ipd;
            elsif (CE_ipd = 'X') then
