        elsif (CLK_ipd = 'X') then
            if (CE_ipd /= '0') then
                SHIFT_REG <= (others => 'X');
           end if;
        end if;
    elsif (CLK_ipd'event AND CLK_ipd'last_value = 'X') then
        if (CLK_ipd = '1') then
            if (CE_ipd /= '0') then
