       tipd_A0   : VitalDelayType01 := (0.0 ns,  0.0 ns);
       tipd_A1   : VitalDelayType01 := (0.0 ns,  0.0 ns);
       tipd_A2   : VitalDelayType01 := (0.0 ns,  0.0 ns);
       tipd_A3   : VitalDelayType01 := (0.0 ns,  0.0 ns);

       tipd_D    : VitalDelayType01 := (0.0 ns,  0.0 ns);
       tipd_CE   : VitalDelayType01 := (0.0 ns,  0.0 ns);
       tipd_CLK  : VitalDelayType01 := (0.0 ns,  0.0 ns);

       -- VITAL pin-to-pin propagation delays

       tpd_A0_Q  : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A1_Q  : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A2_Q  : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A3_Q  : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_CLK_Q : VitalDelayType01 := (0.1 ns, 0.1 ns);

       tpd_A0_Q15  : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A1_Q15  : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A2_Q15  : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_A3_Q15  : VitalDelayType01 := (0.1 ns, 0.1 ns);
       tpd_CLK_Q15 : VitalDelayType01 := (0.1 ns, 0.1 ns);

       -- VITAL setup and hold times

       tsetup_CE_CLK_posedge_negedge : VitalDelayType := 0.01 ns;
       tsetup_CE_CLK_negedge_negedge : VitalDelayType := 0.01 ns;
       tsetup_D_CLK_posedge_negedge  : VitalDelayType := 0.01 ns;
       tsetup_D_CLK_negedge_negedge  : VitalDelayType := 0.01 ns;

       thold_CE_CLK_posedge_negedge  : VitalDelayType := 0.01 ns;
       thold_CE_CLK_negedge_negedge  : VitalDelayType := 0.01 ns;
       thold_D_CLK_posedge_negedge   : VitalDelayType := 0.01 ns;
       thold_D_CLK_negedge_negedge   : VitalDelayType := 0.01 ns;

       -- VITAL minimum pulse width

       tpw_CLK_posedge : VitalDelayType := 0.01 ns;
       tpw_CLK_negedge : VitalDelayType := 0.01 ns;

       INIT : bit_vector := X"0000"
  );

  port (D   : in STD_ULOGIC;
        CE  : in STD_ULOGIC;
        CLK : in STD_ULOGIC;
        A0  : in STD_ULOGIC;
        A1  : in STD_ULOGIC;
        A2  : in STD_ULOGIC;
        A3  : in STD_ULOGIC;
        Q   : out STD_ULOGIC;
        Q15   : out STD_ULOGIC
       ); 

attribute VITAL_LEVEL0 of SRLC16E_1 : entity is TRUE;

end SRLC16E_1;

-----------------------------------------------------------------------------

architecture SRLC16E_1_V of SRLC16E_1 is

  attribute VITAL_LEVEL0 of SRLC16E_1_V : architecture is TRUE;

  -- Local signals used to propagate input wire delay

  signal A0_ipd  : std_ulogic := 'X';
  signal A1_ipd  : std_ulogic := 'X';
  signal A2_ipd  : std_ulogic := 'X';
  signal A3_ipd  : std_ulogic := 'X';

  signal D_ipd   : std_ulogic := 'X';
  signal CE_ipd  : std_ulogic := 'X';
  signal CLK_ipd : std_ulogic := 'X';

  signal Q_zd    : std_ulogic := 'X';
  signal Q15_zd    : std_ulogic := 'X';
signal SHIFT_REG : std_logic_vector (16 downto 0) := ('X' & To_StdLogicVector( INIT));

 
begin -- architecture

  ----------------------
  --  Wire Delay Section
  ----------------------
  WireDelay : block
  begin
    VitalWireDelay (A0_ipd,   A0,  tipd_A0);
    VitalWireDelay (A1_ipd,   A1,  tipd_A1);
    VitalWireDelay (A2_ipd,   A2,  tipd_A2);
    VitalWireDelay (A3_ipd,   A3,  tipd_A3);

    VitalWireDelay (D_ipd,    D,   tipd_D);
    VitalWireDelay (CE_ipd,   CE,  tipd_CE);
    VitalWireDelay (CLK_ipd,  CLK, tipd_CLK);
  end block;

  --------------------
  -- SRLC16E_1 Behavior
  --------------------
  VITALReadBehavior : process(A0_ipd, A1_ipd, A2_ipd, A3_ipd, SHIFT_REG)

    -- Local variables used for functionality
    variable ADDR : std_logic_vector(3 downto 0);
    variable VALID_ADDR : boolean := FALSE;
    variable LENGTH : integer;

  begin -- process

    ADDR := (A3_ipd, A2_ipd, A1_ipd, A0_ipd);
    VALID_ADDR := ADDR_IS_VALID(SLV => ADDR);

    if (VALID_ADDR) then
        LENGTH := SLV_TO_INT(SLV => ADDR);
    else
        LENGTH := 16;
    end if;
    Q_zd <= SHIFT_REG(LENGTH);
    Q15_zd <= SHIFT_REG(15);

  end process VITALReadBehavior;

  VITALWriteBehavior : process

    variable FIRST_TIME : boolean := TRUE;


  begin -- process

    if (FIRST_TIME) then
        wait until ((CE_ipd = '1' or CE_ipd = '0') and 
                   (CLK_ipd'last_value = '0' or CLK_ipd'last_value = '1') and
                   (CLK_ipd = '0' or CLK_ipd = '1'));
        FIRST_TIME := FALSE;
    end if;


    -------------------------
    --  Functionality Section
    -------------------------

    if (CLK_ipd'event AND CLK_ipd'last_value = '1') then
        if (CLK_ipd = '0') then
            if (CE_ipd = '1') then
                    for I in 15 downto 1 loop
                        SHIFT_REG(I) <= SHIFT_REG(I-1);
                    end loop;
                SHIFT_REG(0) <= D_ipd;
            elsif (CE_ipd = 'X') then
                SHIFT_REG <= (others => 'X');
            end if;
        elsif (CLK_ipd = 'X') then
            if (CE_ipd /= '0') then
                SHIFT_REG <= (others => 'X');
            end if;
        end if;
    elsif (CLK_ipd'event AND CLK_ipd'last_value = 'X') then
        if (CLK_ipd = '0') then
            if (CE_ipd /= '0') then
                SHIFT_REG <= (others => 'X');
            end if;
        end if;
    end if;

    wait on CLK_ipd;

  end process VITALWriteBehavior;


    ------------------------
    --  Timing Check Section
    ------------------------
  VITALTiming : process (A0_ipd, A1_ipd, A2_ipd, A3_ipd, CLK_ipd, CE_ipd, D_ipd, Q_zd, Q15_zd)

    -- Local variables used for timing checks
    variable Tviol_D_CLK_negedge  : std_ulogic := '0';
    variable Tviol_CE_CLK_negedge : std_ulogic := '0';

    variable Tmkr_D_CLK_negedge   : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_CE_CLK_negedge  : VitalTimingDataType := VitalTimingDataInit;
 
    variable PViol_CLK : std_ulogic := '0';
    variable PInfo_CLK : VitalPeriodDataType := VitalPeriodDataInit;
    variable Violation : std_ulogic := '0';
    variable Q_zdt : std_ulogic := '0';
    variable Q_GlitchData : VitalGlitchDataType;
    variable Q15_zdt : std_ulogic := '0';
    variable Q15_GlitchData : VitalGlitchDataType;

   begin

    Q_zdt := Q_zd;
    Q15_zdt := Q15_zd;

    if (TimingChecksOn) then

         VitalSetupHoldCheck (
          Violation               => Tviol_D_CLK_negedge,
          TimingData              => Tmkr_D_CLK_negedge,
          TestSignal              => D_ipd,
          TestSignalName          => "D",
          TestDelay               => 0 ns,
          RefSignal               => CLK_ipd,
          RefSignalName           => "CLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_D_CLK_posedge_negedge,
          SetupLow                => tsetup_D_CLK_negedge_negedge,
          HoldHigh                => thold_D_CLK_posedge_negedge,
          HoldLow                 => thold_D_CLK_negedge_negedge,
          CheckEnabled            => (TO_X01(CE_ipd) = '1'),
          RefTransition           => 'F',
          HeaderMsg               => InstancePath & "/SRLC16E_1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_CE_CLK_negedge,
          TimingData              => Tmkr_CE_CLK_negedge,
          TestSignal              => CE_ipd,
          TestSignalName          => "CE",
          TestDelay               => 0 ns,
          RefSignal               => CLK_ipd,
          RefSignalName           => "CLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_CE_CLK_posedge_negedge,
          SetupLow                => tsetup_CE_CLK_negedge_negedge,
          HoldHigh                => thold_CE_CLK_posedge_negedge,
          HoldLow                 => thold_CE_CLK_negedge_negedge,
          CheckEnabled            => TRUE,
          RefTransition           => 'F',
          HeaderMsg               => InstancePath & "/SRLC16E_1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

         VitalPeriodPulseCheck (
          Violation               => Pviol_CLK,
          PeriodData              => PInfo_CLK,
          TestSignal              => CLK_ipd,
          TestSignalName          => "CLK",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_CLK_posedge,
          PulseWidthLow           => tpw_CLK_negedge,
          CheckEnabled            => TRUE,
          HeaderMsg               => InstancePath &"/SRLC16E_1",
          Xon                     => Xon,
          MsgOn                   => MsgOn,
          MsgSeverity             => WARNING);

    end if;

    Violation := Tviol_D_CLK_negedge or Tviol_CE_CLK_negedge or
                 Pviol_CLK;

    Q_zdt := Violation XOR Q_zdt;
    Q15_zdt := Violation XOR Q15_zdt;

    ----------------------
    --  Path Delay Section
    ----------------------
    VitalPathDelay01 (
      OutSignal => Q,
      GlitchData => Q_GlitchData,
      OutSignalName => "Q",
      OutTemp => Q_zdt,
      Paths => (0 => (CLK_ipd'last_event, tpd_CLK_Q, TRUE),
                1 => (A0_ipd'last_event,  tpd_A0_Q,  TRUE),
                2 => (A1_ipd'last_event,  tpd_A1_Q,  TRUE),
                3 => (A2_ipd'last_event,  tpd_A2_Q,  TRUE),
                4 => (A3_ipd'last_event,  tpd_A3_Q,  TRUE)),
      Mode => VitalInertial,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => Q15,
      GlitchData => Q15_GlitchData,
      OutSignalName => "Q15",
      OutTemp => Q15_zdt,
      Paths => (0 => (CLK_ipd'last_event, tpd_CLK_Q15, TRUE),
                1 => (A0_ipd'last_event,  tpd_A0_Q15,  TRUE),
                2 => (A1_ipd'last_event,  tpd_A1_Q15,  TRUE),
                3 => (A2_ipd'last_event,  tpd_A2_Q15,  TRUE),
                4 => (A3_ipd'last_event,  tpd_A3_Q15,  TRUE)),
      Mode => VitalInertial,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

  end process VITALTiming;

end SRLC16E_1_V;

configuration CFG_SRLC16E_1_V of SRLC16E_1 is
   for SRLC16E_1_V
   end for;
end CFG_SRLC16E_1_V;
----- CELL STARTBUF -----
-----------------------------------------------------------------------------
-- Model for STARTBUF Cell
--
-- Version 1.0.1
--
-- Dhimant Patel, August 22, 1996.

-- Version 1.0.2, DP, 06/18/97
-- 1. Incorporated error checking to ensure that WIDTH > 0 ns.
-- Version 1.0.2, DP, 06/18/97

-- Version 1.1.0, DP, 08/11/97
-- 1. Modified model to have 3 input and 5 output ports, as well as 2 width
--    generics.

-- Version 1.1.1, DP, 09/25/97
-- 1. Changed model from one incorporating ROC, TOC and 2 OR2s to one
--    incorporating 2 buffers.
-----------------------------------------------------------------------------
library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.VITAL_Timing.all;

entity STARTBUF is
    generic ( 
      InstancePath: STRING := "*";
      Xon: Boolean := True;
      MsgOn: Boolean := False;
      tpd_GSRIN_GSROUT               :  VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_GTSIN_GTSOUT               :  VitalDelayType01 := (0.100 ns, 0.100 ns);
      tipd_GSRIN                     :  VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_GTSIN                     :  VitalDelayType01 := (0.000 ns, 0.000 ns));

    port( GSRIN     : in std_ulogic;
          GTSIN     : in std_ulogic;
          CLKIN     : in std_ulogic;
          GSROUT    : out std_ulogic;
          GTSOUT    : out std_ulogic;
          Q2OUT     : out std_ulogic := 'H';
          Q3OUT     : out std_ulogic := 'H';
          Q1Q4OUT   : out std_ulogic := 'H';
          DONEINOUT : out std_ulogic := 'H');
    attribute VITAL_LEVEL0 of STARTBUF : entity is TRUE;
end STARTBUF;

architecture STARTBUF_V of STARTBUF is

attribute VITAL_LEVEL0 of STARTBUF_V : architecture is TRUE;

   SIGNAL GSRIN_ipd, GTSIN_ipd  : STD_ULOGIC := 'X';

begin

   Q2OUT     <= 'H';
   Q3OUT     <= 'H';
   Q1Q4OUT   <= 'H';
   DONEINOUT <= 'H';

   ---------------------
   --  INPUT PATH DELAYs
   ---------------------
   WireDelay : block
   begin
     VitalWireDelay (GSRIN_ipd, GSRIN, tipd_GSRIN);
     VitalWireDelay (GTSIN_ipd, GTSIN, tipd_GTSIN);
   end block;
   --------------------
   --  BEHAVIOR SECTION
   --------------------
   VITALBehavior : process (GSRIN_ipd, GTSIN_ipd)
 
 
   -- functionality results
   VARIABLE GSR_zd, GTS_zd : STD_ULOGIC := 'X';
 
   -- output glitch detection variables
   VARIABLE GSR_GlitchData, GTS_GlitchData : VitalGlitchDataType;
 
   begin
 
      -------------------------
      --  Functionality Section
      -------------------------
      GSR_zd    := TO_X01(GSRIN_ipd);
      GTS_zd    := TO_X01(GTSIN_ipd);
 
      ----------------------
      --  Path Delay Section
      ----------------------
      VitalPathDelay01 (
       OutSignal => GSROUT,
       GlitchData => GSR_GlitchData,
       OutSignalName => "GSR",
       OutTemp => GSR_zd,
       Paths => (0 => (GSRIN_ipd'last_event, tpd_GSRIN_GSROUT, TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);

      VitalPathDelay01 ( 
       OutSignal => GTSOUT, 
       GlitchData => GTS_GlitchData,
       OutSignalName => "GTSOUT",
       OutTemp => GTS_zd,
       Paths => (0 => (GTSIN_ipd'last_event, tpd_GTSIN_GTSOUT, TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);

 
    end process;

end STARTBUF_V;

configuration CFG_STARTBUF_V of STARTBUF is
   for STARTBUF_V
   end for;
end CFG_STARTBUF_V;
