----- CELL TOC -----
-----------------------------------------------------------------------------
-- Model for Tristate-On-Configuration Cell
--
-- Version 1.0.1
--
-- Dhimant Patel, 06/18/97
-----------------------------------------------------------------------------
library IEEE;
use IEEE.std_logic_1164.all;
use IEEE.VITAL_Timing.all;

entity TOC is
    generic ( InstancePath: STRING := "*";
              WIDTH : Time := 100 ns);
    port( O : out std_ulogic := '0' );
    attribute VITAL_LEVEL0 of TOC : entity is TRUE;
end TOC;

architecture TOC_V of TOC is
attribute VITAL_LEVEL0 of TOC_V : architecture is TRUE;
begin
    ONE_SHOT: process
    begin
        O <= '1';
        if (WIDTH <= 0 ns) then
            O <= '0';
        else
            wait for WIDTH;
            O <= '0';
        end if;
        wait;
    end process ONE_SHOT;
end TOC_V;

configuration CFG_TOC_V of TOC is
    for TOC_V
    end for;
end CFG_TOC_V;
----- CELL TOCBUF -----
-----------------------------------------------------------------------------
-- Model for TOCBUF Cell
--
-- Version 1.0.1
--
-- Dhimant Patel, August 22, 1996.

-- Version 1.0.2, DP, 06/18/97
-- 1. Incorporated error checking to ensure that WIDTH > 0 ns.

-- Version 1.0.3, DP, 09/25/97
-- 1. Changed model from one incorporating a ROC cell and OR2 to a simple
--    buffer.
-----------------------------------------------------------------------------
library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.VITAL_Timing.all;

entity TOCBUF is
    generic(
      InstancePath: STRING := "*";
      Xon: Boolean := True;
      MsgOn: Boolean := False;
      tpd_I_O                        :  VitalDelayType01 := (0.100 ns, 0.100 ns);
      tipd_I                         :  VitalDelayType01 := (0.000 ns, 0.000 ns));

    port( I : in  std_ulogic;
          O : out std_ulogic );
    attribute VITAL_LEVEL0 of TOCBUF : entity is TRUE;
end TOCBUF;

architecture TOCBUF_V of TOCBUF is

attribute VITAL_LEVEL1 of TOCBUF_V : architecture is TRUE;
 
   SIGNAL I_ipd  : STD_ULOGIC := 'X';
 
begin
 
   ---------------------
   --  INPUT PATH DELAYs
   ---------------------
   WireDelay : block
   begin
   VitalWireDelay (I_ipd, I, tipd_I);
   end block;
   --------------------
   --  BEHAVIOR SECTION
   --------------------
   VITALBehavior : process (I_ipd)
 
 
   -- functionality results
   VARIABLE O_zd : STD_ULOGIC := 'X';
 
   -- output glitch detection variables
   VARIABLE O_GlitchData        : VitalGlitchDataType;
 
   begin
 
      -------------------------
      --  Functionality Section
      -------------------------
      O_zd := TO_X01(I_ipd);

      ----------------------
      --  Path Delay Section
      ----------------------
      VitalPathDelay01 (
       OutSignal => O,
       GlitchData => O_GlitchData,
       OutSignalName => "O",
       OutTemp => O_zd,
       Paths => (0 => (I_ipd'last_event, tpd_I_O, TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);
 
    end process;
 
end TOCBUF_V;
 
configuration CFG_TOCBUF_V of TOCBUF is
   for TOCBUF_V
   end for;
end CFG_TOCBUF_V;
